import * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import type * as Redacted from "effect/Redacted";
import { isResolved } from "../Diff.ts";
import * as Provider from "../Provider.ts";
import { Resource } from "../Resource.ts";
import { arrayEqualsUnordered } from "../Util/equal.ts";
import type { Account } from "./Account.ts";
import {
  accountLayer,
  issueCertificate,
  revokeCertificate,
  type AccountCredentials,
} from "./Client.ts";
import type { PropagationOptions } from "./Dns.ts";
import { resolveDnsSolver, type DnsSolverDescriptor } from "./DnsSolver.ts";
import type { KeyAlgorithm } from "./Pki.ts";
import type { Providers } from "./Providers.ts";

export interface CertificateProps {
  /** The {@link Account} that orders the certificate. Changing it replaces. */
  account: Account;
  /**
   * DNS names the certificate covers. The first is the subject CN;
   * wildcards (`*.example.com`) are allowed. Changing the set re-issues.
   */
  identifiers: string[];
  /**
   * How `_acme-challenge` TXT records are published, e.g.
   * `Cloudflare.DNS.AcmeSolver(zone)`. Changing the solver alone does not
   * re-issue.
   */
  solver: DnsSolverDescriptor;
  /**
   * Certificate key algorithm. Changing it re-issues the certificate.
   * @default "ES256"
   */
  keyAlgorithm?: KeyAlgorithm;
  /**
   * Re-issue when less than this remains before `notAfter`. Renewal is a
   * `diff` result, so any `alchemy deploy` (a scheduled one, typically)
   * renews.
   * @default "30 days"
   */
  renewBefore?: Duration.Input;
  /**
   * Revoke the certificate at the CA when the resource is deleted. By
   * default deletion only forgets the certificate.
   * @default false
   */
  revokeOnDelete?: boolean;
  /**
   * Issuer name to prefer (`CN=…` substring, e.g. `ISRG Root X1`) when the
   * CA offers alternate chains.
   */
  preferredChain?: string;
  /** DNS propagation polling (resolvers, timeout, interval). */
  propagation?: PropagationOptions;
}

export interface Certificate extends Resource<
  "ACME.Certificate",
  CertificateProps,
  {
    /** Leaf certificate PEM. */
    certificate: string;
    /** Full chain PEM, leaf first. */
    chain: string;
    /** PKCS#8 private key PEM. Sensitive; persisted in stack state. */
    privateKey: Redacted.Redacted<string>;
    /** Serial number, hex. */
    serial: string;
    /** ISO 8601 validity start. */
    notBefore: string;
    /** ISO 8601 expiry. Renewal is scheduled against it. */
    notAfter: string;
    /** Issuer distinguished name. */
    issuer: string;
    /** The DNS names covered. */
    identifiers: string[];
    /** The CA's certificate URL. */
    certificateUrl: string;
    /** The CA's order URL. */
    orderUrl: string;
    /** Key algorithm of `privateKey`. */
    keyAlgorithm: KeyAlgorithm;
    /** The account that issued the certificate. */
    accountUrl: string;
    /** The CA the certificate was issued by (for revocation on delete). */
    directoryUrl: string;
    /** PEM root trusted for the CA's endpoint (private CAs only). */
    trustedRoot: string | undefined;
  },
  never,
  Providers
> {}

/**
 * A TLS certificate issued over ACME at deploy time, with renewal.
 *
 * Reconcile places an order, proves control of every name over DNS-01
 * through the `solver`, finalizes with a fresh key's CSR and stores the
 * chain and redacted private key in state. Protect the state store as
 * secret material. `diff` reports an update when the
 * names change or when `renewBefore` of validity remains, so a scheduled
 * `alchemy deploy` keeps certificates fresh.
 *
 * ### Wildcard certificate
 * **Example:** Let's Encrypt wildcard over Cloudflare DNS
 * ```typescript
 * const account = yield* ACME.Account("Issuer", {
 *   ca: ACME.LetsEncrypt,
 *   termsOfServiceAgreed: true,
 * });
 * const zone = yield* Zone;
 * const wildcard = yield* ACME.Certificate("Wildcard", {
 *   account,
 *   identifiers: ["*.example.com", "example.com"],
 *   solver: Cloudflare.DNS.AcmeSolver(zone),
 * });
 * ```
 *
 * ### Using the certificate
 * The chain and key are Outputs — pass them to whatever terminates TLS.
 *
 * **Example:** Upload to a Fly App
 * ```typescript
 * const www = yield* Fly.Certificate("Www", {
 *   app: Site,
 *   hostname: "www.example.com",
 *   kind: "custom",
 *   fullchain: wildcard.chain,
 *   privateKey: wildcard.privateKey,
 * });
 * ```
 *
 * ### Renewal
 * **Example:** Renew earlier and revoke on delete
 * ```typescript
 * const api = yield* ACME.Certificate("Api", {
 *   account,
 *   identifiers: ["api.example.com"],
 *   solver: Cloudflare.DNS.AcmeSolver(zone),
 *   renewBefore: "45 days",
 *   revokeOnDelete: true,
 * });
 * ```
 *
 * @resource
 * @product Certificate
 * @category Certificates
 */
export const Certificate = Resource<Certificate>("ACME.Certificate");

type AccountRef = {
  directoryUrl: string;
  trustedRoot?: string | undefined;
  accountUrl: string;
  privateKey: Redacted.Redacted<string>;
};

/** The resolved account attributes behind a resource-valued prop. */
const accountOf = (value: unknown): AccountRef => value as AccountRef;

const credentialsOf = (account: AccountRef): AccountCredentials => ({
  ca: { directoryUrl: account.directoryUrl, trustedRoot: account.trustedRoot },
  accountKey: account.privateKey,
  accountUrl: account.accountUrl,
});

const DEFAULT_RENEW_BEFORE: Duration.Input = "30 days";

const renewalDue = (
  notAfter: string,
  renewBefore: Duration.Input | undefined,
  now: number,
): boolean =>
  Date.parse(notAfter) - now <
  Duration.toMillis(renewBefore ?? DEFAULT_RENEW_BEFORE);

export const CertificateProvider = () =>
  Provider.succeed(Certificate, {
    stables: ["directoryUrl"],

    diff: Effect.fn(function* ({ news, olds, output }) {
      if (news === undefined || !isResolved(news) || output === undefined) {
        return undefined;
      }
      const account = accountOf(news.account);
      if (account.accountUrl !== output.accountUrl) {
        return { action: "replace" as const };
      }
      const now = yield* Effect.sync(() => Date.now());
      const reissue =
        !arrayEqualsUnordered(news.identifiers, output.identifiers) ||
        (news.keyAlgorithm ?? "ES256") !== output.keyAlgorithm ||
        news.preferredChain !== olds?.preferredChain ||
        renewalDue(output.notAfter, news.renewBefore, now);
      return reissue ? { action: "update" as const } : undefined;
    }),

    read: Effect.fn(function* ({ output }) {
      return output;
    }),

    reconcile: Effect.fn(function* ({ news, olds, output }) {
      const account = accountOf(news.account);
      const keyAlgorithm = news.keyAlgorithm ?? "ES256";
      const now = yield* Effect.sync(() => Date.now());
      // Observe: the stored certificate is authoritative — nothing to do
      // while it covers the names and isn't due.
      if (
        output !== undefined &&
        output.accountUrl === account.accountUrl &&
        arrayEqualsUnordered(news.identifiers, output.identifiers) &&
        output.keyAlgorithm === keyAlgorithm &&
        news.preferredChain === olds?.preferredChain &&
        !renewalDue(output.notAfter, news.renewBefore, now)
      ) {
        return {
          ...output,
          directoryUrl: account.directoryUrl,
          trustedRoot: account.trustedRoot,
        };
      }
      const solver = yield* resolveDnsSolver(news.solver);
      const issued = yield* issueCertificate({
        identifiers: news.identifiers,
        solver,
        keyAlgorithm,
        preferredChain: news.preferredChain,
        propagation: news.propagation,
      }).pipe(Effect.provide(accountLayer(credentialsOf(account))));
      return {
        certificate: issued.certificate,
        chain: issued.chain,
        privateKey: issued.privateKey,
        serial: issued.serial,
        notBefore: issued.notBefore,
        notAfter: issued.notAfter,
        issuer: issued.issuer,
        identifiers: [...news.identifiers],
        certificateUrl: issued.certificateUrl,
        orderUrl: issued.orderUrl,
        keyAlgorithm,
        accountUrl: account.accountUrl,
        directoryUrl: account.directoryUrl,
        trustedRoot: account.trustedRoot,
      };
    }),

    delete: Effect.fn(function* ({ olds, output }) {
      if (olds.revokeOnDelete !== true) return;
      const account = accountOf(olds.account);
      // Signed with the certificate's own key, so revocation works even
      // after the account was replaced or deactivated.
      yield* revokeCertificate({
        certificate: output.certificate,
        privateKey: output.privateKey,
        reason: "cessationOfOperation",
      }).pipe(
        Effect.provide(
          accountLayer({
            ca: {
              directoryUrl: output.directoryUrl,
              trustedRoot: output.trustedRoot,
            },
            accountKey: account.privateKey,
            accountUrl: account.accountUrl,
          }),
        ),
      );
    }),
  });

import * as ag from "@distilled.cloud/aws/api-gateway";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Output from "../../Output.ts";
import { registerApiGatewayBinding } from "./BindingHttp.ts";
import {
  DeleteUsagePlanKey,
  type DeleteUsagePlanKeyRequest,
} from "./DeleteUsagePlanKey.ts";
import type { UsagePlan } from "./UsagePlan.ts";

/**
 * HTTP implementation of the {@link DeleteUsagePlanKey} binding. Grants
 * `apigateway:DELETE` on the plan's per-key paths and calls the API with
 * the host Function's credentials.
 */
export const DeleteUsagePlanKeyHttp = Layer.effect(
  DeleteUsagePlanKey,
  Effect.gen(function* () {
    const deleteUsagePlanKey = yield* ag.deleteUsagePlanKey;
    return Effect.fn(function* <P extends UsagePlan>(usagePlan: P) {
      const UsagePlanId = yield* usagePlan.id;
      yield* registerApiGatewayBinding({
        cap: "AWS.ApiGateway.DeleteUsagePlanKey",
        target: usagePlan,
        verb: "DELETE",
        paths: (region) => [
          Output.interpolate`arn:aws:apigateway:${region}::/usageplans/${usagePlan.id}/keys/*`,
        ],
      });
      return Effect.fn(
        `AWS.ApiGateway.DeleteUsagePlanKey(${usagePlan.LogicalId})`,
      )(function* (request: DeleteUsagePlanKeyRequest) {
        return yield* deleteUsagePlanKey({
          ...request,
          usagePlanId: yield* UsagePlanId,
        });
      });
    });
  }),
);

import * as appsignals from "@distilled.cloud/aws/application-signals";
import * as Effect from "effect/Effect";
import { Unowned } from "../../AdoptPolicy.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import type { Providers } from "../Providers.ts";

export interface GroupingConfigurationProps {
  /**
   * The custom grouping attribute definitions for this account. Each
   * definition names a grouping dimension (`GroupingName`), the telemetry
   * attribute or AWS tag keys it is sourced from (`GroupingSourceKeys`,
   * e.g. `"Tag.team"` or an OTel resource attribute key), and an optional
   * `DefaultGroupingValue` used when none of the source keys are present.
   */
  groupingAttributeDefinitions: appsignals.GroupingAttributeDefinition[];
}

export interface GroupingConfiguration extends Resource<
  "AWS.ApplicationSignals.GroupingConfiguration",
  GroupingConfigurationProps,
  {
    /**
     * The grouping attribute definitions as returned by the service.
     */
    groupingAttributeDefinitions: appsignals.GroupingAttributeDefinition[];
    /**
     * When the grouping configuration was last updated (ISO timestamp).
     */
    updatedAt: string | undefined;
  },
  never,
  Providers
> {}

/**
 * The CloudWatch Application Signals grouping configuration for this
 * account — an account-level singleton that defines custom grouping
 * attributes (sourced from telemetry attributes or AWS tags) used to
 * organize and filter discovered services in the Application Signals
 * console and APIs.
 *
 * There is at most ONE grouping configuration per account/region;
 * `PutGroupingConfiguration` replaces the whole definition list.
 *
 * ### Creating a Grouping Configuration
 * **Example:** Group Services by Team Tag
 * ```typescript
 * import * as AWS from "alchemy/AWS";
 *
 * const grouping = yield* AWS.ApplicationSignals.GroupingConfiguration(
 *   "Grouping",
 *   {
 *     groupingAttributeDefinitions: [
 *       {
 *         GroupingName: "Team",
 *         GroupingSourceKeys: ["Tag.team"],
 *         DefaultGroupingValue: "unassigned",
 *       },
 *     ],
 *   },
 * );
 * ```
 *
 * **Example:** Multiple Grouping Dimensions
 * ```typescript
 * const grouping = yield* AWS.ApplicationSignals.GroupingConfiguration(
 *   "Grouping",
 *   {
 *     groupingAttributeDefinitions: [
 *       { GroupingName: "Team", GroupingSourceKeys: ["Tag.team"] },
 *       {
 *         GroupingName: "CostCenter",
 *         GroupingSourceKeys: ["Tag.cost-center", "business_unit"],
 *         DefaultGroupingValue: "shared",
 *       },
 *     ],
 *   },
 * );
 * ```
 *
 * @resource
 */
export const GroupingConfiguration = Resource<GroupingConfiguration>(
  "AWS.ApplicationSignals.GroupingConfiguration",
);

/** Normalize a definition for comparison (drop undefined members). */
const normalizeDefinition = (
  definition: appsignals.GroupingAttributeDefinition,
) => ({
  GroupingName: definition.GroupingName,
  GroupingSourceKeys: definition.GroupingSourceKeys ?? [],
  DefaultGroupingValue: definition.DefaultGroupingValue,
});

const sameDefinitions = (
  desired: appsignals.GroupingAttributeDefinition[],
  observed: appsignals.GroupingAttributeDefinition[],
): boolean =>
  desired.length === observed.length &&
  desired.every(
    (d, i) =>
      JSON.stringify(normalizeDefinition(d)) ===
      JSON.stringify(normalizeDefinition(observed[i])),
  );

export const GroupingConfigurationProvider = () =>
  Provider.effect(
    GroupingConfiguration,
    Effect.gen(function* () {
      /**
       * Observe the account's grouping configuration. The API has no
       * dedicated "get" — an account without a configuration returns an
       * empty definition list and no `UpdatedAt`.
       */
      const observe = appsignals.listGroupingAttributeDefinitions({}).pipe(
        Effect.map((response) =>
          response.UpdatedAt === undefined &&
          response.GroupingAttributeDefinitions.length === 0
            ? undefined
            : {
                groupingAttributeDefinitions: [
                  ...response.GroupingAttributeDefinitions,
                ],
                updatedAt: response.UpdatedAt?.toISOString(),
              },
        ),
      );

      return {
        stables: [],

        read: Effect.fn(function* ({ olds, output }) {
          const observed = yield* observe;
          if (observed === undefined) return undefined;
          // The grouping configuration is not taggable, so ownership cannot
          // be branded. If we have no record of creating it, surface it as
          // an existing-but-foreign singleton so takeover requires --adopt.
          return output !== undefined || olds !== undefined
            ? observed
            : Unowned(observed);
        }),

        reconcile: Effect.fn(function* ({ id, news, session }) {
          const desired = news.groupingAttributeDefinitions;

          // 1. Observe — the live configuration is authoritative.
          const observed = yield* observe;

          // 2/3. Ensure + sync — PutGroupingConfiguration is a full-replace
          // upsert; skip the call when the observed definitions already
          // match the desired ones.
          const fresh =
            observed !== undefined &&
            sameDefinitions(desired, observed.groupingAttributeDefinitions)
              ? observed
              : yield* appsignals
                  .putGroupingConfiguration({
                    GroupingAttributeDefinitions: desired,
                  })
                  .pipe(
                    Effect.map((response) => ({
                      groupingAttributeDefinitions: [
                        ...response.GroupingConfiguration
                          .GroupingAttributeDefinitions,
                      ],
                      updatedAt:
                        response.GroupingConfiguration.UpdatedAt?.toISOString(),
                    })),
                  );

          yield* session.note(id);
          return fresh;
        }),

        delete: Effect.fn(function* () {
          // DeleteGroupingConfiguration is idempotent — deleting an absent
          // configuration succeeds.
          yield* appsignals.deleteGroupingConfiguration({});
        }),

        // Account-level singleton; enumeration happens through read.
        list: () => Effect.succeed([]),
      };
    }),
  );

import * as athena from "@distilled.cloud/aws/athena";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, diffTags } from "../../Tags.ts";
import { AWSEnvironment, type AccountID } from "../Environment.ts";
import type { Providers } from "../Providers.ts";
import type { RegionID } from "../Region.ts";

export type WorkGroupName = string;
export type WorkGroupArn =
  `arn:aws:athena:${RegionID}:${AccountID}:workgroup/${WorkGroupName}`;

export interface WorkGroupProps {
  /**
   * Name of the workgroup. If omitted, a unique name is generated.
   * Changing this replaces the workgroup. Up to 128 characters.
   */
  workGroupName?: string;
  /**
   * Human-readable description of the workgroup.
   */
  description?: string;
  /**
   * S3 URI (`s3://bucket/prefix/`) where query results are written.
   * Applied as the workgroup's `ResultConfiguration.OutputLocation`.
   */
  outputLocation?: string;
  /**
   * Server-side encryption for query results written to S3.
   */
  encryptionOption?: "SSE_S3" | "SSE_KMS" | "CSE_KMS";
  /**
   * KMS key ARN/ID — required when `encryptionOption` is `SSE_KMS` or `CSE_KMS`.
   */
  kmsKey?: string;
  /**
   * Force queries to use this workgroup's result configuration (output
   * location, encryption) instead of client-side settings.
   * @default true
   */
  enforceWorkGroupConfiguration?: boolean;
  /**
   * Per-query data-scanned cutoff in bytes. Queries scanning more are
   * cancelled. Minimum is 10 MB (10_000_000).
   */
  bytesScannedCutoffPerQuery?: number;
  /**
   * Publish per-query CloudWatch metrics for this workgroup.
   * @default false
   */
  publishCloudWatchMetricsEnabled?: boolean;
  /**
   * Charge S3 data-transfer/request costs to the query requester.
   * @default false
   */
  requesterPaysEnabled?: boolean;
  /**
   * Selected Athena engine version (e.g. `"Athena engine version 3"`).
   * If omitted, Athena picks the account default (AUTO).
   */
  engineVersion?: string;
  /**
   * Whether the workgroup accepts queries.
   * @default "ENABLED"
   */
  state?: "ENABLED" | "DISABLED";
  /**
   * User-defined tags to apply to the workgroup.
   */
  tags?: Record<string, string>;
}

export interface WorkGroup extends Resource<
  "AWS.Athena.WorkGroup",
  WorkGroupProps,
  {
    /**
     * Name of the workgroup.
     */
    workGroupName: WorkGroupName;
    /**
     * ARN of the workgroup.
     */
    workGroupArn: WorkGroupArn;
    /**
     * Whether the workgroup accepts queries.
     */
    state: "ENABLED" | "DISABLED";
    /**
     * S3 location query results are written to (`s3://bucket/prefix/`).
     */
    outputLocation: string | undefined;
    /**
     * Tags on the workgroup.
     */
    tags: Record<string, string>;
  },
  never,
  Providers
> {}

/**
 * An Amazon Athena workgroup — an isolation boundary for queries that pins the
 * S3 result-output location, result encryption, a bytes-scanned cutoff, and
 * whether that configuration is enforced over per-query client settings.
 *
 * ### Creating Workgroups
 * **Example:** Workgroup with an enforced result location
 * ```typescript
 * const results = yield* AWS.S3.Bucket("AthenaResults", {});
 * const wg = yield* AWS.Athena.WorkGroup("Analytics", {
 *   outputLocation: results.bucketName.pipe(
 *     Output.map((b) => `s3://${b}/results/`),
 *   ),
 *   enforceWorkGroupConfiguration: true,
 * });
 * ```
 *
 * **Example:** Workgroup with a bytes-scanned cost guardrail
 * ```typescript
 * const wg = yield* AWS.Athena.WorkGroup("Guarded", {
 *   outputLocation: "s3://my-results-bucket/prefix/",
 *   bytesScannedCutoffPerQuery: 10_000_000, // 10 MB per query
 *   publishCloudWatchMetricsEnabled: true,
 * });
 * ```
 *
 * @resource
 */
export const WorkGroup = Resource<WorkGroup>("AWS.Athena.WorkGroup");

const observedTagsOf = (tags: readonly athena.Tag[] | undefined) =>
  Object.fromEntries(
    (tags ?? []).flatMap((t) =>
      t.Key !== undefined && t.Value !== undefined ? [[t.Key, t.Value]] : [],
    ),
  );

const outputLocationOf = (wg: athena.WorkGroup | undefined) =>
  wg?.Configuration?.ResultConfiguration?.OutputLocation;

export const WorkGroupProvider = () =>
  Provider.effect(
    WorkGroup,
    Effect.gen(function* () {
      const toName = (id: string, props: WorkGroupProps = {}) =>
        props.workGroupName
          ? Effect.succeed(props.workGroupName)
          : createPhysicalName({ id, maxLength: 128 });

      const getOne = (name: string) =>
        athena.getWorkGroup({ WorkGroup: name }).pipe(
          Effect.map((res) => res.WorkGroup),
          Effect.catchTag("WorkGroupNotFound", () => Effect.succeed(undefined)),
        );

      const fetchTags = (arn: string) =>
        athena.listTagsForResource.items({ ResourceARN: arn }).pipe(
          Stream.runCollect,
          Effect.map((chunk) => observedTagsOf(Array.from(chunk))),
          Effect.catch(() => Effect.succeed({} as Record<string, string>)),
        );

      return {
        stables: ["workGroupName", "workGroupArn"],
        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return;
          if (
            (yield* toName(id, olds ?? {})) !== (yield* toName(id, news ?? {}))
          ) {
            return { action: "replace" } as const;
          }
        }),
        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name = output?.workGroupName ?? (yield* toName(id, olds ?? {}));
          const wg = yield* getOne(name);
          if (!wg) return undefined;
          const arn =
            `arn:aws:athena:${region}:${accountId}:workgroup/${name}` as WorkGroupArn;
          return {
            workGroupName: name,
            workGroupArn: arn,
            state: (wg.State ?? "ENABLED") as "ENABLED" | "DISABLED",
            outputLocation: outputLocationOf(wg),
            tags: yield* fetchTags(arn),
          };
        }),
        list: () =>
          Effect.gen(function* () {
            const { accountId, region } = yield* AWSEnvironment.current;
            const pages = yield* athena.listWorkGroups
              .pages({})
              .pipe(Stream.runCollect);
            return Array.from(pages)
              .flatMap((page) => page.WorkGroups ?? [])
              .flatMap((wg) =>
                // `primary` is the account's built-in default workgroup;
                // DeleteWorkGroup always rejects it, so keep it out of
                // enumeration for account-wide teardown (nuke).
                wg.Name && wg.Name !== "primary"
                  ? [
                      {
                        workGroupName: wg.Name,
                        workGroupArn:
                          `arn:aws:athena:${region}:${accountId}:workgroup/${wg.Name}` as WorkGroupArn,
                        state: (wg.State ?? "ENABLED") as
                          | "ENABLED"
                          | "DISABLED",
                        outputLocation: undefined,
                        tags: {} as Record<string, string>,
                      },
                    ]
                  : [],
              );
          }),
        reconcile: Effect.fn(function* ({ id, news = {}, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name = output?.workGroupName ?? (yield* toName(id, news));
          const arn =
            `arn:aws:athena:${region}:${accountId}:workgroup/${name}` as WorkGroupArn;
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };
          const desiredState = news.state ?? "ENABLED";
          const enforce = news.enforceWorkGroupConfiguration ?? true;
          const encryption = news.encryptionOption
            ? {
                EncryptionOption: news.encryptionOption,
                KmsKey: news.kmsKey,
              }
            : undefined;

          // Observe — cloud state is authoritative.
          let wg = yield* getOne(name);

          // Ensure — create if missing.
          if (!wg) {
            yield* athena.createWorkGroup({
              Name: name,
              Description: news.description,
              Configuration: {
                ResultConfiguration: news.outputLocation
                  ? {
                      OutputLocation: news.outputLocation,
                      EncryptionConfiguration: encryption,
                    }
                  : undefined,
                EnforceWorkGroupConfiguration: enforce,
                PublishCloudWatchMetricsEnabled:
                  news.publishCloudWatchMetricsEnabled,
                BytesScannedCutoffPerQuery: news.bytesScannedCutoffPerQuery,
                RequesterPaysEnabled: news.requesterPaysEnabled,
                EngineVersion: news.engineVersion
                  ? { SelectedEngineVersion: news.engineVersion }
                  : undefined,
              },
              Tags: Object.entries(desiredTags).map(([Key, Value]) => ({
                Key,
                Value,
              })),
            });
            wg = yield* getOne(name);
          } else {
            // Sync — diff observed configuration against desired, apply the
            // delta via UpdateWorkGroup (which takes a ConfigurationUpdates
            // shape distinct from CreateWorkGroup's Configuration).
            const cfg = wg.Configuration;
            const updates: athena.WorkGroupConfigurationUpdates = {};
            let dirty = false;

            if ((cfg?.EnforceWorkGroupConfiguration ?? false) !== enforce) {
              updates.EnforceWorkGroupConfiguration = enforce;
              dirty = true;
            }
            if (
              news.outputLocation !== undefined &&
              cfg?.ResultConfiguration?.OutputLocation !== news.outputLocation
            ) {
              updates.ResultConfigurationUpdates = {
                ...updates.ResultConfigurationUpdates,
                OutputLocation: news.outputLocation,
              };
              dirty = true;
            }
            if (
              encryption &&
              cfg?.ResultConfiguration?.EncryptionConfiguration
                ?.EncryptionOption !== encryption.EncryptionOption
            ) {
              updates.ResultConfigurationUpdates = {
                ...updates.ResultConfigurationUpdates,
                EncryptionConfiguration: encryption,
              };
              dirty = true;
            }
            if (
              (cfg?.PublishCloudWatchMetricsEnabled ?? false) !==
              (news.publishCloudWatchMetricsEnabled ?? false)
            ) {
              updates.PublishCloudWatchMetricsEnabled =
                news.publishCloudWatchMetricsEnabled ?? false;
              dirty = true;
            }
            if (
              (cfg?.RequesterPaysEnabled ?? false) !==
              (news.requesterPaysEnabled ?? false)
            ) {
              updates.RequesterPaysEnabled = news.requesterPaysEnabled ?? false;
              dirty = true;
            }
            if (
              (cfg?.BytesScannedCutoffPerQuery ?? undefined) !==
              news.bytesScannedCutoffPerQuery
            ) {
              if (news.bytesScannedCutoffPerQuery === undefined) {
                updates.RemoveBytesScannedCutoffPerQuery = true;
              } else {
                updates.BytesScannedCutoffPerQuery =
                  news.bytesScannedCutoffPerQuery;
              }
              dirty = true;
            }
            if (
              news.engineVersion !== undefined &&
              cfg?.EngineVersion?.SelectedEngineVersion !== news.engineVersion
            ) {
              updates.EngineVersion = {
                SelectedEngineVersion: news.engineVersion,
              };
              dirty = true;
            }

            const stateChange =
              (wg.State ?? "ENABLED") !== desiredState
                ? desiredState
                : undefined;
            const descChange =
              news.description !== undefined &&
              wg.Description !== news.description
                ? news.description
                : undefined;

            if (dirty || stateChange || descChange) {
              yield* athena.updateWorkGroup({
                WorkGroup: name,
                Description: descChange,
                State: stateChange,
                ConfigurationUpdates: dirty ? updates : undefined,
              });
            }
          }

          // Sync tags — diff against OBSERVED cloud tags.
          const observed = yield* fetchTags(arn);
          const { upsert, removed } = diffTags(observed, desiredTags);
          if (upsert.length > 0) {
            yield* athena.tagResource({
              ResourceARN: arn,
              Tags: upsert.map((t) => ({ Key: t.Key, Value: t.Value })),
            });
          }
          if (removed.length > 0) {
            yield* athena.untagResource({ ResourceARN: arn, TagKeys: removed });
          }

          const final = (yield* getOne(name)) ?? wg;
          yield* session.note(arn);
          return {
            workGroupName: name,
            workGroupArn: arn,
            state: (final?.State ?? desiredState) as "ENABLED" | "DISABLED",
            outputLocation: outputLocationOf(final) ?? news.outputLocation,
            tags: desiredTags,
          };
        }),
        delete: Effect.fn(function* ({ output }) {
          // Idempotent: DeleteWorkGroup succeeds (no error) when the workgroup
          // is already gone. RecursiveDeleteOption tears down any named
          // queries / prepared statements still saved in it.
          yield* athena.deleteWorkGroup({
            WorkGroup: output.workGroupName,
            RecursiveDeleteOption: true,
          });
        }),
      };
    }),
  );

import * as autoscaling from "@distilled.cloud/aws/auto-scaling";
import type * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import { deepEqual, isResolved } from "../../Diff.ts";
import type { Input } from "../../Input.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { toSeconds } from "../../Util/Duration.ts";
import type { Providers } from "../Providers.ts";
import type { AutoScalingGroup as AutoScalingGroupResource } from "./AutoScalingGroup.ts";

export type LifecycleHookName = string;

/**
 * Lifecycle transition the hook fires on. The friendly `LAUNCHING` /
 * `TERMINATING` aliases map to the `autoscaling:EC2_INSTANCE_*` transition
 * strings the API expects.
 */
export type LifecycleTransition =
  | "LAUNCHING"
  | "TERMINATING"
  | "autoscaling:EC2_INSTANCE_LAUNCHING"
  | "autoscaling:EC2_INSTANCE_TERMINATING";

export type LifecycleActionResult = "CONTINUE" | "ABANDON";

export const normalizeTransition = (transition: LifecycleTransition): string =>
  transition === "LAUNCHING"
    ? "autoscaling:EC2_INSTANCE_LAUNCHING"
    : transition === "TERMINATING"
      ? "autoscaling:EC2_INSTANCE_TERMINATING"
      : transition;

export interface LifecycleHookProps {
  /**
   * Lifecycle hook name. If omitted, a deterministic name is generated.
   */
  lifecycleHookName?: string;
  /**
   * Auto Scaling Group to attach the hook to.
   */
  autoScalingGroup: Input<string> | AutoScalingGroupResource;
  /**
   * Instance state transition the hook pauses on. Use `LAUNCHING` to drain
   * before an instance enters service, `TERMINATING` to drain before it is
   * removed.
   */
  lifecycleTransition: LifecycleTransition;
  /**
   * Maximum time the instance stays in the wait state before the
   * `defaultResult` is applied, e.g. `"5 minutes"` or
   * `Duration.seconds(300)` (30 seconds–2 hours on the wire).
   * @default "1 hour"
   */
  heartbeatTimeout?: Duration.Input;
  /**
   * Action taken when the hook times out or the ASG is otherwise unable to
   * respond.
   * @default "ABANDON"
   */
  defaultResult?: LifecycleActionResult;
  /**
   * ARN of an SNS topic or SQS queue to notify when the transition occurs.
   * Omit to receive lifecycle events via EventBridge (the default target).
   */
  notificationTargetARN?: string;
  /**
   * ARN of the IAM role that permits the ASG to publish to
   * `notificationTargetARN`. Required when `notificationTargetARN` is set.
   */
  roleARN?: string;
  /**
   * Arbitrary metadata delivered with the lifecycle notification.
   */
  notificationMetadata?: string;
}

export interface LifecycleHook extends Resource<
  "AWS.AutoScaling.LifecycleHook",
  LifecycleHookProps,
  {
    /**
     * Name of the lifecycle hook.
     */
    lifecycleHookName: LifecycleHookName;
    /**
     * Name of the Auto Scaling Group the hook is attached to.
     */
    autoScalingGroupName: string;
    /**
     * The paused transition (e.g. `autoscaling:EC2_INSTANCE_LAUNCHING`).
     */
    lifecycleTransition: string;
    /**
     * Seconds an instance stays paused before `defaultResult` applies.
     */
    heartbeatTimeout: number;
    /**
     * Maximum total seconds an instance can remain in the wait state
     * (100x heartbeat, capped by AWS).
     */
    globalTimeout: number;
    /**
     * Action taken when the hook times out (`CONTINUE` or `ABANDON`).
     */
    defaultResult: string;
    /**
     * SNS/SQS target lifecycle notifications are published to, if any.
     */
    notificationTargetARN?: string;
    /**
     * IAM role used to publish to the notification target, if any.
     */
    roleARN?: string;
    /**
     * Metadata delivered with each lifecycle event.
     */
    notificationMetadata?: string;
  },
  never,
  Providers
> {}

/**
 * A lifecycle hook that pauses an Auto Scaling instance in a wait state on
 * launch or termination so a handler can drain connections, snapshot state, or
 * warm caches before the transition completes. Pair with
 * {@link consumeLifecycleActions} to receive the transition events and
 * {@link CompleteLifecycleAction} to signal `CONTINUE` / `ABANDON`.
 *
 * ### Creating a Lifecycle Hook
 * **Example:** Drain before termination (EventBridge target)
 * ```typescript
 * const hook = yield* LifecycleHook("Drain", {
 *   autoScalingGroup: group,
 *   lifecycleTransition: "TERMINATING",
 *   heartbeatTimeout: "300 seconds",
 *   defaultResult: "CONTINUE",
 * });
 * ```
 *
 * **Example:** Warm caches before an instance enters service
 * ```typescript
 * const hook = yield* LifecycleHook("Warm", {
 *   autoScalingGroup: group,
 *   lifecycleTransition: "LAUNCHING",
 *   heartbeatTimeout: "2 minutes",
 * });
 * ```
 *
 * @resource
 */
export const LifecycleHook = Resource<LifecycleHook>(
  "AWS.AutoScaling.LifecycleHook",
);

// Derive the group name from either spelling of `autoScalingGroup`. A whole
// AutoScalingGroup resource resolves to its bare Attributes before reaching the
// provider — the resource `Type` marker does not survive resolution — so narrow
// on the attributes shape, never on `Type`.
const toAutoScalingGroupName = (
  input: LifecycleHookProps["autoScalingGroup"] | undefined,
): string | undefined =>
  typeof input === "string"
    ? input
    : typeof (input as { autoScalingGroupName?: unknown } | undefined)
          ?.autoScalingGroupName === "string"
      ? (input as unknown as { autoScalingGroupName: string })
          .autoScalingGroupName
      : undefined;

export const LifecycleHookProvider = () =>
  Provider.effect(
    LifecycleHook,
    Effect.gen(function* () {
      const toName = (
        id: string,
        props: { lifecycleHookName?: string } = {},
      ) =>
        props.lifecycleHookName
          ? Effect.succeed(props.lifecycleHookName)
          : createPhysicalName({ id, maxLength: 255, lowercase: true });

      const describeHook = ({
        autoScalingGroupName,
        lifecycleHookName,
      }: {
        autoScalingGroupName: string;
        lifecycleHookName: string;
      }) =>
        autoscaling
          .describeLifecycleHooks({
            AutoScalingGroupName: autoScalingGroupName,
            LifecycleHookNames: [lifecycleHookName],
          } as any)
          .pipe(
            Effect.map((result) => result.LifecycleHooks?.[0]),
            // A deleted/absent Auto Scaling Group surfaces as
            // `ValidationError: AutoScalingGroup ... not found` (typed
            // `AutoScalingGroupNotFound` via the auto-scaling patch); treat it
            // as "hook gone" so refresh/read converge instead of failing.
            Effect.catchTag("AutoScalingGroupNotFound", () =>
              Effect.succeed(undefined),
            ),
          );

      const toAttributes = (
        hook: autoscaling.LifecycleHook,
      ): LifecycleHook["Attributes"] => ({
        lifecycleHookName: hook.LifecycleHookName!,
        autoScalingGroupName: hook.AutoScalingGroupName!,
        lifecycleTransition: hook.LifecycleTransition!,
        heartbeatTimeout: hook.HeartbeatTimeout ?? 0,
        globalTimeout: hook.GlobalTimeout ?? 0,
        defaultResult: hook.DefaultResult ?? "ABANDON",
        notificationTargetARN: hook.NotificationTargetARN,
        roleARN: hook.RoleARN,
        notificationMetadata: hook.NotificationMetadata,
      });

      return {
        stables: ["lifecycleHookName", "autoScalingGroupName"],
        // A lifecycle hook is a sub-resource of its Auto Scaling Group;
        // `describeLifecycleHooks` requires an AutoScalingGroupName and cannot
        // enumerate account-wide, so there is no parent-free listing.
        list: () => Effect.succeed([]),
        diff: Effect.fn(function* ({ id, olds, news: _news }) {
          if (!isResolved(_news)) return undefined;
          const news = _news as typeof olds;
          const oldName = yield* toName(id, olds ?? {});
          const newName = yield* toName(id, news ?? {});
          const oldGroup = toAutoScalingGroupName(olds.autoScalingGroup);
          const newGroup = toAutoScalingGroupName(news.autoScalingGroup);
          // Hook name or ASG change → replace (identity fields). Both sides must
          // be known before forcing a replacement; a half-created row may have
          // lost an Output-valued `autoScalingGroup`.
          if (
            oldName !== newName ||
            (oldGroup !== undefined &&
              newGroup !== undefined &&
              oldGroup !== newGroup)
          ) {
            return { action: "replace", deleteFirst: true } as const;
          }

          if (!deepEqual(olds, news)) {
            return {
              action: "update",
              stables: ["lifecycleHookName", "autoScalingGroupName"],
            } as const;
          }
        }),
        read: Effect.fn(function* ({ id, olds, output }) {
          const autoScalingGroupName =
            output?.autoScalingGroupName ??
            toAutoScalingGroupName(olds?.autoScalingGroup);
          const lifecycleHookName =
            output?.lifecycleHookName ?? (yield* toName(id, olds ?? {}));
          if (!autoScalingGroupName) return undefined;
          const hook = yield* describeHook({
            autoScalingGroupName,
            lifecycleHookName,
          });
          return hook ? toAttributes(hook) : undefined;
        }),
        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const autoScalingGroupName =
            output?.autoScalingGroupName ??
            toAutoScalingGroupName(news.autoScalingGroup);
          if (!autoScalingGroupName) {
            return yield* Effect.die(
              new Error(
                "LifecycleHook requires a resolvable autoScalingGroup name",
              ),
            );
          }
          const lifecycleHookName =
            output?.lifecycleHookName ?? (yield* toName(id, news));

          // Ensure + Sync — `putLifecycleHook` is the single create-or-update
          // API. It overwrites the whole hook configuration, so we issue it
          // unconditionally (idempotent on matching params).
          yield* autoscaling.putLifecycleHook({
            LifecycleHookName: lifecycleHookName,
            AutoScalingGroupName: autoScalingGroupName,
            LifecycleTransition: normalizeTransition(news.lifecycleTransition),
            HeartbeatTimeout: toSeconds(news.heartbeatTimeout),
            DefaultResult: news.defaultResult,
            NotificationTargetARN: news.notificationTargetARN,
            RoleARN: news.roleARN,
            NotificationMetadata: news.notificationMetadata,
          } as any);

          const hook = yield* describeHook({
            autoScalingGroupName,
            lifecycleHookName,
          }).pipe(
            Effect.flatMap((hook) =>
              hook
                ? Effect.succeed(hook)
                : Effect.fail(
                    new Error(
                      `Lifecycle hook '${lifecycleHookName}' was not readable after reconcile`,
                    ),
                  ),
            ),
          );
          yield* session.note(lifecycleHookName);
          return toAttributes(hook);
        }),
        delete: Effect.fn(function* ({ output }) {
          // `deleteLifecycleHook` is idempotent — a missing hook returns
          // success. Retry only the transient contention fault.
          yield* autoscaling
            .deleteLifecycleHook({
              AutoScalingGroupName: output.autoScalingGroupName,
              LifecycleHookName: output.lifecycleHookName,
            } as any)
            .pipe(
              Effect.retry({
                while: (error) => error._tag === "ResourceContentionFault",
                schedule: Schedule.max([
                  Schedule.recurs(5),
                  Schedule.exponential("250 millis"),
                ]),
              }),
            );
        }),
      };
    }),
  );

