/**
 * Where CodeBuild fetches the source to build.
 */
export interface ProjectSourceConfig {
  /**
   * Source provider type. `NO_SOURCE` builds run only the inline `buildspec`
   * (nothing is fetched); `S3` pulls an object; the git types
   * (`CODECOMMIT`/`GITHUB`/`GITLAB`/`BITBUCKET`/…) require a matching
   * source credential or connection.
   */
  type:
    | "NO_SOURCE"
    | "S3"
    | "CODECOMMIT"
    | "CODEPIPELINE"
    | "GITHUB"
    | "GITHUB_ENTERPRISE"
    | "GITLAB"
    | "GITLAB_SELF_MANAGED"
    | "BITBUCKET";
  /**
   * Source location. Required for every type except `NO_SOURCE` and
   * `CODEPIPELINE`. For `S3` this is `bucket/path/to/object.zip`; for git
   * types it is the clone URL.
   */
  location?: string;
  /**
   * Inline build spec (YAML/JSON). Required when `type` is `NO_SOURCE`;
   * otherwise overrides the `buildspec.yml` in the source root. May also be
   * an `arn:aws:s3:::` path to a build spec object.
   */
  buildspec?: string;
  /**
   * Depth of history to fetch for git sources. `0` fetches full history.
   */
  gitCloneDepth?: number;
  /**
   * Report the build's start and completion status back to the source
   * provider (git sources only).
   */
  reportBuildStatus?: boolean;
  /**
   * Ignore TLS errors when connecting to the source (git sources only).
   */
  insecureSsl?: boolean;
}

/**
 * Where CodeBuild writes build output artifacts.
 */
export interface ProjectArtifactsConfig {
  /**
   * Artifact destination. `NO_ARTIFACTS` discards output; `S3` uploads to a
   * bucket; `CODEPIPELINE` hands artifacts back to a pipeline stage.
   * @default "NO_ARTIFACTS"
   */
  type: "NO_ARTIFACTS" | "S3" | "CODEPIPELINE";
  /**
   * Output bucket name (for `type: "S3"`).
   */
  location?: string;
  /**
   * Path inside the bucket to write to.
   */
  path?: string;
  /**
   * Whether to prefix the artifact path with the build ID.
   * @default "NONE"
   */
  namespaceType?: "NONE" | "BUILD_ID";
  /**
   * Name of the artifact object/folder.
   */
  name?: string;
  /**
   * Whether the artifact is zipped.
   * @default "NONE"
   */
  packaging?: "NONE" | "ZIP";
  /**
   * Use the artifact `name` verbatim instead of appending it to the path.
   */
  overrideArtifactName?: boolean;
  /**
   * Disable default artifact encryption.
   */
  encryptionDisabled?: boolean;
}

/**
 * An environment variable exposed to the build container.
 */
export interface ProjectEnvironmentVariable {
  /** Variable name. */
  name: string;
  /**
   * Variable value. For `PLAINTEXT` this is the literal value; for
   * `PARAMETER_STORE`/`SECRETS_MANAGER` it is the parameter name / secret
   * ARN to resolve at build time.
   */
  value: string;
  /**
   * How to interpret `value`.
   * @default "PLAINTEXT"
   */
  type?: "PLAINTEXT" | "PARAMETER_STORE" | "SECRETS_MANAGER";
}

/**
 * The build container: image, compute size, and runtime settings.
 */
export interface ProjectEnvironmentConfig {
  /**
   * Container environment type.
   * @default "LINUX_CONTAINER"
   */
  type?:
    | "LINUX_CONTAINER"
    | "LINUX_GPU_CONTAINER"
    | "ARM_CONTAINER"
    | "WINDOWS_SERVER_2019_CONTAINER"
    | "WINDOWS_SERVER_2022_CONTAINER"
    | "LINUX_LAMBDA_CONTAINER"
    | "ARM_LAMBDA_CONTAINER"
    | "MAC_ARM";
  /**
   * Docker image to run the build in, e.g.
   * `aws/codebuild/amazonlinux2-x86_64-standard:5.0`.
   */
  image: string;
  /**
   * Compute size for the build fleet.
   * @default "BUILD_GENERAL1_SMALL"
   */
  computeType?:
    | "BUILD_GENERAL1_SMALL"
    | "BUILD_GENERAL1_MEDIUM"
    | "BUILD_GENERAL1_LARGE"
    | "BUILD_GENERAL1_XLARGE"
    | "BUILD_GENERAL1_2XLARGE"
    | "BUILD_LAMBDA_1GB"
    | "BUILD_LAMBDA_2GB"
    | "BUILD_LAMBDA_4GB"
    | "BUILD_LAMBDA_8GB"
    | "BUILD_LAMBDA_10GB";
  /**
   * Environment variables available to every build.
   */
  environmentVariables?: ProjectEnvironmentVariable[];
  /**
   * Run the build container in privileged mode (required to build Docker
   * images inside the build).
   * @default false
   */
  privilegedMode?: boolean;
  /**
   * ARN of an S3 object holding a PEM-encoded certificate to install.
   */
  certificate?: string;
  /**
   * Credentials used to pull the build image.
   * @default "CODEBUILD"
   */
  imagePullCredentialsType?: "CODEBUILD" | "SERVICE_ROLE";
}

/** Build log destinations for a CodeBuild project. */
export interface ProjectLogsConfig {
  /** CloudWatch Logs delivery configuration. */
  cloudWatchLogs?: {
    /** Whether CloudWatch Logs delivery is enabled. */
    status: "ENABLED" | "DISABLED";
    /** Optional CloudWatch log group name. */
    groupName?: string;
    /** Optional CloudWatch log stream name. */
    streamName?: string;
  };
  /** S3 log delivery configuration. */
  s3Logs?: {
    /** Whether S3 log delivery is enabled. */
    status: "ENABLED" | "DISABLED";
    /** S3 bucket and prefix for build logs. */
    location?: string;
    /** Disable default encryption for S3 build logs. */
    encryptionDisabled?: boolean;
    /** Access granted to the destination bucket owner. */
    bucketOwnerAccess?: "NONE" | "READ_ONLY" | "FULL";
  };
}

export interface ProjectProps {
  /**
   * Name of the build project (2-255 chars). If omitted a deterministic
   * physical name is generated. Changing the name replaces the project.
   */
  projectName?: string;
  /**
   * Description of the project.
   */
  description?: string;
  /**
   * Source configuration.
   */
  source: ProjectSourceConfig;
  /**
   * Artifact configuration.
   * @default { type: "NO_ARTIFACTS" }
   */
  artifacts?: ProjectArtifactsConfig;
  /**
   * Build container configuration.
   */
  environment: ProjectEnvironmentConfig;
  /**
   * ARN of the IAM role CodeBuild assumes to run builds. Must trust
   * `codebuild.amazonaws.com`.
   */
  serviceRole: string;
  /**
   * How long a build may run before CodeBuild stops it, e.g. `"1 hour"`
   * (5 minutes to 36 hours). Rounded to whole minutes on the wire.
   * @default 60 minutes
   */
  timeout?: Duration.Input;
  /**
   * How long a build may sit queued before it is failed, e.g.
   * `"30 minutes"` (5 minutes to 8 hours). Rounded to whole minutes on
   * the wire.
   */
  queuedTimeout?: Duration.Input;
  /**
   * Maximum number of builds allowed to run concurrently for this project.
   */
  concurrentBuildLimit?: number;
  /**
   * KMS key ARN/alias used to encrypt build output. Defaults to the
   * account's default S3 CMK.
   */
  encryptionKey?: string;
  /**
   * Enable a publicly visible build badge.
   * @default false
   */
  badgeEnabled?: boolean;
  /**
   * Build log destinations. Set both destinations to `DISABLED` for builds
   * that do not need persisted logs.
   */
  logsConfig?: ProjectLogsConfig;
  /**
   * Resource policy attached to the project — shares the project with other
   * AWS accounts by granting them read actions such as
   * `codebuild:BatchGetProjects`. Accepts a typed {@link PolicyDocument} or a
   * raw JSON string (escape hatch / adoption of an existing policy). Omit to
   * remove any existing policy.
   */
  resourcePolicy?: PolicyDocument | string;
  /**
   * User-defined tags.
   */
  tags?: Record<string, string>;
}

export interface Project extends Resource<
  "AWS.CodeBuild.Project",
  ProjectProps,
  {
    /** Physical name of the build project. */
    projectName: string;
    /** ARN of the build project. */
    projectArn: string;
  },
  never,
  Providers
> {}

/**
 * An AWS CodeBuild build project — a reusable definition of how to run a
 * build: the source, the build container, the compute size, the IAM role,
 * and where artifacts land.
 *
 * The project is a definition only; creating it is instant and free.
 * Running a build (`StartBuild`) provisions compute and is billed per
 * build-minute.
 * ### Creating a Project
 * **Example:** NO_SOURCE Project with an Inline Buildspec
 * ```typescript
 * const project = yield* CodeBuild.Project("Hello", {
 *   serviceRole: role.roleArn,
 *   source: {
 *     type: "NO_SOURCE",
 *     buildspec: [
 *       "version: 0.2",
 *       "phases:",
 *       "  build:",
 *       "    commands:",
 *       "      - echo Hello from CodeBuild",
 *     ].join("\n"),
 *   },
 *   environment: {
 *     image: "aws/codebuild/amazonlinux2-x86_64-standard:5.0",
 *     computeType: "BUILD_GENERAL1_SMALL",
 *   },
 * });
 * ```
 *
 * **Example:** S3-Source Project with S3 Artifacts
 * ```typescript
 * const project = yield* CodeBuild.Project("Packager", {
 *   serviceRole: role.roleArn,
 *   source: { type: "S3", location: `${bucket.bucketName}/source.zip` },
 *   artifacts: { type: "S3", location: bucket.bucketName, name: "out.zip", packaging: "ZIP" },
 *   environment: {
 *     image: "aws/codebuild/amazonlinux2-x86_64-standard:5.0",
 *     environmentVariables: [{ name: "STAGE", value: "prod" }],
 *   },
 * });
 * ```
 *
 * @resource
 */
export const Project = Resource<Project>("AWS.CodeBuild.Project");

/** Convert a CodeBuild wire tag list into a plain record. */
const toTagRecord = (
  tags: ReadonlyArray<{ key?: string; value?: string }> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    (tags ?? [])
      .filter(
        (tag): tag is { key: string; value: string } =>
          typeof tag.key === "string" && typeof tag.value === "string",
      )
      .map((tag) => [tag.key, tag.value]),
  );

const toWireTags = (tags: Record<string, string>): codebuild.Tag[] =>
  Object.entries(tags).map(([key, value]) => ({ key, value }));

const toWireSource = (
  source: ProjectSourceConfig,
): codebuild.ProjectSource => ({
  type: source.type,
  location: source.location,
  buildspec: source.buildspec,
  gitCloneDepth: source.gitCloneDepth,
  reportBuildStatus: source.reportBuildStatus,
  insecureSsl: source.insecureSsl,
});

const toWireArtifacts = (
  artifacts: ProjectArtifactsConfig | undefined,
): codebuild.ProjectArtifacts => ({
  type: artifacts?.type ?? "NO_ARTIFACTS",
  location: artifacts?.location,
  path: artifacts?.path,
  namespaceType: artifacts?.namespaceType,
  name: artifacts?.name,
  packaging: artifacts?.packaging,
  overrideArtifactName: artifacts?.overrideArtifactName,
  encryptionDisabled: artifacts?.encryptionDisabled,
});

const toWireEnvironment = (
  environment: ProjectEnvironmentConfig,
): codebuild.ProjectEnvironment => ({
  type: environment.type ?? "LINUX_CONTAINER",
  image: environment.image,
  computeType: environment.computeType ?? "BUILD_GENERAL1_SMALL",
  environmentVariables: environment.environmentVariables?.map((v) => ({
    name: v.name,
    value: v.value,
    type: v.type,
  })),
  privilegedMode: environment.privilegedMode,
  certificate: environment.certificate,
  imagePullCredentialsType: environment.imagePullCredentialsType,
});

/**
 * CodeBuild validates the service role at create/update time; a freshly
 * created IAM role is not yet assumable, surfacing as an
 * `InvalidInputException` whose message mentions the role is not authorized.
 * Retry (bounded) through IAM propagation. The explicit return annotation
 * keeps the retry's conditional type out of declaration emit (which would
 * otherwise widen the provider layer — see PATTERNS §7).
 */
const retryIamPropagation = <
  A,
  E extends { readonly _tag: string; readonly message?: string },
  R,
>(
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> =>
  effect.pipe(
    Effect.retry({
      while: (e) =>
        e._tag === "InvalidInputException" &&
        (e.message ?? "").toLowerCase().includes("not authorized"),
      schedule: Schedule.max([
        Schedule.fixed("3 seconds"),
        Schedule.recurs(10),
      ]),
    }),
  );

export const ProjectProvider = () =>
  Provider.effect(
    Project,
    Effect.gen(function* () {
      const toName = (id: string, props: Partial<ProjectProps>) =>
        props.projectName
          ? Effect.succeed(props.projectName)
          : createPhysicalName({ id, maxLength: 128 });

      /** Read a project by name; a missing project reads as absent. */
      const getProject = Effect.fn(function* (name: string) {
        const response = yield* codebuild.batchGetProjects({ names: [name] });
        return response.projects?.[0];
      });

      return {
        stables: ["projectName", "projectArn"],

        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return undefined;
          if (
            (yield* toName(id, olds ?? {})) !== (yield* toName(id, news ?? {}))
          ) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const name = output?.projectName ?? (yield* toName(id, olds ?? {}));
          const project = yield* getProject(name);
          if (project === undefined || project.arn === undefined) {
            return undefined;
          }
          const attrs = {
            projectName: project.name ?? name,
            projectArn: project.arn,
          };
          const tags = toTagRecord(project.tags);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const name = output?.projectName ?? (yield* toName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };

          // 1. Observe — cloud state is authoritative.
          let observed = yield* getProject(name);

          const spec = {
            description: news.description,
            source: toWireSource(news.source),
            artifacts: toWireArtifacts(news.artifacts),
            environment: toWireEnvironment(news.environment),
            serviceRole: news.serviceRole,
            // The CodeBuild wire unit for build/queue timeouts is whole minutes.
            timeoutInMinutes: toWireMinutes(news.timeout),
            queuedTimeoutInMinutes: toWireMinutes(news.queuedTimeout),
            concurrentBuildLimit: news.concurrentBuildLimit,
            encryptionKey: news.encryptionKey,
            badgeEnabled: news.badgeEnabled,
            logsConfig: news.logsConfig,
            tags: toWireTags(desiredTags),
          };

          // 3. Sync — updateProject is a full upsert of the definition and
          // tags; apply the desired spec (project updates are instant). A
          // delete→redeploy race can leave batchGetProjects returning the
          // just-deleted project; updateProject then reports the truth with
          // a typed ResourceNotFoundException — treat it as missing.
          if (observed !== undefined) {
            observed = yield* retryIamPropagation(
              codebuild.updateProject({ name, ...spec }),
            ).pipe(
              Effect.map((updated) => updated.project),
              Effect.catchTag("ResourceNotFoundException", () =>
                Effect.succeed(undefined),
              ),
            );
          }

          // 2. Ensure — create if missing; tolerate the create/create race.
          if (observed === undefined) {
            const created = yield* retryIamPropagation(
              codebuild.createProject({ name, ...spec }),
            ).pipe(
              Effect.catchTag("ResourceAlreadyExistsException", () =>
                getProject(name).pipe(Effect.map((p) => ({ project: p }))),
              ),
            );
            observed = created.project;
          }

          if (observed === undefined || observed.arn === undefined) {
            return yield* Effect.fail(
              new Error(
                `CodeBuild project '${name}' disappeared while reconciling`,
              ),
            );
          }

          // 3b. Sync — resource policy. Compare observed against desired in
          // normalized form (keys sorted, no whitespace) so a re-deploy of an
          // equivalent document — regardless of key order or string vs typed
          // object — is a no-op that skips the API entirely.
          const desiredPolicy =
            news.resourcePolicy === undefined
              ? undefined
              : typeof news.resourcePolicy === "string"
                ? news.resourcePolicy
                : stringifyPolicyDocument(news.resourcePolicy);
          const observedPolicy = yield* codebuild
            .getResourcePolicy({ resourceArn: observed.arn })
            .pipe(
              Effect.map((res) => res.policy),
              Effect.catchTag("ResourceNotFoundException", () =>
                Effect.succeed(undefined),
              ),
            );
          if (desiredPolicy === undefined) {
            if (observedPolicy !== undefined && observedPolicy !== "") {
              yield* codebuild.deleteResourcePolicy({
                resourceArn: observed.arn,
              });
            }
          } else if (
            observedPolicy === undefined ||
            normalizePolicyDocument(observedPolicy) !==
              normalizePolicyDocument(desiredPolicy)
          ) {
            yield* codebuild.putResourcePolicy({
              resourceArn: observed.arn,
              policy: desiredPolicy,
            });
          }

          // 4. Return fresh attributes.
          yield* session.note(name);
          return {
            projectName: observed.name ?? name,
            projectArn: observed.arn,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteProject is idempotent — a missing project returns success.
          yield* codebuild.deleteProject({ name: output.projectName });
        }),

        list: () =>
          codebuild.listProjects.pages({}).pipe(
            Stream.runCollect,
            Effect.map((chunk) =>
              Array.from(chunk).flatMap((page) => page.projects ?? []),
            ),
            Effect.flatMap((names) =>
              names.length === 0
                ? Effect.succeed(
                    [] as { projectName: string; projectArn: string }[],
                  )
                : Effect.forEach(
                    // batchGetProjects accepts up to 100 names per call.
                    chunkNames(names, 100),
                    (batch) =>
                      codebuild
                        .batchGetProjects({ names: batch })
                        .pipe(Effect.map((res) => res.projects ?? [])),
                    { concurrency: 2 },
                  ).pipe(
                    Effect.map((results) =>
                      results
                        .flat()
                        .flatMap((p) =>
                          p.name !== undefined && p.arn !== undefined
                            ? [{ projectName: p.name, projectArn: p.arn }]
                            : [],
                        ),
                    ),
                  ),
            ),
          ),
      };
    }),
  );

/** Split a list into fixed-size chunks. */
const chunkNames = (names: string[], size: number): string[][] => {
  const chunks: string[][] = [];
  for (let i = 0; i < names.length; i += size) {
    chunks.push(names.slice(i, i + size));
  }
  return chunks;
};

import * as codebuild from "@distilled.cloud/aws/codebuild";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, hasAlchemyTags } from "../../Tags.ts";
import { AWSEnvironment } from "../Environment.ts";

/**
 * Where CodeBuild exports the raw report data.
 */
export interface ReportGroupExportConfig {
  /**
   * `NO_EXPORT` keeps report data only in CodeBuild (30-day retention);
   * `S3` additionally exports the raw data to a bucket.
   * @default "NO_EXPORT"
   */
  exportConfigType?: "NO_EXPORT" | "S3";
  /**
   * S3 destination for exported report data (for `exportConfigType: "S3"`).
   */
  s3Destination?: {
    /** Name of the destination bucket. */
    bucket?: string;
    /** AWS account that owns the bucket, when not the report's account. */
    bucketOwner?: string;
    /** Path prefix inside the bucket. */
    path?: string;
    /**
     * Whether the exported data is zipped.
     * @default "NONE"
     */
    packaging?: "ZIP" | "NONE";
    /** KMS key used to encrypt the exported data. */
    encryptionKey?: string;
    /** Disable encryption of the exported data. */
    encryptionDisabled?: boolean;
  };
}

export interface ReportGroupProps {
  /**
   * Name of the report group (2-128 chars). Builds address it from the
   * buildspec `reports:` section as `<project-name>-<group-name>` or by this
   * exact name. If omitted a deterministic physical name is generated.
   * Changing the name replaces the report group.
   */
  reportGroupName?: string;
  /**
   * What the group's reports contain: test results or code coverage.
   * Changing the type replaces the report group.
   */
  type: "TEST" | "CODE_COVERAGE";
  /**
   * Where raw report data is exported.
   * @default { exportConfigType: "NO_EXPORT" }
   */
  exportConfig?: ReportGroupExportConfig;
  /**
   * Also delete any reports in the group when the group is destroyed.
   * @default true
   */
  deleteReports?: boolean;
  /**
   * User-defined tags.
   */
  tags?: Record<string, string>;
}

export interface ReportGroup extends Resource<
  "AWS.CodeBuild.ReportGroup",
  ReportGroupProps,
  {
    /** Physical name of the report group. */
    reportGroupName: string;
    /** ARN of the report group. */
    reportGroupArn: string;
  }
> {}

/**
 * An AWS CodeBuild report group — a named collection of test or
 * code-coverage reports produced by builds. A build's buildspec `reports:`
 * section uploads its test results into a report group, and the report-read
 * bindings ({@link BatchGetReports}, {@link DescribeTestCases}, …) let
 * runtime code query them.
 *
 * ### Creating a Report Group
 * **Example:** Test Report Group
 * ```typescript
 * const reports = yield* CodeBuild.ReportGroup("UnitTests", {
 *   type: "TEST",
 * });
 * ```
 *
 * **Example:** Coverage Group Exported to S3
 * ```typescript
 * const coverage = yield* CodeBuild.ReportGroup("Coverage", {
 *   type: "CODE_COVERAGE",
 *   exportConfig: {
 *     exportConfigType: "S3",
 *     s3Destination: { bucket: bucket.bucketName, packaging: "ZIP" },
 *   },
 * });
 * ```
 *
 * @resource
 */
export const ReportGroup = Resource<ReportGroup>("AWS.CodeBuild.ReportGroup");

/** Convert a CodeBuild wire tag list into a plain record. */
const toTagRecord = (
  tags: ReadonlyArray<{ key?: string; value?: string }> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    (tags ?? [])
      .filter(
        (tag): tag is { key: string; value: string } =>
          typeof tag.key === "string" && typeof tag.value === "string",
      )
      .map((tag) => [tag.key, tag.value]),
  );

const toWireTags = (tags: Record<string, string>): codebuild.Tag[] =>
  Object.entries(tags).map(([key, value]) => ({ key, value }));

const toWireExportConfig = (
  exportConfig: ReportGroupExportConfig | undefined,
): codebuild.ReportExportConfig => ({
  exportConfigType: exportConfig?.exportConfigType ?? "NO_EXPORT",
  s3Destination: exportConfig?.s3Destination,
});

/** Builds a report group's ARN from its name in the ambient account/region. */
const reportGroupArn = Effect.fn(function* (name: string) {
  const { accountId, region } = yield* AWSEnvironment.current;
  return `arn:aws:codebuild:${region}:${accountId}:report-group/${name}`;
});

/** Structural comparison for the export-config sync no-op check. */
const sameExportConfig = (
  observed: codebuild.ReportExportConfig | undefined,
  desired: codebuild.ReportExportConfig,
): boolean =>
  (observed?.exportConfigType ?? "NO_EXPORT") === desired.exportConfigType &&
  JSON.stringify(observed?.s3Destination ?? null) ===
    JSON.stringify(desired.s3Destination ?? null);

const sameTags = (
  observed: Record<string, string>,
  desired: Record<string, string>,
): boolean =>
  Object.keys(observed).length === Object.keys(desired).length &&
  Object.entries(desired).every(([k, v]) => observed[k] === v);

export const ReportGroupProvider = () =>
  Provider.effect(
    ReportGroup,
    Effect.gen(function* () {
      const toName = (id: string, props: Partial<ReportGroupProps>) =>
        props.reportGroupName
          ? Effect.succeed(props.reportGroupName)
          : createPhysicalName({ id, maxLength: 128 });

      /** Read a report group by ARN; missing or DELETING reads as absent. */
      const getReportGroup = Effect.fn(function* (arn: string) {
        const response = yield* codebuild.batchGetReportGroups({
          reportGroupArns: [arn],
        });
        const group = response.reportGroups?.[0];
        return group?.status === "DELETING" ? undefined : group;
      });

      return {
        stables: ["reportGroupName", "reportGroupArn"],

        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return undefined;
          if (
            (yield* toName(id, olds ?? {})) !==
              (yield* toName(id, news ?? {})) ||
            olds?.type !== news.type
          ) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const name =
            output?.reportGroupName ?? (yield* toName(id, olds ?? {}));
          const arn = output?.reportGroupArn ?? (yield* reportGroupArn(name));
          const group = yield* getReportGroup(arn);
          if (group === undefined || group.arn === undefined) {
            return undefined;
          }
          const attrs = {
            reportGroupName: group.name ?? name,
            reportGroupArn: group.arn,
          };
          const tags = toTagRecord(group.tags);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const name = output?.reportGroupName ?? (yield* toName(id, news));
          const arn = output?.reportGroupArn ?? (yield* reportGroupArn(name));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };
          const desiredExport = toWireExportConfig(news.exportConfig);

          // 1. Observe — cloud state is authoritative.
          let observed = yield* getReportGroup(arn);

          // 3. Sync — diff observed export config + tags against desired
          // and skip the API entirely on a no-op. updateReportGroup is a
          // full upsert of both mutable aspects. A delete→redeploy race can
          // leave batchGetReportGroups returning the just-deleted group;
          // updateReportGroup then reports the truth with a typed
          // ResourceNotFoundException — treat it as missing.
          if (
            observed !== undefined &&
            (!sameExportConfig(observed.exportConfig, desiredExport) ||
              !sameTags(toTagRecord(observed.tags), desiredTags))
          ) {
            observed = yield* codebuild
              .updateReportGroup({
                arn,
                exportConfig: desiredExport,
                tags: toWireTags(desiredTags),
              })
              .pipe(
                Effect.map((res) => res.reportGroup),
                Effect.catchTag("ResourceNotFoundException", () =>
                  Effect.succeed(undefined),
                ),
              );
          }

          // 2. Ensure — create if missing; tolerate the create/create race.
          if (observed === undefined) {
            observed = yield* codebuild
              .createReportGroup({
                name,
                type: news.type,
                exportConfig: desiredExport,
                tags: toWireTags(desiredTags),
              })
              .pipe(
                Effect.map((res) => res.reportGroup),
                Effect.catchTag("ResourceAlreadyExistsException", () =>
                  getReportGroup(arn),
                ),
              );
          }

          if (observed === undefined || observed.arn === undefined) {
            return yield* Effect.fail(
              new Error(
                `CodeBuild report group '${name}' disappeared while reconciling`,
              ),
            );
          }

          yield* session.note(name);
          return {
            reportGroupName: observed.name ?? name,
            reportGroupArn: observed.arn,
          };
        }),

        delete: Effect.fn(function* ({ olds, output }) {
          // deleteReportGroup is idempotent — deleting a missing group
          // returns success. `deleteReports` clears contained reports first
          // (a non-empty group cannot be deleted otherwise).
          yield* codebuild.deleteReportGroup({
            arn: output.reportGroupArn,
            deleteReports: olds.deleteReports ?? true,
          });
        }),

        list: () =>
          codebuild.listReportGroups.pages({}).pipe(
            Stream.runCollect,
            Effect.map((chunk) =>
              Array.from(chunk).flatMap((page) => page.reportGroups ?? []),
            ),
            Effect.flatMap((arns) =>
              arns.length === 0
                ? Effect.succeed(
                    [] as { reportGroupName: string; reportGroupArn: string }[],
                  )
                : Effect.forEach(
                    // batchGetReportGroups accepts up to 100 ARNs per call.
                    chunkArns(arns, 100),
                    (batch) =>
                      codebuild
                        .batchGetReportGroups({ reportGroupArns: batch })
                        .pipe(Effect.map((res) => res.reportGroups ?? [])),
                    { concurrency: 2 },
                  ).pipe(
                    Effect.map((results) =>
                      results.flat().flatMap((g) =>
                        g.name !== undefined && g.arn !== undefined
                          ? [
                              {
                                reportGroupName: g.name,
                                reportGroupArn: g.arn,
                              },
                            ]
                          : [],
                      ),
                    ),
                  ),
            ),
          ),
      };
    }),
  );

/** Split a list into fixed-size chunks. */
const chunkArns = (arns: string[], size: number): string[][] => {
  const chunks: string[][] = [];
  for (let i = 0; i < arns.length; i += size) {
    chunks.push(arns.slice(i, i + size));
  }
  return chunks;
};

import * as codedeploy from "@distilled.cloud/aws/codedeploy";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, diffTags, hasAlchemyTags } from "../../Tags.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";

export interface ApplicationProps {
  /**
   * Name of the application (1-100 chars). If omitted a deterministic physical
   * name is generated. Changing the name replaces the application.
   */
  applicationName?: string;
  /**
   * The compute platform the application deploys to. Immutable — changing it
   * replaces the application.
   * @default "Server"
   */
  computePlatform?: "Server" | "Lambda" | "ECS";
  /**
   * User-defined tags.
   */
  tags?: Record<string, string>;
}

export interface Application extends Resource<
  "AWS.CodeDeploy.Application",
  ApplicationProps,
  {
    /** Physical name of the application. */
    applicationName: string;
    /** Unique CodeDeploy-assigned application ID. */
    applicationId: string;
    /** ARN of the application. */
    applicationArn: string;
    /** The compute platform (`Lambda`, `Server`, or `ECS`). */
    computePlatform: string;
  },
  never,
  Providers
> {}

/**
 * An AWS CodeDeploy application — a logical container that groups the
 * deployment groups and revisions for a single deployable unit on a given
 * compute platform (EC2/on-prem `Server`, `Lambda`, or `ECS`).
 *
 * ### Creating an Application
 * **Example:** Lambda Application
 * ```typescript
 * const app = yield* CodeDeploy.Application("api", {
 *   computePlatform: "Lambda",
 * });
 * ```
 *
 * **Example:** EC2/On-Premises Application
 * ```typescript
 * const app = yield* CodeDeploy.Application("web", {
 *   applicationName: "web-fleet",
 *   computePlatform: "Server",
 *   tags: { team: "platform" },
 * });
 * ```
 *
 * @resource
 */
export const Application = Resource<Application>("AWS.CodeDeploy.Application");

/** Build the ARN for a CodeDeploy application. */
const applicationArn = (
  region: string,
  account: string,
  name: string,
): string => `arn:aws:codedeploy:${region}:${account}:application:${name}`;

/** Convert a CodeDeploy wire tag list into a plain record. */
const toTagRecord = (
  tags: ReadonlyArray<{ Key?: string; Value?: string }> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    (tags ?? [])
      .filter(
        (tag): tag is { Key: string; Value: string } =>
          typeof tag.Key === "string" && typeof tag.Value === "string",
      )
      .map((tag) => [tag.Key, tag.Value]),
  );

export const ApplicationProvider = () =>
  Provider.effect(
    Application,
    Effect.gen(function* () {
      const toName = (id: string, props: Partial<ApplicationProps>) =>
        props.applicationName
          ? Effect.succeed(props.applicationName)
          : createPhysicalName({ id, maxLength: 100 });

      const getApplication = Effect.fn(function* (name: string) {
        const response = yield* codedeploy
          .getApplication({ applicationName: name })
          .pipe(
            Effect.catchTag("ApplicationDoesNotExistException", () =>
              Effect.succeed(undefined),
            ),
          );
        return response?.application;
      });

      const syncTags = Effect.fn(function* (
        arn: string,
        desiredTags: Record<string, string>,
      ) {
        const observed = yield* codedeploy
          .listTagsForResource({ ResourceArn: arn })
          .pipe(Effect.catch(() => Effect.succeed(undefined)));
        const { removed, upsert } = diffTags(
          toTagRecord(observed?.Tags),
          desiredTags,
        );
        if (upsert.length > 0) {
          yield* codedeploy.tagResource({ ResourceArn: arn, Tags: upsert });
        }
        if (removed.length > 0) {
          yield* codedeploy.untagResource({
            ResourceArn: arn,
            TagKeys: removed,
          });
        }
      });

      return {
        stables: ["applicationName", "applicationId", "computePlatform"],

        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return undefined;
          if (
            (yield* toName(id, olds ?? {})) !== (yield* toName(id, news ?? {}))
          ) {
            return { action: "replace" } as const;
          }
          // Compute platform is immutable — replace on change.
          if (
            (news?.computePlatform ?? "Server") !==
            (olds?.computePlatform ?? "Server")
          ) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name =
            output?.applicationName ?? (yield* toName(id, olds ?? {}));
          const application = yield* getApplication(name);
          if (application?.applicationId === undefined) return undefined;
          const arn = applicationArn(region, accountId, name);
          const attrs = {
            applicationName: application.applicationName ?? name,
            applicationId: application.applicationId,
            applicationArn: arn,
            computePlatform: application.computePlatform ?? "Server",
          };
          const tags = yield* codedeploy
            .listTagsForResource({ ResourceArn: arn })
            .pipe(
              Effect.map((res) => toTagRecord(res.Tags)),
              Effect.catch(() => Effect.succeed({})),
            );
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name = output?.applicationName ?? (yield* toName(id, news));
          const arn = applicationArn(region, accountId, name);
          const computePlatform = news.computePlatform ?? "Server";
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };

          // 1. Observe — cloud state is authoritative.
          let application = yield* getApplication(name);

          // 2. Ensure — create if missing. Tolerate an already-exists race.
          if (application?.applicationId === undefined) {
            yield* codedeploy
              .createApplication({
                applicationName: name,
                computePlatform,
                tags: Object.entries(desiredTags).map(([Key, Value]) => ({
                  Key,
                  Value,
                })),
              })
              .pipe(
                Effect.catchTag("ApplicationAlreadyExistsException", () =>
                  Effect.succeed(undefined),
                ),
              );
            application = yield* getApplication(name);
          }

          // 3. Sync tags — diff against OBSERVED cloud tags.
          yield* syncTags(arn, desiredTags);

          // 4. Return fresh attributes.
          yield* session.note(name);
          return {
            applicationName: application?.applicationName ?? name,
            applicationId: application?.applicationId ?? "",
            applicationArn: arn,
            computePlatform: application?.computePlatform ?? computePlatform,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // DeleteApplication is idempotent — deleting a non-existent
          // application succeeds (no not-found variant in its error union).
          yield* codedeploy.deleteApplication({
            applicationName: output.applicationName,
          });
        }),

        list: () =>
          Effect.gen(function* () {
            const { accountId, region } = yield* AWSEnvironment.current;
            const names = yield* codedeploy.listApplications.pages({}).pipe(
              Stream.runCollect,
              Effect.map((chunk) =>
                Array.from(chunk).flatMap((page) => page.applications ?? []),
              ),
            );
            return names.map((name) => ({
              applicationName: name,
              applicationId: "",
              applicationArn: applicationArn(region, accountId, name),
              computePlatform: "",
            }));
          }),
      };
    }),
  );

import * as codedeploy from "@distilled.cloud/aws/codedeploy";
import type * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import * as Stream from "effect/Stream";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { toWireSeconds } from "../../Util/Duration.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";

/**
 * Zonal deployment behaviour (EC2/on-prem `Server` platform): deploy one
 * Availability Zone at a time, monitoring each zone before moving on.
 * Mirrors the wire `ZonalConfig` with `Duration.Input` monitor durations
 * (CodeDeploy's wire unit for both is whole seconds).
 */
export interface ZonalConfigProps {
  /**
   * How long to monitor the FIRST zone after it finishes before starting
   * the next zone. Wire unit: whole seconds.
   * @default monitorDuration
   */
  firstZoneMonitorDuration?: Duration.Input;
  /**
   * How long to monitor each subsequent zone after it finishes before
   * starting the next one. Wire unit: whole seconds.
   * @default 0
   */
  monitorDuration?: Duration.Input;
  /**
   * Minimum healthy hosts required per Availability Zone while deploying.
   */
  minimumHealthyHostsPerZone?: codedeploy.MinimumHealthyHostsPerZone;
}

/** Convert the zonal-config props to the CodeDeploy wire shape (seconds). */
const toWireZonalConfig = (
  props: ZonalConfigProps | undefined,
): codedeploy.ZonalConfig | undefined =>
  props === undefined
    ? undefined
    : {
        firstZoneMonitorDurationInSeconds: toWireSeconds(
          props.firstZoneMonitorDuration,
        ),
        monitorDurationInSeconds: toWireSeconds(props.monitorDuration),
        minimumHealthyHostsPerZone: props.minimumHealthyHostsPerZone,
      };

export interface DeploymentConfigProps {
  /**
   * Name of the deployment configuration (1-100 chars). If omitted a
   * deterministic physical name is generated. Changing the name replaces
   * the configuration.
   */
  deploymentConfigName?: string;
  /**
   * The compute platform the configuration applies to. Immutable — changing
   * it replaces the configuration.
   * @default "Server"
   */
  computePlatform?: "Server" | "Lambda" | "ECS";
  /**
   * Minimum healthy hosts during the deployment (`HOST_COUNT` or
   * `FLEET_PERCENT`). `Server` platform only.
   */
  minimumHealthyHosts?: codedeploy.MinimumHealthyHosts;
  /**
   * How traffic shifts to the new version (`TimeBasedCanary`,
   * `TimeBasedLinear`, or `AllAtOnce`). `Lambda`/`ECS` platforms. The
   * `canaryInterval`/`linearInterval` fields are whole minutes (the wire
   * unit is semantically part of the AWS field).
   */
  trafficRoutingConfig?: codedeploy.TrafficRoutingConfig;
  /**
   * Deploy one Availability Zone at a time with per-zone monitor
   * durations. `Server` platform only.
   */
  zonalConfig?: ZonalConfigProps;
}

export interface DeploymentConfig extends Resource<
  "AWS.CodeDeploy.DeploymentConfig",
  DeploymentConfigProps,
  {
    /** Physical name of the deployment configuration. */
    deploymentConfigName: string;
    /** Unique CodeDeploy-assigned deployment-config ID. */
    deploymentConfigId: string;
    /** ARN of the deployment configuration. */
    deploymentConfigArn: string;
    /** The compute platform (`Lambda`, `Server`, or `ECS`). */
    computePlatform: string;
  },
  never,
  Providers
> {}

/**
 * A custom AWS CodeDeploy deployment configuration — the rules for how
 * traffic shifts during a deployment (canary/linear traffic routing for
 * `Lambda`/`ECS`, minimum-healthy-hosts and zonal rollout for `Server`).
 * Deployment configurations are immutable: any change replaces the
 * configuration.
 *
 * ### Creating a Deployment Config
 * **Example:** Lambda Canary Config
 * ```typescript
 * const config = yield* CodeDeploy.DeploymentConfig("canary", {
 *   computePlatform: "Lambda",
 *   trafficRoutingConfig: {
 *     type: "TimeBasedCanary",
 *     timeBasedCanary: { canaryPercentage: 10, canaryInterval: 5 },
 *   },
 * });
 * ```
 *
 * **Example:** Server Config with Minimum Healthy Hosts
 * ```typescript
 * const config = yield* CodeDeploy.DeploymentConfig("half-fleet", {
 *   computePlatform: "Server",
 *   minimumHealthyHosts: { type: "FLEET_PERCENT", value: 50 },
 * });
 * ```
 *
 * @resource
 */
export const DeploymentConfig = Resource<DeploymentConfig>(
  "AWS.CodeDeploy.DeploymentConfig",
);

/** Build the ARN for a CodeDeploy deployment configuration. */
const deploymentConfigArn = (
  region: string,
  account: string,
  name: string,
): string => `arn:aws:codedeploy:${region}:${account}:deploymentconfig:${name}`;

export const DeploymentConfigProvider = () =>
  Provider.effect(
    DeploymentConfig,
    Effect.gen(function* () {
      const toName = (id: string, props: Partial<DeploymentConfigProps>) =>
        props.deploymentConfigName
          ? Effect.succeed(props.deploymentConfigName)
          : createPhysicalName({ id, maxLength: 100 });

      const getConfig = Effect.fn(function* (name: string) {
        const response = yield* codedeploy
          .getDeploymentConfig({ deploymentConfigName: name })
          .pipe(
            Effect.catchTag("DeploymentConfigDoesNotExistException", () =>
              Effect.succeed(undefined),
            ),
          );
        return response?.deploymentConfigInfo;
      });

      return {
        stables: [
          "deploymentConfigName",
          "deploymentConfigId",
          "computePlatform",
        ],

        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return undefined;
          if (
            (yield* toName(id, olds ?? {})) !== (yield* toName(id, news ?? {}))
          ) {
            return { action: "replace" } as const;
          }
          // Deployment configurations are immutable — any settings change
          // replaces the configuration.
          const key = (props: Partial<DeploymentConfigProps>) =>
            JSON.stringify([
              props.computePlatform ?? "Server",
              props.minimumHealthyHosts,
              props.trafficRoutingConfig,
              toWireZonalConfig(props.zonalConfig),
            ]);
          if (key(olds ?? {}) !== key(news ?? {})) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name =
            output?.deploymentConfigName ?? (yield* toName(id, olds ?? {}));
          const config = yield* getConfig(name);
          if (config?.deploymentConfigId === undefined) return undefined;
          // Deployment configurations cannot be tagged, so there is no
          // ownership marker to check — a name match is treated as ours.
          return {
            deploymentConfigName: config.deploymentConfigName ?? name,
            deploymentConfigId: config.deploymentConfigId,
            deploymentConfigArn: deploymentConfigArn(region, accountId, name),
            computePlatform: config.computePlatform ?? "Server",
          };
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name =
            output?.deploymentConfigName ?? (yield* toName(id, news));
          const computePlatform = news.computePlatform ?? "Server";

          // 1. Observe — cloud state is authoritative.
          let config = yield* getConfig(name);

          // 2. Ensure — create if missing (configs are immutable, so there
          //    is nothing to sync). Tolerate an already-exists race.
          if (config?.deploymentConfigId === undefined) {
            yield* codedeploy
              .createDeploymentConfig({
                deploymentConfigName: name,
                computePlatform,
                minimumHealthyHosts: news.minimumHealthyHosts,
                trafficRoutingConfig: news.trafficRoutingConfig,
                zonalConfig: toWireZonalConfig(news.zonalConfig),
              })
              .pipe(
                Effect.catchTag("DeploymentConfigAlreadyExistsException", () =>
                  Effect.succeed(undefined),
                ),
              );
            config = yield* getConfig(name);
          }

          // 3. Return fresh attributes.
          yield* session.note(name);
          return {
            deploymentConfigName: config?.deploymentConfigName ?? name,
            deploymentConfigId: config?.deploymentConfigId ?? "",
            deploymentConfigArn: deploymentConfigArn(region, accountId, name),
            computePlatform: config?.computePlatform ?? computePlatform,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // A config still referenced by a deployment group fails with
          // DeploymentConfigInUseException — the engine deletes dependents
          // first, but the reference release is eventually consistent, so
          // retry through it (bounded). Deleting a non-existent config
          // succeeds (no not-found variant in the typed error union).
          yield* codedeploy
            .deleteDeploymentConfig({
              deploymentConfigName: output.deploymentConfigName,
            })
            .pipe(
              Effect.retry({
                while: (e): boolean =>
                  e._tag === "DeploymentConfigInUseException",
                schedule: Schedule.max([
                  Schedule.fixed(3000),
                  Schedule.recurs(10),
                ]),
              }),
            );
        }),

        list: () =>
          Effect.gen(function* () {
            const { accountId, region } = yield* AWSEnvironment.current;
            const names = yield* codedeploy.listDeploymentConfigs
              .pages({})
              .pipe(
                Stream.runCollect,
                Effect.map((chunk) =>
                  Array.from(chunk).flatMap(
                    (page) => page.deploymentConfigsList ?? [],
                  ),
                ),
              );
            return (
              names
                // Predefined CodeDeployDefault.* configurations are
                // AWS-managed and cannot be deleted — never ours.
                .filter((name) => !name.startsWith("CodeDeployDefault."))
                .map((name) => ({
                  deploymentConfigName: name,
                  deploymentConfigId: "",
                  deploymentConfigArn: deploymentConfigArn(
                    region,
                    accountId,
                    name,
                  ),
                  computePlatform: "",
                }))
            );
          }),
      };
    }),
  );

import * as codedeploy from "@distilled.cloud/aws/codedeploy";
import type * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, diffTags, hasAlchemyTags } from "../../Tags.ts";
import { toWireMinutes } from "../../Util/Duration.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";

/**
 * Blue/green deployment behaviour for a deployment group. Mirrors the wire
 * `BlueGreenDeploymentConfiguration` with `Duration.Input` wait times
 * (CodeDeploy's wire unit for both is whole minutes).
 */
export interface BlueGreenDeploymentConfigurationProps {
  /**
   * What happens to the original (blue) instances after a successful
   * blue/green deployment.
   */
  terminateBlueInstancesOnDeploymentSuccess?: {
    /**
     * `TERMINATE` the blue instances (after `terminationWaitTime`) or
     * `KEEP_ALIVE` them deregistered from the load balancer.
     */
    action?: codedeploy.InstanceAction;
    /**
     * How long to wait after a successful deployment before terminating
     * the blue instances. Wire unit: whole minutes.
     */
    terminationWaitTime?: Duration.Input;
  };
  /**
   * How traffic is rerouted to the green fleet once it is provisioned.
   */
  deploymentReadyOption?: {
    /**
     * `CONTINUE_DEPLOYMENT` reroutes automatically; `STOP_DEPLOYMENT`
     * waits for {@link ContinueDeployment} (up to `waitTime`).
     */
    actionOnTimeout?: codedeploy.DeploymentReadyAction;
    /**
     * How long to wait for a manual continue before the deployment stops
     * (only with `actionOnTimeout: "STOP_DEPLOYMENT"`). Wire unit: whole
     * minutes.
     */
    waitTime?: Duration.Input;
  };
  /**
   * How the green fleet's instances are provisioned (discover existing or
   * copy the Auto Scaling group).
   */
  greenFleetProvisioningOption?: codedeploy.GreenFleetProvisioningOption;
}

/** Convert the blue/green props to the CodeDeploy wire shape (minutes). */
const toWireBlueGreen = (
  props: BlueGreenDeploymentConfigurationProps | undefined,
): codedeploy.BlueGreenDeploymentConfiguration | undefined =>
  props === undefined
    ? undefined
    : {
        terminateBlueInstancesOnDeploymentSuccess:
          props.terminateBlueInstancesOnDeploymentSuccess === undefined
            ? undefined
            : {
                action: props.terminateBlueInstancesOnDeploymentSuccess.action,
                terminationWaitTimeInMinutes: toWireMinutes(
                  props.terminateBlueInstancesOnDeploymentSuccess
                    .terminationWaitTime,
                ),
              },
        deploymentReadyOption:
          props.deploymentReadyOption === undefined
            ? undefined
            : {
                actionOnTimeout: props.deploymentReadyOption.actionOnTimeout,
                waitTimeInMinutes: toWireMinutes(
                  props.deploymentReadyOption.waitTime,
                ),
              },
        greenFleetProvisioningOption: props.greenFleetProvisioningOption,
      };

export interface DeploymentGroupProps {
  /**
   * Name of the CodeDeploy application that owns the group. Pass an
   * `Application`'s `applicationName` attribute. Immutable — changing it
   * replaces the deployment group.
   */
  applicationName: string;
  /**
   * Name of the deployment group (1-100 chars). If omitted a deterministic
   * physical name is generated. Changing the name replaces the group.
   */
  deploymentGroupName?: string;
  /**
   * ARN of the IAM service role that grants CodeDeploy access to the target
   * compute resources. Required.
   */
  serviceRoleArn: string;
  /**
   * Name of the deployment configuration (predefined like
   * `CodeDeployDefault.LambdaAllAtOnce`, or a custom `DeploymentConfig`).
   */
  deploymentConfigName?: string;
  /**
   * How the deployment routes traffic (in-place vs. blue/green).
   */
  deploymentStyle?: codedeploy.DeploymentStyle;
  /**
   * Automatic rollback behaviour on deployment failure or alarm.
   */
  autoRollbackConfiguration?: codedeploy.AutoRollbackConfiguration;
  /**
   * CloudWatch alarms that can stop a deployment.
   */
  alarmConfiguration?: codedeploy.AlarmConfiguration;
  /**
   * Load-balancer configuration used for traffic shifting.
   */
  loadBalancerInfo?: codedeploy.LoadBalancerInfo;
  /**
   * Blue/green deployment configuration (green-fleet provisioning, traffic
   * ready-options, blue-instance termination). Wait times accept
   * `Duration.Input` (e.g. `"5 minutes"`).
   */
  blueGreenDeploymentConfiguration?: BlueGreenDeploymentConfigurationProps;
  /**
   * EC2 tag filters selecting the instances to deploy to (EC2/on-prem
   * `Server` platform).
   */
  ec2TagFilters?: codedeploy.EC2TagFilter[];
  /**
   * Auto Scaling group names to deploy to (EC2/on-prem `Server` platform).
   */
  autoScalingGroups?: string[];
  /**
   * ECS services (cluster + service) targeted by blue/green ECS deployments.
   */
  ecsServices?: codedeploy.ECSService[];
  /**
   * SNS/notification triggers fired on deployment lifecycle events.
   */
  triggerConfigurations?: codedeploy.TriggerConfig[];
  /**
   * User-defined tags.
   */
  tags?: Record<string, string>;
}

export interface DeploymentGroup extends Resource<
  "AWS.CodeDeploy.DeploymentGroup",
  DeploymentGroupProps,
  {
    /** Physical name of the deployment group. */
    deploymentGroupName: string;
    /** Unique CodeDeploy-assigned deployment-group ID. */
    deploymentGroupId: string;
    /** ARN of the deployment group. */
    deploymentGroupArn: string;
    /** Name of the application this group belongs to. */
    applicationName: string;
    /** ARN of the service role CodeDeploy assumes for deployments. */
    serviceRoleArn: string;
  },
  never,
  Providers
> {}

/**
 * An AWS CodeDeploy deployment group — the set of target instances/functions
 * plus the deployment configuration for one {@link Application}. For the
 * `Lambda` compute platform a group ties a service role and a deployment
 * config (e.g. `CodeDeployDefault.LambdaAllAtOnce`) to an application.
 *
 * ### Creating a Deployment Group
 * **Example:** Lambda Deployment Group
 * ```typescript
 * const app = yield* CodeDeploy.Application("api", { computePlatform: "Lambda" });
 * const group = yield* CodeDeploy.DeploymentGroup("prod", {
 *   applicationName: app.applicationName,
 *   serviceRoleArn: role.roleArn,
 *   deploymentConfigName: "CodeDeployDefault.LambdaAllAtOnce",
 *   deploymentStyle: {
 *     deploymentType: "BLUE_GREEN",
 *     deploymentOption: "WITH_TRAFFIC_CONTROL",
 *   },
 *   autoRollbackConfiguration: {
 *     enabled: true,
 *     events: ["DEPLOYMENT_FAILURE"],
 *   },
 * });
 * ```
 *
 * @resource
 */
export const DeploymentGroup = Resource<DeploymentGroup>(
  "AWS.CodeDeploy.DeploymentGroup",
);

/** Build the ARN for a CodeDeploy deployment group. */
const deploymentGroupArn = (
  region: string,
  account: string,
  appName: string,
  groupName: string,
): string =>
  `arn:aws:codedeploy:${region}:${account}:deploymentgroup:${appName}/${groupName}`;

/**
 * Retry an effect while CodeDeploy reports that it cannot yet assume the
 * service role. A freshly-created IAM role's trust relationship is eventually
 * consistent, so `InvalidRoleException` immediately after role creation is a
 * transient propagation error, not a permanent failure. Wrapped in an
 * explicitly-typed helper so the retry's conditional type never widens the
 * provider layer in declaration emit (see PATTERNS §7).
 */
const retryThroughRolePropagation = <A, E extends { _tag: string }, R>(
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> =>
  effect.pipe(
    Effect.retry({
      while: (e: E) => e._tag === "InvalidRoleException",
      schedule: Schedule.max([Schedule.fixed(2000), Schedule.recurs(15)]),
    }),
  );

/** Convert a CodeDeploy wire tag list into a plain record. */
const toTagRecord = (
  tags: ReadonlyArray<{ Key?: string; Value?: string }> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    (tags ?? [])
      .filter(
        (tag): tag is { Key: string; Value: string } =>
          typeof tag.Key === "string" && typeof tag.Value === "string",
      )
      .map((tag) => [tag.Key, tag.Value]),
  );

export const DeploymentGroupProvider = () =>
  Provider.effect(
    DeploymentGroup,
    Effect.gen(function* () {
      const toName = (id: string, props: Partial<DeploymentGroupProps>) =>
        props.deploymentGroupName
          ? Effect.succeed(props.deploymentGroupName)
          : createPhysicalName({ id, maxLength: 100 });

      const getGroup = Effect.fn(function* (
        appName: string,
        groupName: string,
      ) {
        const response = yield* codedeploy
          .getDeploymentGroup({
            applicationName: appName,
            deploymentGroupName: groupName,
          })
          .pipe(
            Effect.catchTag(
              [
                "DeploymentGroupDoesNotExistException",
                "ApplicationDoesNotExistException",
              ],
              () => Effect.succeed(undefined),
            ),
          );
        return response?.deploymentGroupInfo;
      });

      const syncTags = Effect.fn(function* (
        arn: string,
        desiredTags: Record<string, string>,
      ) {
        const observed = yield* codedeploy
          .listTagsForResource({ ResourceArn: arn })
          .pipe(Effect.catch(() => Effect.succeed(undefined)));
        const { removed, upsert } = diffTags(
          toTagRecord(observed?.Tags),
          desiredTags,
        );
        if (upsert.length > 0) {
          yield* codedeploy.tagResource({ ResourceArn: arn, Tags: upsert });
        }
        if (removed.length > 0) {
          yield* codedeploy.untagResource({
            ResourceArn: arn,
            TagKeys: removed,
          });
        }
      });

      return {
        stables: [
          "deploymentGroupName",
          "deploymentGroupId",
          "applicationName",
        ],

        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return undefined;
          if (
            (yield* toName(id, olds ?? {})) !== (yield* toName(id, news ?? {}))
          ) {
            return { action: "replace" } as const;
          }
          // The parent application is immutable — replace on change.
          if ((news?.applicationName ?? "") !== (olds?.applicationName ?? "")) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const appName = output?.applicationName ?? olds?.applicationName;
          if (appName === undefined) return undefined;
          const name =
            output?.deploymentGroupName ?? (yield* toName(id, olds ?? {}));
          const group = yield* getGroup(appName, name);
          if (group?.deploymentGroupId === undefined) return undefined;
          const arn = deploymentGroupArn(region, accountId, appName, name);
          const attrs = {
            deploymentGroupName: group.deploymentGroupName ?? name,
            deploymentGroupId: group.deploymentGroupId,
            deploymentGroupArn: arn,
            applicationName: group.applicationName ?? appName,
            serviceRoleArn: group.serviceRoleArn ?? "",
          };
          const tags = yield* codedeploy
            .listTagsForResource({ ResourceArn: arn })
            .pipe(
              Effect.map((res) => toTagRecord(res.Tags)),
              Effect.catch(() => Effect.succeed({})),
            );
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const appName = news.applicationName;
          const name = output?.deploymentGroupName ?? (yield* toName(id, news));
          const arn = deploymentGroupArn(region, accountId, appName, name);
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };

          // 1. Observe — cloud state is authoritative.
          let group = yield* getGroup(appName, name);

          // 2. Ensure — create if missing; otherwise converge via update.
          if (group?.deploymentGroupId === undefined) {
            yield* retryThroughRolePropagation(
              codedeploy.createDeploymentGroup({
                applicationName: appName,
                deploymentGroupName: name,
                serviceRoleArn: news.serviceRoleArn,
                deploymentConfigName: news.deploymentConfigName,
                deploymentStyle: news.deploymentStyle,
                autoRollbackConfiguration: news.autoRollbackConfiguration,
                alarmConfiguration: news.alarmConfiguration,
                loadBalancerInfo: news.loadBalancerInfo,
                blueGreenDeploymentConfiguration: toWireBlueGreen(
                  news.blueGreenDeploymentConfiguration,
                ),
                ec2TagFilters: news.ec2TagFilters,
                autoScalingGroups: news.autoScalingGroups,
                ecsServices: news.ecsServices,
                triggerConfigurations: news.triggerConfigurations,
                tags: Object.entries(desiredTags).map(([Key, Value]) => ({
                  Key,
                  Value,
                })),
              }),
            ).pipe(
              Effect.catchTag("DeploymentGroupAlreadyExistsException", () =>
                Effect.succeed(undefined),
              ),
            );
            group = yield* getGroup(appName, name);
          } else {
            // 3. Sync — converge mutable configuration in place.
            yield* codedeploy.updateDeploymentGroup({
              applicationName: appName,
              currentDeploymentGroupName: name,
              serviceRoleArn: news.serviceRoleArn,
              deploymentConfigName: news.deploymentConfigName,
              deploymentStyle: news.deploymentStyle,
              autoRollbackConfiguration: news.autoRollbackConfiguration,
              alarmConfiguration: news.alarmConfiguration,
              loadBalancerInfo: news.loadBalancerInfo,
              blueGreenDeploymentConfiguration: toWireBlueGreen(
                news.blueGreenDeploymentConfiguration,
              ),
              ec2TagFilters: news.ec2TagFilters,
              autoScalingGroups: news.autoScalingGroups,
              ecsServices: news.ecsServices,
              triggerConfigurations: news.triggerConfigurations,
            });
            group = yield* getGroup(appName, name);
          }

          // 3b. Sync tags — diff against OBSERVED cloud tags.
          yield* syncTags(arn, desiredTags);

          // 4. Return fresh attributes.
          yield* session.note(name);
          return {
            deploymentGroupName: group?.deploymentGroupName ?? name,
            deploymentGroupId: group?.deploymentGroupId ?? "",
            deploymentGroupArn: arn,
            applicationName: group?.applicationName ?? appName,
            serviceRoleArn: group?.serviceRoleArn ?? news.serviceRoleArn,
          };
        }),

        delete: Effect.fn(function* ({ output, olds }) {
          const appName = output.applicationName || olds?.applicationName;
          if (appName === undefined) return;
          // DeleteDeploymentGroup is idempotent — deleting a non-existent
          // group (or one under a deleted application) succeeds; its typed
          // error union has no not-found variants.
          yield* codedeploy.deleteDeploymentGroup({
            applicationName: appName,
            deploymentGroupName: output.deploymentGroupName,
          });
        }),

        // Deployment groups are scoped to an application; there is no global
        // enumeration without knowing the application name.
        list: () => Effect.succeed([]),
      };
    }),
  );

import * as codepipeline from "@distilled.cloud/aws/codepipeline";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, diffTags, hasAlchemyTags } from "../../Tags.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";

/**
 * Where a pipeline stores the artifacts it passes between stages.
 */
export interface PipelineArtifactStore {
  /**
   * Store type. Only `S3` is supported by CodePipeline.
   * @default "S3"
   */
  type?: "S3";
  /**
   * Name of the S3 bucket that holds pipeline artifacts.
   */
  location: string;
  /**
   * Optional customer-managed KMS key for artifact encryption.
   */
  encryptionKey?: {
    /** Key id or ARN. */
    id: string;
    /** Key type. */
    type: "KMS";
  };
}

/**
 * A single action within a stage — a source pull, a build, a deploy, etc.
 */
export interface PipelineActionConfig {
  /** Unique name of the action within its stage. */
  name: string;
  /** Action category. */
  category:
    | "Source"
    | "Build"
    | "Deploy"
    | "Test"
    | "Invoke"
    | "Approval"
    | "Compute";
  /** Who owns the action provider. */
  owner: "AWS" | "ThirdParty" | "Custom";
  /**
   * Action provider, e.g. `S3`, `CodeBuild`, `CodeDeploy`,
   * `CodeStarSourceConnection`.
   */
  provider: string;
  /**
   * Provider version.
   * @default "1"
   */
  version?: string;
  /**
   * Provider-specific configuration key/value map (e.g. `{ ProjectName }`
   * for CodeBuild, `{ S3Bucket, S3ObjectKey }` for an S3 source).
   */
  configuration?: Record<string, string>;
  /** Names of artifacts this action consumes. */
  inputArtifacts?: string[];
  /** Names of artifacts this action produces. */
  outputArtifacts?: string[];
  /** Order of execution within the stage (actions with the same order run in parallel). */
  runOrder?: number;
  /** Region the action runs in (for cross-region actions). */
  region?: string;
  /** IAM role the action assumes. */
  roleArn?: string;
  /** Variable namespace for referencing this action's output variables. */
  namespace?: string;
}

/**
 * A pipeline stage: a named group of actions.
 */
export interface PipelineStageConfig {
  /** Unique name of the stage. */
  name: string;
  /** Actions that make up the stage. */
  actions: PipelineActionConfig[];
}

export interface PipelineProps {
  /**
   * Name of the pipeline. If omitted a deterministic physical name is
   * generated. Changing the name replaces the pipeline.
   */
  pipelineName?: string;
  /**
   * ARN of the IAM role CodePipeline assumes. Must trust
   * `codepipeline.amazonaws.com`.
   */
  roleArn: string;
  /**
   * Artifact store for passing outputs between stages.
   */
  artifactStore: PipelineArtifactStore;
  /**
   * Ordered list of stages. A pipeline needs at least two stages, the first
   * of which contains a single source action.
   */
  stages: PipelineStageConfig[];
  /**
   * Pipeline type.
   * @default "V2"
   */
  pipelineType?: "V1" | "V2";
  /**
   * Execution mode (V2 pipelines).
   * @default "SUPERSEDED"
   */
  executionMode?: "QUEUED" | "SUPERSEDED" | "PARALLEL";
  /**
   * User-defined tags.
   */
  tags?: Record<string, string>;
}

export interface Pipeline extends Resource<
  "AWS.CodePipeline.Pipeline",
  PipelineProps,
  {
    /** Physical name of the pipeline. */
    pipelineName: string;
    /** ARN of the pipeline. */
    pipelineArn: string;
    /** Version number, incremented by CodePipeline on every structure update. */
    pipelineVersion: number;
  },
  never,
  Providers
> {}

/**
 * An AWS CodePipeline continuous-delivery pipeline: an ordered set of
 * stages, each running one or more actions (source → build → deploy), with
 * an S3 artifact store carrying outputs between them.
 *
 * Defining and updating the pipeline is instant. Pipelines that use a git
 * source require a CodeConnections connection whose OAuth handshake is
 * completed manually — use an S3 source to avoid the handshake.
 * ### Creating a Pipeline
 * **Example:** S3-Source → CodeBuild Pipeline
 * ```typescript
 * const pipeline = yield* CodePipeline.Pipeline("Release", {
 *   roleArn: role.roleArn,
 *   artifactStore: { type: "S3", location: artifactBucket.bucketName },
 *   stages: [
 *     {
 *       name: "Source",
 *       actions: [{
 *         name: "S3Source",
 *         category: "Source",
 *         owner: "AWS",
 *         provider: "S3",
 *         outputArtifacts: ["SourceOutput"],
 *         configuration: {
 *           S3Bucket: sourceBucket.bucketName,
 *           S3ObjectKey: "source.zip",
 *           PollForSourceChanges: "false",
 *         },
 *       }],
 *     },
 *     {
 *       name: "Build",
 *       actions: [{
 *         name: "Build",
 *         category: "Build",
 *         owner: "AWS",
 *         provider: "CodeBuild",
 *         inputArtifacts: ["SourceOutput"],
 *         configuration: { ProjectName: project.projectName },
 *       }],
 *     },
 *   ],
 * });
 * ```
 *
 * @resource
 */
export const Pipeline = Resource<Pipeline>("AWS.CodePipeline.Pipeline");

/** Convert a CodePipeline wire tag list into a plain record. */
const toTagRecord = (
  tags: ReadonlyArray<{ key?: string; value?: string }> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    (tags ?? [])
      .filter(
        (tag): tag is { key: string; value: string } =>
          typeof tag.key === "string" && typeof tag.value === "string",
      )
      .map((tag) => [tag.key, tag.value]),
  );

const toWireArtifactStore = (
  store: PipelineArtifactStore,
): codepipeline.ArtifactStore => ({
  type: store.type ?? "S3",
  location: store.location,
  encryptionKey: store.encryptionKey,
});

const toWireStages = (
  stages: PipelineStageConfig[],
): codepipeline.StageDeclaration[] =>
  stages.map((stage) => ({
    name: stage.name,
    actions: stage.actions.map((action) => ({
      name: action.name,
      actionTypeId: {
        category: action.category,
        owner: action.owner,
        provider: action.provider,
        version: action.version ?? "1",
      },
      runOrder: action.runOrder,
      configuration: action.configuration,
      inputArtifacts: action.inputArtifacts?.map((n) => ({ name: n })),
      outputArtifacts: action.outputArtifacts?.map((n) => ({ name: n })),
      region: action.region,
      roleArn: action.roleArn,
      namespace: action.namespace,
    })),
  }));

const toWireDeclaration = (
  name: string,
  props: PipelineProps,
): codepipeline.PipelineDeclaration => ({
  name,
  roleArn: props.roleArn,
  artifactStore: toWireArtifactStore(props.artifactStore),
  stages: toWireStages(props.stages),
  pipelineType: props.pipelineType ?? "V2",
  executionMode: props.executionMode,
});

/**
 * CodePipeline validates the pipeline role at create time; a freshly created
 * IAM role is not yet assumable, surfacing as an `InvalidStructureException`
 * whose message mentions the role cannot be assumed / is not authorized.
 * Retry (bounded) through IAM propagation. The explicit return annotation
 * keeps the retry's conditional type out of declaration emit (PATTERNS §7).
 */
const retryIamPropagation = <
  A,
  E extends { readonly _tag: string; readonly message?: string },
  R,
>(
  effect: Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> =>
  effect.pipe(
    Effect.retry({
      while: (e) => {
        const message = (e.message ?? "").toLowerCase();
        return (
          e._tag === "InvalidStructureException" &&
          (message.includes("not authorized") ||
            message.includes("cannot be assumed") ||
            message.includes("unable to assume"))
        );
      },
      schedule: Schedule.max([
        Schedule.fixed("3 seconds"),
        Schedule.recurs(10),
      ]),
    }),
  );

export const PipelineProvider = () =>
  Provider.effect(
    Pipeline,
    Effect.gen(function* () {
      const toName = (id: string, props: Partial<PipelineProps>) =>
        props.pipelineName
          ? Effect.succeed(props.pipelineName)
          : createPhysicalName({ id, maxLength: 100 });

      /** Read a pipeline; a missing pipeline reads as absent. */
      const getPipeline = Effect.fn(function* (name: string) {
        return yield* codepipeline
          .getPipeline({ name })
          .pipe(
            Effect.catchTag("PipelineNotFoundException", () =>
              Effect.succeed(undefined),
            ),
          );
      });

      const syncTags = Effect.fn(function* (
        arn: string,
        desiredTags: Record<string, string>,
      ) {
        const observed = yield* codepipeline
          .listTagsForResource({ resourceArn: arn })
          .pipe(Effect.catch(() => Effect.succeed(undefined)));
        const { removed, upsert } = diffTags(
          toTagRecord(observed?.tags),
          desiredTags,
        );
        if (upsert.length > 0) {
          yield* codepipeline.tagResource({
            resourceArn: arn,
            tags: upsert.map(({ Key, Value }) => ({ key: Key, value: Value })),
          });
        }
        if (removed.length > 0) {
          yield* codepipeline.untagResource({
            resourceArn: arn,
            tagKeys: removed,
          });
        }
      });

      return {
        stables: ["pipelineName", "pipelineArn"],

        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return undefined;
          if (
            (yield* toName(id, olds ?? {})) !== (yield* toName(id, news ?? {}))
          ) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const name = output?.pipelineName ?? (yield* toName(id, olds ?? {}));
          const found = yield* getPipeline(name);
          if (found?.metadata?.pipelineArn === undefined) return undefined;
          const attrs = {
            pipelineName: found.pipeline?.name ?? name,
            pipelineArn: found.metadata.pipelineArn,
            pipelineVersion: found.pipeline?.version ?? 1,
          };
          const tags = yield* codepipeline
            .listTagsForResource({ resourceArn: attrs.pipelineArn })
            .pipe(
              Effect.map((res) => toTagRecord(res.tags)),
              Effect.catch(() => Effect.succeed({})),
            );
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name = output?.pipelineName ?? (yield* toName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };
          const declaration = toWireDeclaration(name, news);

          // 1. Observe — cloud state is authoritative.
          let observed = yield* getPipeline(name);

          // 2. Ensure — create if missing; tolerate the name-in-use race.
          if (observed === undefined) {
            yield* retryIamPropagation(
              codepipeline.createPipeline({
                pipeline: declaration,
                tags: Object.entries(desiredTags).map(([key, value]) => ({
                  key,
                  value,
                })),
              }),
            ).pipe(
              Effect.catchTag("PipelineNameInUseException", () => Effect.void),
            );
            observed = yield* getPipeline(name);
          } else {
            // 3. Sync — updatePipeline is a full upsert of the declaration.
            yield* retryIamPropagation(
              codepipeline.updatePipeline({ pipeline: declaration }),
            );
            observed = yield* getPipeline(name);
          }

          const arn =
            observed?.metadata?.pipelineArn ??
            `arn:aws:codepipeline:${region}:${accountId}:${name}`;

          // 3b. Sync tags — diff against OBSERVED cloud tags.
          yield* syncTags(arn, desiredTags);

          // 4. Return fresh attributes.
          yield* session.note(name);
          return {
            pipelineName: observed?.pipeline?.name ?? name,
            pipelineArn: arn,
            pipelineVersion: observed?.pipeline?.version ?? 1,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deletePipeline is idempotent — a missing pipeline returns success.
          yield* codepipeline.deletePipeline({ name: output.pipelineName });
        }),

        list: () =>
          codepipeline.listPipelines.pages({}).pipe(
            Stream.runCollect,
            Effect.flatMap((chunk) =>
              Effect.gen(function* () {
                const { accountId, region } = yield* AWSEnvironment.current;
                return Array.from(chunk)
                  .flatMap((page) => page.pipelines ?? [])
                  .flatMap((p) =>
                    p.name !== undefined
                      ? [
                          {
                            pipelineName: p.name,
                            pipelineArn: `arn:aws:codepipeline:${region}:${accountId}:${p.name}`,
                            pipelineVersion: p.version ?? 1,
                          },
                        ]
                      : [],
                  );
              }),
            ),
          ),
      };
    }),
  );

import * as config from "@distilled.cloud/aws/config-service";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import {
  createInternalTags,
  createTagsList,
  diffTags,
  hasAlchemyTags,
} from "../../Tags.ts";
import type { Providers } from "../Providers.ts";

export interface AggregationAuthorizationProps {
  /**
   * The 12-digit account ID of the aggregator account that is authorized to
   * collect AWS Config data from this account. Changing it replaces the
   * authorization.
   */
  authorizedAccountId: string;
  /**
   * The region of the aggregator account that is authorized to collect AWS
   * Config data from this account. Changing it replaces the authorization.
   */
  authorizedAwsRegion: string;
  /**
   * Tags to apply to the authorization. Merged with internal Alchemy tags.
   */
  tags?: Record<string, string>;
}

export interface AggregationAuthorization extends Resource<
  "AWS.Config.AggregationAuthorization",
  AggregationAuthorizationProps,
  {
    /** ARN of the aggregation authorization. */
    aggregationAuthorizationArn: string;
    /** The aggregator account authorized to collect data. */
    authorizedAccountId: string;
    /** The aggregator region authorized to collect data. */
    authorizedAwsRegion: string;
  },
  never,
  Providers
> {}

/**
 * An AWS Config aggregation authorization that grants an aggregator account
 * in a specific region permission to collect AWS Config configuration and
 * compliance data from this account.
 *
 * The authorization's identity is the `(account, region)` pair — changing
 * either replaces it.
 * ### Authorizing an Aggregator
 * **Example:** Authorize an aggregator account
 * ```typescript
 * import * as Config from "alchemy/AWS/Config";
 *
 * const authorization = yield* Config.AggregationAuthorization(
 *   "OrgAggregator",
 *   {
 *     authorizedAccountId: "123456789012",
 *     authorizedAwsRegion: "us-east-1",
 *   },
 * );
 * ```
 *
 * @resource
 */
export const AggregationAuthorization = Resource<AggregationAuthorization>(
  "AWS.Config.AggregationAuthorization",
);

export const AggregationAuthorizationProvider = () =>
  Provider.effect(
    AggregationAuthorization,
    Effect.gen(function* () {
      // There is no Get API — enumerate and match on the (account, region)
      // identity pair.
      const observeAuthorization = Effect.fn(function* (
        accountId: string,
        region: string,
      ) {
        return yield* config.describeAggregationAuthorizations.items({}).pipe(
          Stream.filter(
            (auth) =>
              auth.AuthorizedAccountId === accountId &&
              auth.AuthorizedAwsRegion === region,
          ),
          Stream.runHead,
          Effect.map((head) => (head._tag === "Some" ? head.value : undefined)),
        );
      });

      const observedTags = (arn: string) =>
        config.listTagsForResource({ ResourceArn: arn }).pipe(
          Effect.map((r) =>
            Object.fromEntries(
              (r.Tags ?? []).flatMap((t) =>
                t.Key !== undefined ? [[t.Key, t.Value ?? ""]] : [],
              ),
            ),
          ),
          Effect.catchTag("ResourceNotFoundException", () =>
            Effect.succeed({} as Record<string, string>),
          ),
        );

      const toAttrs = (auth: config.AggregationAuthorization) => ({
        aggregationAuthorizationArn: auth.AggregationAuthorizationArn!,
        authorizedAccountId: auth.AuthorizedAccountId!,
        authorizedAwsRegion: auth.AuthorizedAwsRegion!,
      });

      return AggregationAuthorization.Provider.of({
        stables: [
          "aggregationAuthorizationArn",
          "authorizedAccountId",
          "authorizedAwsRegion",
        ],
        list: () =>
          config.describeAggregationAuthorizations.items({}).pipe(
            Stream.runCollect,
            Effect.map((auths) =>
              Array.from(auths).flatMap((auth) =>
                auth.AggregationAuthorizationArn &&
                auth.AuthorizedAccountId &&
                auth.AuthorizedAwsRegion
                  ? [toAttrs(auth)]
                  : [],
              ),
            ),
          ),
        read: Effect.fn(function* ({ id, olds, output }) {
          const accountId =
            output?.authorizedAccountId ?? olds?.authorizedAccountId;
          const region =
            output?.authorizedAwsRegion ?? olds?.authorizedAwsRegion;
          if (accountId === undefined || region === undefined) {
            return undefined;
          }
          const auth = yield* observeAuthorization(accountId, region);
          if (auth?.AggregationAuthorizationArn === undefined) {
            return undefined;
          }
          const attrs = toAttrs(auth);
          const tags = yield* observedTags(auth.AggregationAuthorizationArn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),
        // The (account, region) pair IS the resource identity — any change
        // replaces it. Tags remain updatable in place.
        diff: Effect.fn(function* ({ news, olds }) {
          if (!isResolved(news)) return undefined;
          if (
            olds.authorizedAccountId !== news.authorizedAccountId ||
            olds.authorizedAwsRegion !== news.authorizedAwsRegion
          ) {
            return { action: "replace" } as const;
          }
        }),
        reconcile: Effect.fn(function* ({ id, news, session }) {
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };

          // 1. OBSERVE — cloud state is authoritative.
          let live = yield* observeAuthorization(
            news.authorizedAccountId,
            news.authorizedAwsRegion,
          );

          // 2. ENSURE — PutAggregationAuthorization is idempotent: it
          //    creates when missing and is a no-op when present (create-time
          //    tags on an existing authorization are ignored, so tags are
          //    synced separately below).
          if (live === undefined) {
            live = yield* config
              .putAggregationAuthorization({
                AuthorizedAccountId: news.authorizedAccountId,
                AuthorizedAwsRegion: news.authorizedAwsRegion,
                Tags: createTagsList(desiredTags),
              })
              .pipe(Effect.map((r) => r.AggregationAuthorization));
          }

          const arn = live?.AggregationAuthorizationArn;
          if (arn === undefined) {
            // Extremely unlikely (Put returns the authorization) — fall back
            // to a fresh observation so the attrs are never fabricated.
            live = yield* observeAuthorization(
              news.authorizedAccountId,
              news.authorizedAwsRegion,
            );
          }

          // 3. SYNC TAGS — diff against OBSERVED cloud tags so adoption
          //    converges.
          const finalArn = live?.AggregationAuthorizationArn;
          if (finalArn !== undefined) {
            const currentTags = yield* observedTags(finalArn);
            const { upsert, removed } = diffTags(currentTags, desiredTags);
            if (upsert.length > 0) {
              yield* config.tagResource({
                ResourceArn: finalArn,
                Tags: upsert,
              });
            }
            if (removed.length > 0) {
              yield* config.untagResource({
                ResourceArn: finalArn,
                TagKeys: removed,
              });
            }
          }

          yield* session.note(
            `${news.authorizedAccountId}/${news.authorizedAwsRegion}`,
          );
          return {
            aggregationAuthorizationArn: finalArn!,
            authorizedAccountId: news.authorizedAccountId,
            authorizedAwsRegion: news.authorizedAwsRegion,
          };
        }),
        // DeleteAggregationAuthorization succeeds whether or not the
        // authorization still exists — idempotent by design.
        delete: Effect.fn(function* ({ output }) {
          yield* config.deleteAggregationAuthorization({
            AuthorizedAccountId: output.authorizedAccountId,
            AuthorizedAwsRegion: output.authorizedAwsRegion,
          });
        }),
      });
    }),
  );

import * as ec2 from "@distilled.cloud/aws/ec2";
import * as Data from "effect/Data";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import * as Stream from "effect/Stream";
import { isResolved } from "../../Diff.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, createTagsList, diffTags } from "../../Tags.ts";
import type { AccountID } from "../Environment.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";
import type { RegionID } from "../Region.ts";

export type FlowLogId<ID extends string = string> = `fl-${ID}`;

export type FlowLogArn<ID extends FlowLogId = FlowLogId> =
  `arn:aws:ec2:${RegionID}:${AccountID}:vpc-flow-log/${ID}`;

/**
 * Raised when `createFlowLogs`/`deleteFlowLogs` report an item in the
 * `Unsuccessful` array (these APIs never throw for per-resource failures).
 */
export class FlowLogOperationFailed extends Data.TaggedError(
  "FlowLogOperationFailed",
)<{
  readonly code: string;
  readonly message: string;
}> {}

export interface FlowLogProps {
  /**
   * The type of resource to monitor.
   */
  resourceType: "VPC" | "Subnet" | "NetworkInterface";

  /**
   * The ID of the VPC, subnet, or network interface to capture flow logs for.
   * Immutable — changing it replaces the flow log.
   */
  resourceId: string;

  /**
   * The type of traffic to capture.
   * @default "ALL"
   */
  trafficType?: "ACCEPT" | "REJECT" | "ALL";

  /**
   * Where to deliver the flow logs.
   * @default "cloud-watch-logs"
   */
  logDestinationType?: "cloud-watch-logs" | "s3" | "kinesis-data-firehose";

  /**
   * The name of the CloudWatch Logs log group. Required (and only valid) when
   * `logDestinationType` is `cloud-watch-logs`.
   */
  logGroupName?: string;

  /**
   * The ARN of the IAM role that permits EC2 to publish flow logs to the
   * CloudWatch Logs group. Required when `logDestinationType` is
   * `cloud-watch-logs`.
   */
  deliverLogsPermissionArn?: string;

  /**
   * The ARN of the destination for the flow logs when `logDestinationType` is
   * `s3` (a bucket ARN, optionally with a key prefix) or
   * `kinesis-data-firehose` (a delivery stream ARN).
   */
  logDestination?: string;

  /**
   * The maximum interval, in seconds, during which a flow of packets is
   * captured and aggregated into a flow log record. Either `60` or `600`.
   * @default 600
   */
  maxAggregationInterval?: 60 | 600;

  /**
   * A custom format string for the flow log records. If omitted, the default
   * format is used.
   */
  logFormat?: string;

  /**
   * Tags to assign to the flow log.
   */
  tags?: Record<string, string>;
}

export interface FlowLog extends Resource<
  "AWS.EC2.FlowLog",
  FlowLogProps,
  {
    /**
     * The ID of the flow log (prefixed `fl-`).
     */
    flowLogId: FlowLogId;

    /**
     * The Amazon Resource Name (ARN) of the flow log.
     */
    flowLogArn: FlowLogArn;

    /**
     * The ID of the monitored resource.
     */
    resourceId: string;

    /**
     * The type of traffic captured.
     */
    trafficType: "ACCEPT" | "REJECT" | "ALL";

    /**
     * Where the flow logs are delivered.
     */
    logDestinationType: "cloud-watch-logs" | "s3" | "kinesis-data-firehose";
  },
  never,
  Providers
> {}

/**
 * A flow log captures information about the IP traffic going to and from a VPC,
 * subnet, or network interface, and publishes it to CloudWatch Logs, S3, or a
 * Kinesis Data Firehose delivery stream. Use it for network monitoring, traffic
 * analysis, and troubleshooting security-group / NACL rules.
 *
 * A flow log is immutable: every property except `tags` is fixed at creation,
 * so changing the monitored resource, destination, or traffic type replaces the
 * flow log. For CloudWatch Logs delivery you must supply a `logGroupName` and a
 * `deliverLogsPermissionArn` — an IAM role that EC2's `vpc-flow-logs` service
 * principal can assume to write to the group.
 *
 * ### Creating a Flow Log
 * **Example:** VPC Flow Log to CloudWatch Logs
 * ```typescript
 * const logGroup = yield* AWS.Logs.LogGroup("FlowLogs", {});
 *
 * const role = yield* AWS.IAM.Role("FlowLogRole", {
 *   assumeRolePolicyDocument: {
 *     Version: "2012-10-17",
 *     Statement: [{
 *       Effect: "Allow",
 *       Principal: { Service: "vpc-flow-logs.amazonaws.com" },
 *       Action: "sts:AssumeRole",
 *     }],
 *   },
 *   inlinePolicies: {
 *     deliver: {
 *       Version: "2012-10-17",
 *       Statement: [{
 *         Effect: "Allow",
 *         Action: [
 *           "logs:CreateLogStream",
 *           "logs:PutLogEvents",
 *           "logs:DescribeLogStreams",
 *         ],
 *         Resource: "*",
 *       }],
 *     },
 *   },
 * });
 *
 * const flowLog = yield* AWS.EC2.FlowLog("VpcFlowLog", {
 *   resourceType: "VPC",
 *   resourceId: myVpc.vpcId,
 *   logGroupName: logGroup.logGroupName,
 *   deliverLogsPermissionArn: role.roleArn,
 * });
 * ```
 * Captures all traffic for the VPC and delivers it to the CloudWatch Logs
 * group via the delivery role.
 *
 * **Example:** S3 Flow Log for Rejected Traffic
 * ```typescript
 * const flowLog = yield* AWS.EC2.FlowLog("RejectedTraffic", {
 *   resourceType: "Subnet",
 *   resourceId: mySubnet.subnetId,
 *   trafficType: "REJECT",
 *   logDestinationType: "s3",
 *   logDestination: bucket.bucketArn,
 * });
 * ```
 * Delivers only rejected-traffic records for a subnet directly to an S3 bucket
 * (no IAM role required for S3 delivery).
 *
 * @resource
 */
export const FlowLog = Resource<FlowLog>("AWS.EC2.FlowLog");

export const FlowLogProvider = () =>
  Provider.effect(
    FlowLog,
    Effect.gen(function* () {
      const createTags = Effect.fn(function* (
        id: string,
        tags?: Record<string, string>,
      ) {
        return {
          Name: id,
          ...(yield* createInternalTags(id)),
          ...tags,
        };
      });

      const describeFlowLog = (flowLogId: string) =>
        ec2.describeFlowLogs({ FlowLogIds: [flowLogId] }).pipe(
          Effect.map((r) => r.FlowLogs?.[0]),
          Effect.catchTag("InvalidFlowLogId.NotFound", () =>
            Effect.succeed(undefined),
          ),
        );

      const toAttrs = (fl: ec2.FlowLog) =>
        AWSEnvironment.current.pipe(
          Effect.map((env) => ({
            flowLogId: fl.FlowLogId as FlowLogId,
            flowLogArn:
              `arn:aws:ec2:${env.region}:${env.accountId}:vpc-flow-log/${fl.FlowLogId}` as FlowLogArn,
            resourceId: fl.ResourceId!,
            trafficType: (fl.TrafficType ?? "ALL") as
              | "ACCEPT"
              | "REJECT"
              | "ALL",
            logDestinationType: (fl.LogDestinationType ??
              "cloud-watch-logs") as
              | "cloud-watch-logs"
              | "s3"
              | "kinesis-data-firehose",
          })),
        );

      return {
        stables: ["flowLogId", "flowLogArn"],

        list: () =>
          Effect.gen(function* () {
            const env = yield* AWSEnvironment.current;
            const items = yield* ec2.describeFlowLogs.pages({}).pipe(
              Stream.runCollect,
              Effect.map((chunk) =>
                Array.from(chunk).flatMap((page) =>
                  (page.FlowLogs ?? [])
                    .filter(
                      (fl): fl is ec2.FlowLog & { FlowLogId: string } =>
                        fl.FlowLogId != null,
                    )
                    .map((fl) => ({
                      flowLogId: fl.FlowLogId as FlowLogId,
                      flowLogArn:
                        `arn:aws:ec2:${env.region}:${env.accountId}:vpc-flow-log/${fl.FlowLogId}` as FlowLogArn,
                      resourceId: fl.ResourceId!,
                      trafficType: (fl.TrafficType ?? "ALL") as
                        | "ACCEPT"
                        | "REJECT"
                        | "ALL",
                      logDestinationType: (fl.LogDestinationType ??
                        "cloud-watch-logs") as
                        | "cloud-watch-logs"
                        | "s3"
                        | "kinesis-data-firehose",
                    })),
                ),
              ),
            );
            return items satisfies FlowLog["Attributes"][];
          }),

        read: Effect.fn(function* ({ output }) {
          if (!output) return undefined;
          const fl = yield* describeFlowLog(output.flowLogId);
          if (!fl) return undefined;
          return yield* toAttrs(fl);
        }),

        diff: Effect.fn(function* ({ news, olds }) {
          if (!isResolved(news)) return;
          // Flow logs are immutable except for tags — any structural change
          // replaces the resource.
          if (
            news.resourceType !== olds.resourceType ||
            news.resourceId !== olds.resourceId ||
            (news.trafficType ?? "ALL") !== (olds.trafficType ?? "ALL") ||
            (news.logDestinationType ?? "cloud-watch-logs") !==
              (olds.logDestinationType ?? "cloud-watch-logs") ||
            news.logGroupName !== olds.logGroupName ||
            news.logDestination !== olds.logDestination ||
            news.deliverLogsPermissionArn !== olds.deliverLogsPermissionArn ||
            (news.maxAggregationInterval ?? 600) !==
              (olds.maxAggregationInterval ?? 600) ||
            news.logFormat !== olds.logFormat
          ) {
            return { action: "replace" };
          }
          // Only tags are mutable in place.
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const desiredTags = yield* createTags(id, news.tags);

          // Observe — find the flow log via the cached id, else create.
          let fl: ec2.FlowLog | undefined;
          if (output?.flowLogId) {
            fl = yield* describeFlowLog(output.flowLogId);
          }

          // Ensure — create if missing. createFlowLogs reports per-resource
          // failures in the Unsuccessful array rather than throwing.
          if (fl === undefined) {
            yield* session.note("Creating flow log...");
            // A freshly-created delivery role may not yet be assumable by the
            // flow-logs service (IAM eventual consistency) — createFlowLogs
            // reports that in Unsuccessful. Retry that (but not a genuine
            // "already exists") on a bounded schedule.
            const result = yield* ec2
              .createFlowLogs({
                ResourceType: news.resourceType,
                ResourceIds: [news.resourceId],
                TrafficType: news.trafficType ?? "ALL",
                LogDestinationType:
                  news.logDestinationType ?? "cloud-watch-logs",
                LogGroupName: news.logGroupName,
                DeliverLogsPermissionArn: news.deliverLogsPermissionArn,
                LogDestination: news.logDestination,
                MaxAggregationInterval: news.maxAggregationInterval,
                LogFormat: news.logFormat,
                TagSpecifications: [
                  {
                    ResourceType: "vpc-flow-log",
                    Tags: createTagsList(desiredTags),
                  },
                ],
              })
              .pipe(
                Effect.flatMap((r) => {
                  const failure = r.Unsuccessful?.[0];
                  return failure
                    ? Effect.fail(
                        new FlowLogOperationFailed({
                          code: failure.Error?.Code ?? "Unknown",
                          message:
                            failure.Error?.Message ?? "createFlowLogs failed",
                        }),
                      )
                    : Effect.succeed(r);
                }),
                Effect.retry({
                  while: (e) =>
                    e._tag === "FlowLogOperationFailed" &&
                    e.code !== "FlowLogAlreadyExists",
                  schedule: Schedule.max([
                    Schedule.fixed(3000),
                    Schedule.recurs(15),
                  ]),
                }),
              );
            const flowLogId = result.FlowLogIds![0]!;
            yield* session.note(`Flow log created: ${flowLogId}`);
            fl = yield* describeFlowLog(flowLogId);
            if (!fl) {
              // Freshly-created flow log not yet visible — synthesize attrs.
              return yield* toAttrs({
                FlowLogId: flowLogId,
                ResourceId: news.resourceId,
                TrafficType: news.trafficType ?? "ALL",
                LogDestinationType:
                  news.logDestinationType ?? "cloud-watch-logs",
              } as ec2.FlowLog);
            }
          }

          const flowLogId = fl.FlowLogId!;

          // Sync tags — observed cloud tags vs desired.
          const currentTags =
            (yield* ec2
              .describeTags({
                Filters: [
                  { Name: "resource-id", Values: [flowLogId] },
                  { Name: "resource-type", Values: ["vpc-flow-log"] },
                ],
              })
              .pipe(
                Effect.map(
                  (r) =>
                    Object.fromEntries(
                      r.Tags?.map((t) => [t.Key!, t.Value!]) ?? [],
                    ) as Record<string, string>,
                ),
              )) ?? {};
          const { removed, upsert } = diffTags(currentTags, desiredTags);
          if (removed.length > 0) {
            yield* ec2.deleteTags({
              Resources: [flowLogId],
              Tags: removed.map((key) => ({ Key: key })),
            });
          }
          if (upsert.length > 0) {
            yield* ec2.createTags({ Resources: [flowLogId], Tags: upsert });
          }

          const final = yield* describeFlowLog(flowLogId);
          return yield* toAttrs(final ?? fl);
        }),

        delete: Effect.fn(function* ({ output, session }) {
          const flowLogId = output.flowLogId;
          yield* session.note(`Deleting flow log: ${flowLogId}`);
          // deleteFlowLogs is idempotent — a missing flow log is reported in
          // Unsuccessful, which we ignore.
          yield* ec2.deleteFlowLogs({ FlowLogIds: [flowLogId] });
        }),
      };
    }),
  );

import * as ec2 from "@distilled.cloud/aws/ec2";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import {
  createInternalTags,
  createTagsList,
  diffTags,
  hasTags,
} from "../../Tags.ts";
import type { Providers } from "../Providers.ts";

export type KeyPairId<ID extends string = string> = `key-${ID}`;

/** Key algorithm for a generated EC2 key pair. */
export type KeyPairType = "rsa" | "ed25519";

/** Private-key file format for a generated EC2 key pair. */
export type KeyPairFormat = "pem" | "ppk";

export interface KeyPairProps {
  /**
   * Name of the key pair. If omitted, a unique name is generated from the
   * stack, stage, and logical id. Changing it replaces the key pair.
   */
  keyName?: string;
  /**
   * Algorithm used when Alchemy generates the key pair. Ignored when
   * {@link publicKeyMaterial} is supplied (an imported key keeps its own type).
   * Changing it replaces the key pair.
   * @default "rsa"
   */
  keyType?: KeyPairType;
  /**
   * Format of the returned private key material. Only meaningful when Alchemy
   * generates the key pair. Changing it replaces the key pair.
   * @default "pem"
   */
  keyFormat?: KeyPairFormat;
  /**
   * Public key material (PEM or OpenSSH) to import instead of generating a new
   * key pair. When set, AWS stores only the public key — no `privateKey` is
   * returned. Changing it replaces the key pair.
   */
  publicKeyMaterial?: string;
  /**
   * Tags to assign to the key pair. Merged with the alchemy auto-tags.
   */
  tags?: Record<string, string>;
}

export interface KeyPair extends Resource<
  "AWS.EC2.KeyPair",
  KeyPairProps,
  {
    /** The ID of the key pair (e.g. `key-0123456789abcdef0`). */
    keyPairId: KeyPairId;
    /** The name of the key pair. */
    keyName: string;
    /** SHA-1/MD5 fingerprint of the key pair. */
    keyFingerprint: string;
    /** The algorithm of the key pair. */
    keyType: KeyPairType;
    /**
     * The unencrypted PEM/PPK private key material. Only present when Alchemy
     * generated the key pair (not when {@link KeyPairProps.publicKeyMaterial}
     * was imported). AWS returns this exactly once, at create time; it is then
     * persisted as a secret in alchemy state.
     */
    privateKey?: Redacted.Redacted<string>;
  },
  never,
  Providers
> {}

/**
 * An EC2 key pair used to grant SSH access to instances launched with its
 * `keyName`.
 *
 * By default Alchemy asks EC2 to generate the key pair and captures the
 * private key (returned only once, at create time) as a secret in state. Pass
 * {@link KeyPairProps.publicKeyMaterial} to import your own public key instead,
 * in which case no private key is stored.
 *
 * ### Creating a Key Pair
 * **Example:** Generated key pair
 * ```typescript
 * const keyPair = yield* AWS.EC2.KeyPair("DeployKey", {
 *   keyType: "ed25519",
 * });
 * // keyPair.keyName       -> pass to AWS.EC2.Instance({ keyName })
 * // keyPair.privateKey    -> Redacted<string> (the PEM private key)
 * ```
 *
 * **Example:** Imported public key
 * ```typescript
 * const keyPair = yield* AWS.EC2.KeyPair("ImportedKey", {
 *   publicKeyMaterial: "ssh-ed25519 AAAAC3Nz... user@host",
 * });
 * ```
 *
 * @resource
 */
export const KeyPair = Resource<KeyPair>("AWS.EC2.KeyPair");

const toKeyName = (id: string, props: { keyName?: string } = {}) =>
  props.keyName
    ? Effect.succeed(props.keyName)
    : createPhysicalName({ id, maxLength: 255 });

const asRedacted = (
  material: string | Redacted.Redacted<string> | undefined,
): Redacted.Redacted<string> | undefined =>
  material === undefined
    ? undefined
    : Redacted.isRedacted(material)
      ? material
      : Redacted.make(material);

export const KeyPairProvider = () =>
  Provider.effect(
    KeyPair,
    Effect.gen(function* () {
      const describeByName = (keyName: string) =>
        ec2.describeKeyPairs({ KeyNames: [keyName] }).pipe(
          Effect.catchTag("InvalidKeyPair.NotFound", () =>
            Effect.succeed({ KeyPairs: [] }),
          ),
          Effect.map((r) => r.KeyPairs?.[0]),
        );

      return {
        stables: ["keyPairId", "keyName", "keyType"],

        // Generated key pairs are immutable except for tags. A changed name /
        // type / format / imported material means a different key pair.
        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return;
          const oldName = yield* toKeyName(id, olds ?? {});
          const newName = yield* toKeyName(id, news);
          if (
            oldName !== newName ||
            (olds?.keyType ?? "rsa") !== (news.keyType ?? "rsa") ||
            (olds?.keyFormat ?? "pem") !== (news.keyFormat ?? "pem") ||
            olds?.publicKeyMaterial !== news.publicKeyMaterial
          ) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const keyName = output?.keyName ?? (yield* toKeyName(id, olds ?? {}));
          const info = yield* describeByName(keyName);
          if (!info?.KeyPairId) return undefined;
          const tags = yield* createInternalTags(id);
          const observedTags: Record<string, string | undefined> =
            Object.fromEntries(
              (info.Tags ?? []).map((t) => [t.Key ?? "", t.Value]),
            );
          if (!hasTags(tags, observedTags)) {
            // Exists but unbranded — let the engine gate adoption behind --adopt.
            return Unowned({
              keyPairId: info.KeyPairId as KeyPairId,
              keyName: info.KeyName ?? keyName,
              keyFingerprint: info.KeyFingerprint ?? "",
              keyType: (info.KeyType ?? "rsa") as KeyPairType,
              // Private key is only available at create time; keep any cached
              // copy from prior state.
              privateKey: output?.privateKey,
            });
          }
          return {
            keyPairId: info.KeyPairId as KeyPairId,
            keyName: info.KeyName ?? keyName,
            keyFingerprint: info.KeyFingerprint ?? output?.keyFingerprint ?? "",
            keyType: (info.KeyType ?? output?.keyType ?? "rsa") as KeyPairType,
            privateKey: output?.privateKey,
          };
        }),

        list: () =>
          Effect.gen(function* () {
            const result = yield* ec2.describeKeyPairs({});
            return (result.KeyPairs ?? [])
              .filter(
                (
                  kp,
                ): kp is ec2.KeyPairInfo & {
                  KeyPairId: string;
                  KeyName: string;
                } => kp.KeyPairId != null && kp.KeyName != null,
              )
              .filter((kp) =>
                (kp.Tags ?? []).some((t) => t.Key === "alchemy::stack"),
              )
              .map((kp) => ({
                keyPairId: kp.KeyPairId as KeyPairId,
                keyName: kp.KeyName,
                keyFingerprint: kp.KeyFingerprint ?? "",
                keyType: (kp.KeyType ?? "rsa") as KeyPairType,
                privateKey: undefined,
              }));
          }),

        reconcile: Effect.fn(function* ({ id, news = {}, output, session }) {
          const keyName = output?.keyName ?? (yield* toKeyName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };

          // Observe — is the key pair already present?
          let info = yield* describeByName(keyName);
          let privateKey = output?.privateKey;

          // Ensure — import or generate when missing.
          if (!info?.KeyPairId) {
            if (news.publicKeyMaterial !== undefined) {
              const imported = yield* ec2
                .importKeyPair({
                  KeyName: keyName,
                  PublicKeyMaterial: new TextEncoder().encode(
                    news.publicKeyMaterial,
                  ),
                  TagSpecifications: [
                    {
                      ResourceType: "key-pair",
                      Tags: createTagsList(desiredTags),
                    },
                  ],
                })
                .pipe(
                  Effect.catchTag("InvalidKeyPair.Duplicate", () =>
                    Effect.succeed(undefined),
                  ),
                );
              if (imported?.KeyPairId) {
                info = {
                  KeyPairId: imported.KeyPairId,
                  KeyName: imported.KeyName,
                  KeyFingerprint: imported.KeyFingerprint,
                  KeyType: "rsa",
                };
              } else {
                info = yield* describeByName(keyName);
              }
            } else {
              const created = yield* ec2
                .createKeyPair({
                  KeyName: keyName,
                  KeyType: news.keyType ?? "rsa",
                  KeyFormat: news.keyFormat ?? "pem",
                  TagSpecifications: [
                    {
                      ResourceType: "key-pair",
                      Tags: createTagsList(desiredTags),
                    },
                  ],
                })
                .pipe(
                  Effect.catchTag("InvalidKeyPair.Duplicate", () =>
                    Effect.succeed(undefined),
                  ),
                );
              if (created?.KeyPairId) {
                privateKey = asRedacted(created.KeyMaterial) ?? privateKey;
                info = {
                  KeyPairId: created.KeyPairId,
                  KeyName: created.KeyName,
                  KeyFingerprint: created.KeyFingerprint,
                  KeyType: (news.keyType ?? "rsa") as KeyPairType,
                };
              } else {
                info = yield* describeByName(keyName);
              }
            }
          }

          if (!info?.KeyPairId) {
            return yield* Effect.die(
              new Error(`Failed to resolve EC2 key pair '${keyName}'`),
            );
          }
          const keyPairId = info.KeyPairId as KeyPairId;

          // Sync tags — observed cloud tags vs desired.
          const observedTags = Object.fromEntries(
            (info.Tags ?? []).map((t) => [t.Key!, t.Value!]),
          ) as Record<string, string>;
          const { removed, upsert } = diffTags(observedTags, desiredTags);
          if (removed.length > 0) {
            yield* ec2.deleteTags({
              Resources: [keyPairId],
              Tags: removed.map((key) => ({ Key: key })),
            });
          }
          if (upsert.length > 0) {
            yield* ec2.createTags({ Resources: [keyPairId], Tags: upsert });
          }

          yield* session.note(`Key pair ${keyName} (${keyPairId})`);
          return {
            keyPairId,
            keyName: info.KeyName ?? keyName,
            keyFingerprint: info.KeyFingerprint ?? "",
            keyType: (info.KeyType ?? news.keyType ?? "rsa") as KeyPairType,
            privateKey,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // `deleteKeyPair` is idempotent — deleting a missing key pair
          // succeeds, so there is no NotFound error to catch.
          yield* ec2.deleteKeyPair({ KeyPairId: output.keyPairId });
        }),
      };
    }),
  );

