        stables: ["workflowName", "workflowArn"],

        read: Effect.fn(function* ({ id, olds, output }) {
          const name =
            output?.workflowName ?? (yield* createName(id, olds ?? {}));
          const workflow = yield* getByName(name);
          if (workflow === undefined) return undefined;
          const attrs = {
            workflowName: workflow.workflowName,
            workflowArn: workflow.workflowArn,
          };
          // getMatchingWorkflow does not return tags — read them via
          // listTagsForResource for the ownership check.
          const tags = yield* readEntityResolutionTags(workflow.workflowArn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds);
          const newName = yield* createName(id, news);
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const name = output?.workflowName ?? (yield* createName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };

          // 1. Observe — names are unique, so the name IS the identity.
          let workflow = yield* getByName(name);

          // 2. Ensure — create when missing. A freshly-created IAM role is
          //    transiently rejected while IAM propagates, so retry that
          //    typed AccessDeniedException on a bounded schedule; tolerate
          //    the concurrent-create race, then re-observe: the create
          //    response is a structural subset of the Get shape (it omits
          //    createdAt/updatedAt).
          if (workflow === undefined) {
            yield* entityresolution
              .createMatchingWorkflow({
                workflowName: name,
                description: news.description,
                inputSourceConfig: news.inputSourceConfig,
                outputSourceConfig: news.outputSourceConfig,
                resolutionTechniques: news.resolutionTechniques,
                incrementalRunConfig: news.incrementalRunConfig,
                roleArn: news.roleArn,
                tags: desiredTags,
              })
              .pipe(
                retryRolePropagation,
                Effect.catchTag("ConflictException", () => Effect.void),
              );
            workflow = yield* entityresolution.getMatchingWorkflow({
              workflowName: name,
            });
          }

          // 3. Sync — everything except the name updates in place via a
          //    full-PUT update. Only call the API on an actual delta
          //    between OBSERVED and desired configuration.
          const desired = {
            description: news.description ?? undefined,
            inputSourceConfig: news.inputSourceConfig,
            outputSourceConfig: news.outputSourceConfig,
            resolutionTechniques: news.resolutionTechniques,
            incrementalRunConfig: news.incrementalRunConfig ?? undefined,
            roleArn: news.roleArn,
          };
          const observed = {
            description: workflow.description ?? undefined,
            inputSourceConfig: workflow.inputSourceConfig,
            outputSourceConfig: workflow.outputSourceConfig,
            resolutionTechniques: workflow.resolutionTechniques,
            incrementalRunConfig: workflow.incrementalRunConfig ?? undefined,
            roleArn: workflow.roleArn,
          };
          if (!deepEqual(observed, desired)) {
            // The update response omits workflowArn/createdAt/updatedAt;
            // the ARN is stable, so keep the observed Get shape.
            yield* entityresolution
              .updateMatchingWorkflow({
                workflowName: name,
                description: news.description,
                inputSourceConfig: news.inputSourceConfig,
                outputSourceConfig: news.outputSourceConfig,
                resolutionTechniques: news.resolutionTechniques,
                incrementalRunConfig: news.incrementalRunConfig,
                roleArn: news.roleArn,
              })
              .pipe(retryRolePropagation);
          }

          const workflowArn = workflow.workflowArn;

          // 3b. Sync tags against OBSERVED cloud tags (adoption-safe).
          yield* syncEntityResolutionTags(workflowArn, desiredTags);

          yield* session.note(workflowArn);
          return { workflowName: name, workflowArn };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteMatchingWorkflow succeeds even when the workflow is
          // already gone; a running matching job conflicts — retry briefly.
          yield* entityresolution
            .deleteMatchingWorkflow({ workflowName: output.workflowName })
            .pipe(
              Effect.retry({
                while: (e) => e._tag === "ConflictException",
                schedule: Schedule.max([
                  Schedule.fixed("2 seconds"),
                  Schedule.recurs(10),
                ]),
              }),
            );
        }),

        list: () =>
          entityresolution.listMatchingWorkflows.items({}).pipe(
            Stream.map((summary) => ({
              workflowName: summary.workflowName,
              workflowArn: summary.workflowArn,
            })),
            Stream.runCollect,
            Effect.map((chunk) => Array.from(chunk)),
          ),
      };
    }),
  );

import * as entityresolution from "@distilled.cloud/aws/entityresolution";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { deepEqual, isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, hasAlchemyTags } from "../../Tags.ts";
import type { Providers } from "../Providers.ts";
import {
  readEntityResolutionTags,
  syncEntityResolutionTags,
} from "./internal.ts";

export interface SchemaMappingProps {
  /**
   * Name of the schema mapping. Must be unique per account/region and match
   * `[a-zA-Z_0-9-]*`. If omitted, a unique name is generated from the app,
   * stage, and logical ID. Changing the name replaces the schema mapping.
   */
  schemaName?: string;
  /**
   * A description of the schema mapping.
   */
  description?: string;
  /**
   * The columns of the input records table and how Entity Resolution should
   * interpret them: the attribute `type` (e.g. `UNIQUE_ID`, `EMAIL_ADDRESS`,
   * `NAME`, `PHONE_NUMBER`), an optional `matchKey` used by rule-based
   * matching, and optional `groupName`/`subType`/`hashed` metadata.
   *
   * Mutable in place — but a schema mapping becomes immutable while it is
   * referenced by a matching workflow.
   */
  mappedInputFields: entityresolution.SchemaInputAttribute[];
  /**
   * Tags to apply to the schema mapping. Merged with internal Alchemy tags.
   */
  tags?: Record<string, string>;
}

export interface SchemaMapping extends Resource<
  "AWS.EntityResolution.SchemaMapping",
  SchemaMappingProps,
  {
    /**
     * The name of the schema mapping.
     */
    schemaName: string;
    /**
     * The ARN of the schema mapping.
     */
    schemaArn: string;
  },
  never,
  Providers
> {}

/**
 * An AWS Entity Resolution schema mapping — the schema of an input customer
 * records table. It tells Entity Resolution the attribute type of each column
 * (name, email, phone, unique id, …) and which columns rule-based matching
 * compares via `matchKey`.
 *
 * ### Creating Schema Mappings
 * **Example:** Customer records schema
 * ```typescript
 * import * as AWS from "alchemy/AWS";
 *
 * const schema = yield* AWS.EntityResolution.SchemaMapping("Customers", {
 *   mappedInputFields: [
 *     { fieldName: "id", type: "UNIQUE_ID" },
 *     { fieldName: "email", type: "EMAIL_ADDRESS", matchKey: "email" },
 *     { fieldName: "name", type: "NAME", matchKey: "name" },
 *   ],
 * });
 * ```
 *
 * ### Matching Workflows
 * **Example:** Use the schema in a matching workflow input source
 * ```typescript
 * const workflow = yield* AWS.EntityResolution.MatchingWorkflow("Dedupe", {
 *   inputSourceConfig: [
 *     { inputSourceARN: table.tableArn, schemaName: schema.schemaName },
 *   ],
 *   // ...
 * });
 * ```
 *
 * @resource
 */
export const SchemaMapping = Resource<SchemaMapping>(
  "AWS.EntityResolution.SchemaMapping",
);

export const SchemaMappingProvider = () =>
  Provider.effect(
    SchemaMapping,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: { schemaName?: string | undefined },
      ) {
        return (
          props.schemaName ??
          (yield* createPhysicalName({ id, maxLength: 255 }))
        );
      });

      /** Get a schema mapping by name; typed not-found → undefined. */
      const getByName = Effect.fn(function* (schemaName: string) {
        return yield* entityresolution
          .getSchemaMapping({ schemaName })
          .pipe(
            Effect.catchTag("ResourceNotFoundException", () =>
              Effect.succeed(undefined),
            ),
          );
      });

      return {
        stables: ["schemaName", "schemaArn"],

        read: Effect.fn(function* ({ id, olds, output }) {
          const name =
            output?.schemaName ?? (yield* createName(id, olds ?? {}));
          const mapping = yield* getByName(name);
          if (mapping === undefined) return undefined;
          const attrs = {
            schemaName: mapping.schemaName,
            schemaArn: mapping.schemaArn,
          };
          // getSchemaMapping does not return tags — read them via
          // listTagsForResource for the ownership check.
          const tags = yield* readEntityResolutionTags(mapping.schemaArn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds);
          const newName = yield* createName(id, news);
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const name = output?.schemaName ?? (yield* createName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };

          // 1. Observe — names are unique, so the name IS the identity.
          let mapping = yield* getByName(name);

          // 2. Ensure — create when missing; tolerate the concurrent-create
          //    race, then re-observe: the create response is a structural
          //    subset of the Get shape (it omits createdAt/updatedAt/
          //    hasWorkflows).
          if (mapping === undefined) {
            yield* entityresolution
              .createSchemaMapping({
                schemaName: name,
                description: news.description,
                mappedInputFields: news.mappedInputFields,
                tags: desiredTags,
              })
              .pipe(Effect.catchTag("ConflictException", () => Effect.void));
            mapping = yield* entityresolution.getSchemaMapping({
              schemaName: name,
            });
          }

          // 3. Sync — description and mapped fields update in place (fails
          //    with a typed ConflictException while a workflow references
          //    the schema). Only call the API on an actual delta.
          if (
            !deepEqual(mapping.mappedInputFields, news.mappedInputFields) ||
            (mapping.description || undefined) !==
              (news.description ?? undefined)
          ) {
            // The update response omits createdAt/updatedAt/hasWorkflows;
            // name and ARN are stable, so keep the observed Get shape.
            yield* entityresolution.updateSchemaMapping({
              schemaName: name,
              description: news.description,
              mappedInputFields: news.mappedInputFields,
            });
          }

          // 3b. Sync tags against OBSERVED cloud tags (adoption-safe).
          yield* syncEntityResolutionTags(mapping.schemaArn, desiredTags);

          yield* session.note(mapping.schemaArn);
          return {
            schemaName: mapping.schemaName,
            schemaArn: mapping.schemaArn,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteSchemaMapping succeeds even when the mapping is already
          // gone; it conflicts while a matching workflow still references
          // the schema (the engine deletes dependents first — retry the
          // eventual-consistency window).
          yield* entityresolution
            .deleteSchemaMapping({ schemaName: output.schemaName })
            .pipe(
              Effect.retry({
                while: (e) => e._tag === "ConflictException",
                schedule: Schedule.max([
                  Schedule.fixed("2 seconds"),
                  Schedule.recurs(10),
                ]),
              }),
            );
        }),

        list: () =>
          entityresolution.listSchemaMappings.items({}).pipe(
            Stream.map((summary) => ({
              schemaName: summary.schemaName,
              schemaArn: summary.schemaArn,
            })),
            Stream.runCollect,
            Effect.map((chunk) => Array.from(chunk)),
          ),
      };
    }),
  );

import * as glue from "@distilled.cloud/aws/glue";
import type * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, hasAlchemyTags } from "../../Tags.ts";
import { toWireMinutes } from "../../Util/Duration.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";
import {
  fetchObservedTags,
  jobArn,
  retryWhileRoleNotAssumable,
  syncTags,
} from "./internal.ts";

export interface JobCommand {
  /**
   * The command name: `glueetl` (Spark), `pythonshell` (Python shell), or
   * `gluestreaming` (Spark streaming).
   */
  name: "glueetl" | "pythonshell" | "gluestreaming" | (string & {});
  /** The S3 path to the job script, e.g. `s3://my-bucket/scripts/job.py`. */
  scriptLocation?: string;
  /** For `pythonshell`, the Python version (`3` or `3.9`). */
  pythonVersion?: string;
  /** The Ray runtime version (for Ray jobs). */
  runtime?: string;
}

export interface JobProps {
  /**
   * Name of the job. If omitted, a unique name is generated. Changing the
   * name replaces the job.
   * @default a generated physical name
   */
  jobName?: string;
  /**
   * The IAM role (ARN or name) the job assumes to run.
   */
  role: string;
  /**
   * The job's execution command (script location + runtime).
   */
  command: JobCommand;
  /**
   * A description of the job.
   */
  description?: string;
  /**
   * Default arguments passed to the script (keys are `--`-prefixed), e.g.
   * `{ "--TempDir": "s3://.../tmp/", "--job-language": "python" }`.
   */
  defaultArguments?: Record<string, string>;
  /**
   * Arguments that cannot be overridden at run time.
   */
  nonOverridableArguments?: Record<string, string>;
  /**
   * Glue connection names the job uses.
   */
  connections?: string[];
  /**
   * Max retries before the job run is considered failed.
   */
  maxRetries?: number;
  /**
   * Job timeout, e.g. `"1 hour"` or `Duration.minutes(60)`. Rounded to
   * whole minutes on the wire (the Glue API unit).
   */
  timeout?: Duration.Input;
  /**
   * Max Glue data processing units (DPUs) for `pythonshell` (0.0625 or 1).
   * Mutually exclusive with `numberOfWorkers`/`workerType`.
   */
  maxCapacity?: number;
  /**
   * The Glue version (e.g. `4.0`, `3.0`).
   */
  glueVersion?: string;
  /**
   * The number of workers of `workerType` allocated (Spark jobs).
   */
  numberOfWorkers?: number;
  /**
   * The worker type for Spark jobs: `Standard`, `G.1X`, `G.2X`, `G.025X`,
   * `G.4X`, `G.8X`, `Z.2X`.
   */
  workerType?: string;
  /**
   * Execution class: `STANDARD` or `FLEX`.
   */
  executionClass?: "STANDARD" | "FLEX";
  /**
   * Concurrency configuration.
   */
  executionProperty?: {
    /** Maximum number of concurrent runs allowed. */
    maxConcurrentRuns?: number;
  };
  /**
   * Tags to apply to the job. Merged with internal Alchemy tags.
   */
  tags?: Record<string, string>;
}

export interface Job extends Resource<
  "AWS.Glue.Job",
  JobProps,
  {
    /** The name of the job. */
    jobName: string;
    /** The ARN of the job. */
    jobArn: string;
    /** The IAM role the job assumes to run. */
    role: string;
  },
  {},
  Providers
> {}

/**
 * An AWS Glue job — a Spark (`glueetl`), Python shell (`pythonshell`), or
 * streaming ETL job definition (script in S3 + IAM role + arguments). The
 * definition lifecycle is instant and free; job *runs* are billed and are
 * started via `startJobRun`.
 * ### Creating Jobs
 * **Example:** Python Shell Job
 * ```typescript
 * import * as AWS from "alchemy/AWS";
 *
 * const job = yield* AWS.Glue.Job("Etl", {
 *   role: jobRole.roleArn,
 *   command: {
 *     name: "pythonshell",
 *     pythonVersion: "3.9",
 *     scriptLocation: "s3://my-bucket/scripts/etl.py",
 *   },
 *   maxCapacity: 0.0625,
 *   glueVersion: "3.0",
 *   defaultArguments: { "--job-language": "python" },
 * });
 * ```
 *
 * **Example:** Spark ETL Job
 * ```typescript
 * const job = yield* AWS.Glue.Job("SparkEtl", {
 *   role: jobRole.roleArn,
 *   command: {
 *     name: "glueetl",
 *     scriptLocation: "s3://my-bucket/scripts/spark.py",
 *   },
 *   glueVersion: "4.0",
 *   workerType: "G.1X",
 *   numberOfWorkers: 2,
 *   timeout: "1 hour",
 * });
 * ```
 *
 * ### Running Jobs
 * **Example:** Start a Job Run from a Lambda
 * ```typescript
 * // init
 * const startJobRun = yield* AWS.Glue.StartJobRun(job);
 *
 * // runtime
 * const { JobRunId } = yield* startJobRun({});
 * ```
 *
 * @resource
 */
export const Job = Resource<Job>("AWS.Glue.Job");

export const JobProvider = () =>
  Provider.effect(
    Job,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: { jobName?: string | undefined },
      ) {
        return (
          props.jobName ?? (yield* createPhysicalName({ id, maxLength: 255 }))
        );
      });

      const observe = Effect.fn(function* (name: string) {
        return yield* glue.getJob({ JobName: name }).pipe(
          Effect.map((r) => r.Job),
          Effect.catchTag("EntityNotFoundException", () =>
            Effect.succeed(undefined),
          ),
        );
      });

      const buildCommand = (command: JobCommand) => ({
        Name: command.name,
        ScriptLocation: command.scriptLocation,
        PythonVersion: command.pythonVersion,
        Runtime: command.runtime,
      });

      const buildDefinition = (props: JobProps) => ({
        Role: props.role,
        Command: buildCommand(props.command),
        Description: props.description,
        DefaultArguments: props.defaultArguments,
        NonOverridableArguments: props.nonOverridableArguments,
        Connections:
          props.connections !== undefined
            ? { Connections: props.connections }
            : undefined,
        MaxRetries: props.maxRetries,
        Timeout: toWireMinutes(props.timeout),
        MaxCapacity: props.maxCapacity,
        GlueVersion: props.glueVersion,
        NumberOfWorkers: props.numberOfWorkers,
        WorkerType: props.workerType,
        ExecutionClass: props.executionClass,
        ExecutionProperty: props.executionProperty
          ? { MaxConcurrentRuns: props.executionProperty.maxConcurrentRuns }
          : undefined,
      });

      return Job.Provider.of({
        stables: ["jobName", "jobArn"],

        list: () =>
          Effect.gen(function* () {
            const { accountId, region } = yield* AWSEnvironment.current;
            const pages = yield* glue.getJobs.pages({}).pipe(Stream.runCollect);
            return Array.from(pages)
              .flatMap((page) => page.Jobs ?? [])
              .filter((j) => j.Name !== undefined)
              .map((j) => ({
                jobName: j.Name!,
                jobArn: jobArn(region, accountId, j.Name!),
                role: j.Role ?? "",
              }));
          }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name = output?.jobName ?? (yield* createName(id, olds ?? {}));
          const job = yield* observe(name);
          if (job?.Name === undefined) return undefined;
          const arn = jobArn(region, accountId, job.Name);
          const attrs = {
            jobName: job.Name,
            jobArn: arn,
            role: job.Role ?? "",
          };
          const tags = yield* fetchObservedTags(arn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds);
          const newName = yield* createName(id, news);
          if (oldName !== newName) return { action: "replace" } as const;
          // everything else is UpdateJob-able
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name = output?.jobName ?? (yield* createName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };
          const arn = jobArn(region, accountId, name);

          // 1. OBSERVE
          let job = yield* observe(name);

          // 2. ENSURE / 3. SYNC
          if (job === undefined) {
            yield* retryWhileRoleNotAssumable(
              glue.createJob({
                Name: name,
                ...buildDefinition(news),
                Tags: desiredTags,
              }),
            ).pipe(
              Effect.catchTag("AlreadyExistsException", () => Effect.void),
            );
          } else {
            // UpdateJob replaces the full JobUpdate (Name is not part of it).
            yield* retryWhileRoleNotAssumable(
              glue.updateJob({
                JobName: name,
                JobUpdate: buildDefinition(news),
              }),
            );
          }

          // 3b. SYNC TAGS
          const observedTags = yield* fetchObservedTags(arn);
          yield* syncTags(arn, observedTags, desiredTags);

          job = yield* observe(name);

          yield* session.note(name);
          return {
            jobName: name,
            jobArn: arn,
            role: job?.Role ?? news.role,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // DeleteJob is idempotent — the API returns success (not an error)
          // when the job definition is already gone.
          yield* glue.deleteJob({ JobName: output.jobName });
        }),
      });
    }),
  );

import * as mm from "@distilled.cloud/aws/mailmanager";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import {
  createInternalTags,
  createTagsList,
  hasAlchemyTags,
} from "../../Tags.ts";
import type { Providers } from "../Providers.ts";
import { readMailManagerTags, syncMailManagerTags } from "./internal.ts";

export interface AddonInstanceProps {
  /**
   * ID of the {@link AddonSubscription} this instance is created from.
   * Immutable — changing the subscription replaces the instance.
   */
  addonSubscriptionId: string;
  /**
   * Tags applied to the instance. Alchemy ownership tags are merged in
   * automatically.
   */
  tags?: Record<string, string>;
}

export interface AddonInstance extends Resource<
  "AWS.MailManager.AddonInstance",
  AddonInstanceProps,
  {
    /** Server-assigned ID of the Add On instance. */
    addonInstanceId: string;
    /** ARN of the Add On instance. */
    addonInstanceArn: string;
    /** ID of the subscription the instance was created from. */
    addonSubscriptionId: string;
    /** Name of the Add On product. */
    addonName: string | undefined;
  },
  never,
  Providers
> {}

/**
 * An SES Mail Manager Add On instance — a usable deployment of a subscribed
 * Add On that rule-set conditions and traffic-policy statements reference as
 * an analyzer.
 *
 * Instances are immutable after creation (only tags update in place).
 * ### Creating Add On Instances
 * **Example:** Instance from a Subscription
 * ```typescript
 * import * as MailManager from "alchemy/AWS/MailManager";
 *
 * const subscription = yield* MailManager.AddonSubscription("Spamhaus", {
 *   addonName: "SPAMHAUS_DBL",
 * });
 * const instance = yield* MailManager.AddonInstance("SpamhausInstance", {
 *   addonSubscriptionId: subscription.addonSubscriptionId,
 * });
 * ```
 *
 * ### Referencing from a Traffic Policy
 * **Example:** Analyzer Condition
 * ```typescript
 * const policy = yield* MailManager.TrafficPolicy("Edge", {
 *   defaultAction: "ALLOW",
 *   policyStatements: [
 *     {
 *       Action: "DENY",
 *       Conditions: [
 *         {
 *           BooleanExpression: {
 *             Evaluate: {
 *               Analysis: {
 *                 Analyzer: instance.addonInstanceArn,
 *                 ResultField: "IN_DBL",
 *               },
 *             },
 *             Operator: "IS_TRUE",
 *           },
 *         },
 *       ],
 *     },
 *   ],
 * });
 * ```
 *
 * @resource
 */
export const AddonInstance = Resource<AddonInstance>(
  "AWS.MailManager.AddonInstance",
);

export const AddonInstanceProvider = () =>
  Provider.effect(
    AddonInstance,
    Effect.gen(function* () {
      const getById = (addonInstanceId: string) =>
        mm
          .getAddonInstance({ AddonInstanceId: addonInstanceId })
          .pipe(
            Effect.catchTag("ResourceNotFoundException", () =>
              Effect.succeed(undefined),
            ),
          );

      const listAll = mm.listAddonInstances.pages({}).pipe(
        Stream.runCollect,
        Effect.map((chunk) =>
          Array.from(chunk).flatMap((page) => page.AddonInstances ?? []),
        ),
      );

      // Instances have no user-supplied name — recover identity after a lost
      // state write by searching for our ownership tags.
      const findByAlchemyTags = Effect.fn(function* (id: string) {
        const instances = yield* listAll;
        for (const instance of instances) {
          if (instance.AddonInstanceArn === undefined) continue;
          const tags = yield* readMailManagerTags(instance.AddonInstanceArn);
          if (yield* hasAlchemyTags(id, tags)) return instance;
        }
        return undefined;
      });

      const toAttrs = (instance: mm.AddonInstance) =>
        instance.AddonInstanceId !== undefined &&
        instance.AddonInstanceArn !== undefined &&
        instance.AddonSubscriptionId !== undefined
          ? {
              addonInstanceId: instance.AddonInstanceId,
              addonInstanceArn: instance.AddonInstanceArn,
              addonSubscriptionId: instance.AddonSubscriptionId,
              addonName: instance.AddonName,
            }
          : undefined;

      const observe = Effect.fn(function* (
        id: string,
        output: AddonInstance["Attributes"] | undefined,
      ) {
        if (output?.addonInstanceId !== undefined) {
          const found = yield* getById(output.addonInstanceId);
          if (found !== undefined) {
            return {
              AddonInstanceId: output.addonInstanceId,
              AddonInstanceArn: found.AddonInstanceArn,
              AddonSubscriptionId: found.AddonSubscriptionId,
              AddonName: found.AddonName,
            } satisfies mm.AddonInstance;
          }
        }
        return yield* findByAlchemyTags(id);
      });

      return AddonInstance.Provider.of({
        stables: [
          "addonInstanceId",
          "addonInstanceArn",
          "addonSubscriptionId",
          "addonName",
        ],

        list: () =>
          listAll.pipe(
            Effect.map((instances) =>
              instances.flatMap((i) => {
                const attrs = toAttrs(i);
                return attrs === undefined ? [] : [attrs];
              }),
            ),
          ),

        read: Effect.fn(function* ({ id, output }) {
          const instance = yield* observe(id, output);
          if (instance === undefined) return undefined;
          const attrs = toAttrs(instance);
          if (attrs === undefined) return undefined;
          const tags = yield* readMailManagerTags(attrs.addonInstanceArn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        // The subscription is create-only — changing it replaces the
        // instance.
        diff: Effect.fn(function* ({ news, olds }) {
          if (!isResolved(news)) return undefined;
          if (
            olds !== undefined &&
            olds.addonSubscriptionId !== news.addonSubscriptionId
          ) {
            return { action: "replace" } as const;
          }
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };

          // 1. OBSERVE — by cached id, falling back to an ownership-tag
          //    search.
          let instance = yield* observe(id, output);

          // 2. ENSURE — create if missing; a Conflict race re-observes via
          //    the tag search.
          if (instance === undefined) {
            yield* session.note(
              `creating Add On instance for subscription ${news.addonSubscriptionId}`,
            );
            const created = yield* mm
              .createAddonInstance({
                AddonSubscriptionId: news.addonSubscriptionId,
                Tags: createTagsList(desiredTags),
              })
              .pipe(
                Effect.catchTag("ConflictException", () =>
                  Effect.succeed(undefined),
                ),
              );
            if (created !== undefined) {
              const found = yield* getById(created.AddonInstanceId);
              instance = {
                AddonInstanceId: created.AddonInstanceId,
                AddonInstanceArn: found?.AddonInstanceArn,
                AddonSubscriptionId:
                  found?.AddonSubscriptionId ?? news.addonSubscriptionId,
                AddonName: found?.AddonName,
              };
            } else {
              instance = yield* findByAlchemyTags(id);
            }
          }
          const attrs = instance !== undefined ? toAttrs(instance) : undefined;
          if (attrs === undefined) {
            return yield* Effect.fail(
              new Error(
                `Mail Manager Add On instance for subscription '${news.addonSubscriptionId}' not found after create`,
              ),
            );
          }

          // 3. SYNC — only tags are mutable.
          yield* syncMailManagerTags(attrs.addonInstanceArn, desiredTags);

          yield* session.note(attrs.addonInstanceId);
          return attrs;
        }),

        delete: Effect.fn(function* ({ output }) {
          // DeleteAddonInstance is natively idempotent — deleting a
          // nonexistent instance succeeds (verified live).
          yield* mm
            .deleteAddonInstance({ AddonInstanceId: output.addonInstanceId })
            .pipe(Effect.asVoid);
        }),
      });
    }),
  );

