export interface OriginEndpointProps {
  /**
   * Name of the channel group the endpoint belongs to. Changing it replaces
   * the endpoint.
   */
  channelGroupName: string;
  /**
   * Name of the channel the endpoint packages content from. Changing it
   * replaces the endpoint.
   */
  channelName: string;
  /**
   * Name of the origin endpoint. Must be unique within the channel and match
   * `^[a-zA-Z0-9_-]+$`. If omitted, a unique name is generated. Changing the
   * name replaces the endpoint.
   */
  originEndpointName?: string;
  /**
   * The container format packaged for the endpoint's manifests: `TS`,
   * `CMAF`, or `ISM`. Immutable — changing it replaces the endpoint.
   */
  containerType: mediapackagev2.ContainerType;
  /**
   * Segment settings: duration, name, SCTE-35 ad-marker filtering, and DRM
   * encryption (SPEKE key provider).
   */
  segment?: mediapackagev2.Segment;
  /**
   * Optional description of the origin endpoint (up to 1024 characters).
   */
  description?: string;
  /**
   * The size of the window (1 minute - 14 days, e.g. `"1 hour"` or
   * `Duration.hours(1)`) from which viewers can start over or catch up on
   * previously streamed content. Sent to the API in whole seconds.
   */
  startoverWindow?: Duration.Input;
  /**
   * HLS manifest configurations served by the endpoint.
   */
  hlsManifests?: mediapackagev2.CreateHlsManifestConfiguration[];
  /**
   * Low-latency HLS manifest configurations served by the endpoint.
   */
  lowLatencyHlsManifests?: mediapackagev2.CreateLowLatencyHlsManifestConfiguration[];
  /**
   * DASH manifest configurations served by the endpoint.
   */
  dashManifests?: mediapackagev2.CreateDashManifestConfiguration[];
  /**
   * Microsoft Smooth Streaming (MSS) manifest configurations served by the
   * endpoint. Requires the `ISM` container type.
   */
  mssManifests?: mediapackagev2.CreateMssManifestConfiguration[];
  /**
   * Conditions (stale manifest, missing DRM key, ...) under which the
   * endpoint deliberately serves errors, for testing player behavior.
   */
  forceEndpointErrorConfiguration?: mediapackagev2.ForceEndpointErrorConfiguration;
  /**
   * The separator (`UNDERSCORE` or `HYPHEN`) inserted into manifest and
   * segment URIs.
   */
  uriSeparator?: mediapackagev2.UriSeparator;
  /**
   * IAM resource policy (JSON) attached to the origin endpoint, controlling
   * which principals may retrieve content from it
   * (`mediapackagev2:GetObject` / `mediapackagev2:GetHeadObject`). Omitting
   * it removes any existing policy.
   */
  policy?: string;
  /**
   * CDN authorization for the endpoint policy: the Secrets Manager secrets
   * holding the CDN identifier and the role MediaPackage assumes to read
   * them. Only applied together with {@link OriginEndpointProps.policy}.
   */
  cdnAuthConfiguration?: mediapackagev2.CdnAuthConfiguration;
  /**
   * User-defined tags for the origin endpoint. Merged with internal Alchemy
   * tags.
   */
  tags?: Record<string, string>;
}

interface ManifestRef {
  /** Name of the manifest. */
  manifestName: string;
  /** Playback URL of the manifest on the group's egress domain. */
  url: string;
}

export interface OriginEndpoint extends Resource<
  "AWS.MediaPackageV2.OriginEndpoint",
  OriginEndpointProps,
  {
    /** Name of the channel group the endpoint belongs to. */
    channelGroupName: string;
    /** Name of the channel the endpoint packages content from. */
    channelName: string;
    /** Name of the origin endpoint. */
    originEndpointName: string;
    /** ARN of the origin endpoint. */
    originEndpointArn: string;
    /** Output container type (`TS`, `CMAF`, or `ISM`). */
    containerType: string;
    /** HLS manifests served by the endpoint. */
    hlsManifests: ManifestRef[];
    /** Low-latency HLS manifests served by the endpoint. */
    lowLatencyHlsManifests: ManifestRef[];
    /** DASH manifests served by the endpoint. */
    dashManifests: ManifestRef[];
    /** Microsoft Smooth Streaming manifests served by the endpoint. */
    mssManifests: ManifestRef[];
  },
  never,
  Providers
> {}

/**
 * An AWS Elemental MediaPackage v2 origin endpoint — the output side of a
 * channel. The endpoint packages the channel's ingested content into HLS,
 * low-latency HLS, DASH, and/or MSS manifests and serves them to downstream
 * devices (players or CDNs) on the channel group's egress domain.
 *
 * ### Creating an Origin Endpoint
 * **Example:** HLS Endpoint on a Channel
 * ```typescript
 * import * as MediaPackageV2 from "alchemy/AWS/MediaPackageV2";
 *
 * const group = yield* MediaPackageV2.ChannelGroup("Live");
 * const channel = yield* MediaPackageV2.Channel("Feed", {
 *   channelGroupName: group.channelGroupName,
 * });
 * const endpoint = yield* MediaPackageV2.OriginEndpoint("Playback", {
 *   channelGroupName: group.channelGroupName,
 *   channelName: channel.channelName,
 *   containerType: "TS",
 *   hlsManifests: [{ ManifestName: "index" }],
 * });
 * ```
 *
 * **Example:** CMAF Endpoint with DASH and Low-Latency HLS
 * ```typescript
 * const endpoint = yield* MediaPackageV2.OriginEndpoint("Playback", {
 *   channelGroupName: group.channelGroupName,
 *   channelName: channel.channelName,
 *   containerType: "CMAF",
 *   segment: { SegmentDurationSeconds: 4 },
 *   dashManifests: [{ ManifestName: "dash" }],
 *   lowLatencyHlsManifests: [{ ManifestName: "ll-hls" }],
 * });
 * ```
 *
 * ### Startover Window
 * **Example:** Allow viewers to catch up on the last hour
 * ```typescript
 * const endpoint = yield* MediaPackageV2.OriginEndpoint("Playback", {
 *   channelGroupName: group.channelGroupName,
 *   channelName: channel.channelName,
 *   containerType: "TS",
 *   startoverWindow: "1 hour",
 *   hlsManifests: [{ ManifestName: "index" }],
 * });
 * ```
 *
 * ### Resource Policy
 * **Example:** Restrict playback to a CDN principal
 * ```typescript
 * const endpoint = yield* MediaPackageV2.OriginEndpoint("Playback", {
 *   channelGroupName: group.channelGroupName,
 *   channelName: channel.channelName,
 *   containerType: "TS",
 *   hlsManifests: [{ ManifestName: "index" }],
 *   policy: JSON.stringify({
 *     Version: "2012-10-17",
 *     Statement: [{
 *       Effect: "Allow",
 *       Principal: { AWS: "arn:aws:iam::111122223333:root" },
 *       Action: ["mediapackagev2:GetObject", "mediapackagev2:GetHeadObject"],
 *       Resource: "arn:aws:mediapackagev2:us-east-1:111122223333:channelGroup/live/channel/feed/originEndpoint/playback",
 *     }],
 *   }),
 * });
 * ```
 *
 * ### Playback URLs
 * **Example:** Read the served manifest URLs
 * ```typescript
 * const playbackUrl = endpoint.hlsManifests.map((m) => m.url);
 * ```
 *
 * @resource
 */
export const OriginEndpoint = Resource<OriginEndpoint>(
  "AWS.MediaPackageV2.OriginEndpoint",
);

export const OriginEndpointProvider = () =>
  Provider.effect(
    OriginEndpoint,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: { originEndpointName?: string },
      ) {
        return (
          props.originEndpointName ??
          (yield* createPhysicalName({ id, maxLength: 256 }))
        );
      });

      const manifestRefs = (
        manifests: { ManifestName: string; Url: string }[] | undefined,
      ): ManifestRef[] =>
        (manifests ?? []).map((m) => ({
          manifestName: m.ManifestName,
          url: m.Url,
        }));

      const toAttrs = (endpoint: {
        Arn: string;
        ChannelGroupName: string;
        ChannelName: string;
        OriginEndpointName: string;
        ContainerType: mediapackagev2.ContainerType;
        HlsManifests?: mediapackagev2.GetHlsManifestConfiguration[];
        LowLatencyHlsManifests?: mediapackagev2.GetLowLatencyHlsManifestConfiguration[];
        DashManifests?: mediapackagev2.GetDashManifestConfiguration[];
        MssManifests?: mediapackagev2.GetMssManifestConfiguration[];
      }) => ({
        channelGroupName: endpoint.ChannelGroupName,
        channelName: endpoint.ChannelName,
        originEndpointName: endpoint.OriginEndpointName,
        originEndpointArn: endpoint.Arn,
        containerType: endpoint.ContainerType,
        hlsManifests: manifestRefs(endpoint.HlsManifests),
        lowLatencyHlsManifests: manifestRefs(endpoint.LowLatencyHlsManifests),
        dashManifests: manifestRefs(endpoint.DashManifests),
        mssManifests: manifestRefs(endpoint.MssManifests),
      });

      /** Get an origin endpoint; typed not-found → undefined. */
      const getEndpoint = Effect.fn(function* (
        channelGroupName: string,
        channelName: string,
        originEndpointName: string,
      ) {
        return yield* mediapackagev2
          .getOriginEndpoint({
            ChannelGroupName: channelGroupName,
            ChannelName: channelName,
            OriginEndpointName: originEndpointName,
          })
          .pipe(
            Effect.catchTag("ResourceNotFoundException", () =>
              Effect.succeed(undefined),
            ),
          );
      });

      return {
        stables: [
          "channelGroupName",
          "channelName",
          "originEndpointName",
          "originEndpointArn",
          "containerType",
        ],

        diff: Effect.fn(function* ({ id, olds, news }) {
          if (!isResolved(news)) return undefined;
          // Group, channel, name, and container type are the endpoint's
          // identity.
          if (olds.channelGroupName !== news.channelGroupName) {
            return { action: "replace" } as const;
          }
          if (olds.channelName !== news.channelName) {
            return { action: "replace" } as const;
          }
          const oldName = yield* createName(id, olds);
          const newName = yield* createName(id, news);
          if (oldName !== newName) return { action: "replace" } as const;
          if (olds.containerType !== news.containerType) {
            return { action: "replace" } as const;
          }
        }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const channelGroupName =
            output?.channelGroupName ?? olds?.channelGroupName;
          const channelName = output?.channelName ?? olds?.channelName;
          if (channelGroupName === undefined || channelName === undefined) {
            return undefined;
          }
          const name =
            output?.originEndpointName ?? (yield* createName(id, olds ?? {}));
          const endpoint = yield* getEndpoint(
            channelGroupName,
            channelName,
            name,
          );
          if (endpoint === undefined) return undefined;
          const attrs = toAttrs(endpoint);
          return (yield* hasAlchemyTags(id, toMpTagRecord(endpoint.Tags)))
            ? attrs
            : Unowned(attrs);
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...internalTags, ...news.tags };
          const channelGroupName = news.channelGroupName;
          const channelName = news.channelName;
          // The wire field is whole seconds.
          const startoverWindowSeconds = toWireSeconds(news.startoverWindow);
          const name =
            output?.originEndpointName ?? (yield* createName(id, news));

          // 1. Observe — cloud state is authoritative; output is an id cache.
          let endpoint = yield* getEndpoint(
            channelGroupName,
            channelName,
            name,
          );

          // 2. Ensure — create if missing; a Conflict means a peer created it
          //    concurrently, so fall through to observing the winner.
          if (endpoint === undefined) {
            endpoint = yield* mediapackagev2
              .createOriginEndpoint({
                ChannelGroupName: channelGroupName,
                ChannelName: channelName,
                OriginEndpointName: name,
                ContainerType: news.containerType,
                Segment: news.segment,
                Description: news.description,
                StartoverWindowSeconds: startoverWindowSeconds,
                HlsManifests: news.hlsManifests,
                LowLatencyHlsManifests: news.lowLatencyHlsManifests,
                DashManifests: news.dashManifests,
                MssManifests: news.mssManifests,
                ForceEndpointErrorConfiguration:
                  news.forceEndpointErrorConfiguration,
                UriSeparator: news.uriSeparator,
                Tags: desiredTags,
              })
              .pipe(
                Effect.catchTag("ConflictException", () =>
                  mediapackagev2.getOriginEndpoint({
                    ChannelGroupName: channelGroupName,
                    ChannelName: channelName,
                    OriginEndpointName: name,
                  }),
                ),
              );
          } else {
            // 3. Sync — the update is a full PUT of the mutable aspects, so
            //    apply it only when the observed state has drifted from the
            //    desired subset. Manifest arrays are compared by length and
            //    by the fields the desired config specifies, so server-side
            //    defaults never register as drift.
            const desired = {
              Segment: news.segment,
              Description: news.description ?? "",
              StartoverWindowSeconds: startoverWindowSeconds,
              HlsManifests: news.hlsManifests ?? [],
              LowLatencyHlsManifests: news.lowLatencyHlsManifests ?? [],
              DashManifests: news.dashManifests ?? [],
              MssManifests: news.mssManifests ?? [],
              ForceEndpointErrorConfiguration:
                news.forceEndpointErrorConfiguration,
              UriSeparator: news.uriSeparator,
            };
            const observed = {
              Segment: endpoint.Segment,
              Description: endpoint.Description ?? "",
              StartoverWindowSeconds: endpoint.StartoverWindowSeconds,
              HlsManifests: endpoint.HlsManifests ?? [],
              LowLatencyHlsManifests: endpoint.LowLatencyHlsManifests ?? [],
              DashManifests: endpoint.DashManifests ?? [],
              MssManifests: endpoint.MssManifests ?? [],
              ForceEndpointErrorConfiguration:
                endpoint.ForceEndpointErrorConfiguration,
              UriSeparator: endpoint.UriSeparator,
            };
            if (!matchesDesired(desired, observed)) {
              endpoint = yield* mediapackagev2.updateOriginEndpoint({
                ChannelGroupName: channelGroupName,
                ChannelName: channelName,
                OriginEndpointName: name,
                ContainerType: news.containerType,
                Segment: news.segment,
                Description: news.description,
                StartoverWindowSeconds: startoverWindowSeconds,
                HlsManifests: news.hlsManifests,
                LowLatencyHlsManifests: news.lowLatencyHlsManifests,
                DashManifests: news.dashManifests,
                MssManifests: news.mssManifests,
                ForceEndpointErrorConfiguration:
                  news.forceEndpointErrorConfiguration,
                UriSeparator: news.uriSeparator,
              });
            }
          }

          // 3b. Sync tags — diff against OBSERVED cloud tags.
          yield* syncMpTags(
            endpoint.Arn,
            toMpTagRecord(endpoint.Tags),
            desiredTags,
          );

          // 3c. Sync the resource policy — observe the live policy (absent
          //     policy is the typed not-found) and apply only the delta.
          const observedPolicy = yield* mediapackagev2
            .getOriginEndpointPolicy({
              ChannelGroupName: channelGroupName,
              ChannelName: channelName,
              OriginEndpointName: name,
            })
            .pipe(
              Effect.map((response) => ({
                policy: response.Policy as string | undefined,
                cdnAuth: response.CdnAuthConfiguration,
              })),
              Effect.catchTag("ResourceNotFoundException", () =>
                Effect.succeed({
                  policy: undefined as string | undefined,
                  cdnAuth: undefined as
                    | mediapackagev2.CdnAuthConfiguration
                    | undefined,
                }),
              ),
            );
          if (news.policy !== undefined) {
            const cdnDrift =
              news.cdnAuthConfiguration === undefined
                ? observedPolicy.cdnAuth !== undefined
                : !matchesDesired(
                    news.cdnAuthConfiguration,
                    observedPolicy.cdnAuth,
                  );
            if (
              !policiesEqual(observedPolicy.policy, news.policy) ||
              cdnDrift
            ) {
              yield* mediapackagev2.putOriginEndpointPolicy({
                ChannelGroupName: channelGroupName,
                ChannelName: channelName,
                OriginEndpointName: name,
                Policy: news.policy,
                CdnAuthConfiguration: news.cdnAuthConfiguration,
              });
            }
          } else if (observedPolicy.policy !== undefined) {
            yield* mediapackagev2.deleteOriginEndpointPolicy({
              ChannelGroupName: channelGroupName,
              ChannelName: channelName,
              OriginEndpointName: name,
            });
          }

          yield* session.note(name);
          return toAttrs(endpoint);
        }),

        delete: Effect.fn(function* ({ output }) {
          // MediaPackage v2 deletes are idempotent (deleting a missing
          // endpoint succeeds); a Conflict from a concurrent mutation is
          // transient.
          yield* mediapackagev2
            .deleteOriginEndpoint({
              ChannelGroupName: output.channelGroupName,
              ChannelName: output.channelName,
              OriginEndpointName: output.originEndpointName,
            })
            .pipe(retryWhileMpConflict);
        }),

        // Origin endpoints are keyed by their parent channel, so enumerate
        // groups → channels → endpoints.
        list: () =>
          Effect.gen(function* () {
            const groups = yield* listAllChannelGroups();
            const channels = yield* Effect.forEach(
              groups,
              (group) => listGroupChannels(group.ChannelGroupName),
              { concurrency: 5 },
            ).pipe(Effect.map((nested) => nested.flat()));
            const items = yield* Effect.forEach(
              channels,
              (channel) =>
                listChannelEndpoints(
                  channel.ChannelGroupName,
                  channel.ChannelName,
                ),
              { concurrency: 5 },
            ).pipe(Effect.map((nested) => nested.flat()));
            // Hydrate each item via get so the attributes carry the manifest
            // URLs; an endpoint can vanish between enumeration and hydration.
            const endpoints = yield* Effect.forEach(
              items,
              (item) =>
                getEndpoint(
                  item.ChannelGroupName,
                  item.ChannelName,
                  item.OriginEndpointName,
                ).pipe(
                  Effect.map((endpoint) =>
                    endpoint === undefined ? undefined : toAttrs(endpoint),
                  ),
                ),
              { concurrency: 5 },
            );
            return endpoints.filter(Predicate.isNotUndefined);
          }),
      };
    }),
  );

import * as mediatailor from "@distilled.cloud/aws/mediatailor";
import * as Data from "effect/Data";
import type * as Duration from "effect/Duration";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import {
  createInternalTags,
  diffTags,
  hasAlchemyTags,
  tagRecord,
} from "../../Tags.ts";
import { toWireSeconds } from "../../Util/Duration.ts";
import type { Providers } from "../Providers.ts";

/**
 * CDN routing configuration for ad and content segment delivery.
 */
export interface PlaybackConfigurationCdn {
  /**
   * A non-default content delivery network (CDN) prefix that MediaTailor
   * routes ad segment requests through, e.g. a CloudFront distribution in
   * front of `ads.mediatailor.<region>.amazonaws.com`.
   */
  adSegmentUrlPrefix?: string;
  /**
   * A content delivery network (CDN) prefix that content segment URLs in
   * manifests are rewritten to, so players request content through the CDN.
   */
  contentSegmentUrlPrefix?: string;
}

/**
 * DASH manifest handling configuration.
 */
export interface PlaybackConfigurationDash {
  /**
   * Where the `Location` element is placed in the DASH manifest.
   * @default "EMT_DEFAULT"
   */
  mpdLocation?: string;
  /**
   * Whether the origin server produces single-period or multi-period DASH
   * manifests. One of `SINGLE_PERIOD` or `MULTI_PERIOD`.
   * @default "MULTI_PERIOD"
   */
  originManifestType?: "SINGLE_PERIOD" | "MULTI_PERIOD";
}

/**
 * Controls how MediaTailor suppresses ad insertion near the live edge.
 */
export interface PlaybackConfigurationAvailSuppression {
  /**
   * `BEHIND_LIVE_EDGE` suppresses ads behind the configured point in the
   * stream; `AFTER_LIVE_EDGE` suppresses ads after it.
   * @default "OFF"
   */
  mode?: "OFF" | "BEHIND_LIVE_EDGE" | "AFTER_LIVE_EDGE";
  /**
   * A live-edge offset timestamp (HH:MM:SS) that defines the suppression
   * boundary.
   */
  value?: string;
  /**
   * `PARTIAL_AVAIL` fills partial ad breaks; `FULL_AVAIL_ONLY` only fills
   * complete ad breaks.
   */
  fillPolicy?: "FULL_AVAIL_ONLY" | "PARTIAL_AVAIL";
}

/**
 * Bumpers are short branded videos played before and after ad breaks.
 */
export interface PlaybackConfigurationBumper {
  /** URL of the bumper asset played before each ad break. */
  startUrl?: string;
  /** URL of the bumper asset played after each ad break. */
  endUrl?: string;
}

/**
 * Configuration for pre-roll ad insertion on live streams.
 */
export interface PlaybackConfigurationLivePreRoll {
  /** The ad decision server URL used for live pre-roll ads. */
  adDecisionServerUrl?: string;
  /**
   * Maximum allowed duration for the pre-roll ad avail, e.g. `"30 seconds"`.
   * Sent to the API in whole seconds (`MaxDurationSeconds`).
   */
  maxDuration?: Duration.Input;
}

/**
 * CloudWatch log configuration for the playback configuration
 * (`ConfigureLogsForPlaybackConfiguration`).
 */
export interface PlaybackConfigurationLogs {
  /**
   * The percentage of session logs MediaTailor sends to CloudWatch Logs
   * (0–100). Session logs land in the `MediaTailor/PlaybackConfiguration`
   * log group (legacy) or the vended-log delivery you configure.
   */
  percentEnabled: number;
  /**
   * The method MediaTailor uses to deliver the logs:
   * `LEGACY_CLOUDWATCH` (direct to CloudWatch Logs) and/or `VENDED_LOGS`
   * (CloudWatch vended log delivery to CloudWatch/S3/Firehose).
   */
  enabledLoggingStrategies?: ("LEGACY_CLOUDWATCH" | "VENDED_LOGS")[];
}

/**
 * Rules that customize how MediaTailor processes the origin manifest.
 */
export interface PlaybackConfigurationManifestProcessingRules {
  /**
   * When enabled, `EXT-X-CUE-IN`/`EXT-X-CUE-OUT` (and other ad markers) from
   * the origin manifest pass through into the personalized manifest.
   * @default false
   */
  adMarkerPassthroughEnabled?: boolean;
}

export interface PlaybackConfigurationProps {
  /**
   * The identifier for the playback configuration. Maximum 64 characters,
   * letters, digits, hyphens, and underscores.
   *
   * Changing the name replaces the configuration.
   * @default ${app}-${stage}-${id}
   */
  name?: string;
  /**
   * The URL for the ad decision server (ADS). This includes the
   * specification of static parameters and placeholders for dynamic
   * parameters, e.g. `https://ads.example.com/vast?ip=[client_ip]`.
   * Maximum 25,000 characters.
   */
  adDecisionServerUrl: string;
  /**
   * The URL prefix for the source of the content stream (the origin server),
   * minus the asset ID. Maximum 512 characters.
   */
  videoContentSourceUrl: string;
  /**
   * The URL for a video asset to transcode and use to fill in time that's
   * not used by ads. MediaTailor shows the slate when there is no ad to
   * fill an avail.
   */
  slateAdUrl?: string;
  /**
   * Defines the maximum duration of underfilled ad time (e.g. `"2 seconds"`)
   * allowed in an ad break. Underfilled time beyond the threshold is not
   * filled with slate. Sent to the API in whole seconds
   * (`PersonalizationThresholdSeconds`).
   */
  personalizationThreshold?: Duration.Input;
  /**
   * The name that is used to associate this playback configuration with a
   * custom transcode profile (set up with AWS Support).
   */
  transcodeProfileName?: string;
  /**
   * The setting that controls whether players can use stitched or guided ad
   * insertion. One of `STITCHED_ONLY` or `PLAYER_SELECT`.
   * @default "STITCHED_ONLY"
   */
  insertionMode?: "STITCHED_ONLY" | "PLAYER_SELECT";
  /**
   * CDN prefixes for routing ad and content segment requests.
   */
  cdnConfiguration?: PlaybackConfigurationCdn;
  /**
   * DASH manifest configuration.
   */
  dashConfiguration?: PlaybackConfigurationDash;
  /**
   * Ad suppression behavior near the live edge.
   */
  availSuppression?: PlaybackConfigurationAvailSuppression;
  /**
   * Bumper videos played before and after ad breaks.
   */
  bumper?: PlaybackConfigurationBumper;
  /**
   * Pre-roll ad insertion for live streams.
   */
  livePreRollConfiguration?: PlaybackConfigurationLivePreRoll;
  /**
   * Origin-manifest processing rules (e.g. ad marker passthrough).
   */
  manifestProcessingRules?: PlaybackConfigurationManifestProcessingRules;
  /**
   * CloudWatch session-log configuration. Omit (or set `percentEnabled: 0`)
   * to disable session logging.
   */
  logConfiguration?: PlaybackConfigurationLogs;
  /**
   * Tags to apply to the playback configuration. Merged with internal
   * Alchemy tags.
   */
  tags?: Record<string, string>;
}

export interface PlaybackConfiguration extends Resource<
  "AWS.MediaTailor.PlaybackConfiguration",
  PlaybackConfigurationProps,
  {
    /** The identifier for the playback configuration. */
    name: string;
    /** The ARN of the playback configuration. */
    playbackConfigurationArn: string;
    /** The URL that the player accesses to get a manifest from MediaTailor. */
    playbackEndpointPrefix: string;
    /** The URL that the player uses to initialize a session that uses client-side reporting. */
    sessionInitializationEndpointPrefix: string;
    /** The HLS manifest endpoint prefix, if HLS is configured. */
    hlsManifestEndpointPrefix: string | undefined;
    /** The DASH manifest endpoint prefix, if DASH is configured. */
    dashManifestEndpointPrefix: string | undefined;
  },
  never,
  Providers
> {}

/**
 * An AWS Elemental MediaTailor playback configuration for server-side ad
 * insertion (SSAI) into HLS and DASH video streams.
 *
 * ### Creating Playback Configurations
 * **Example:** Basic ad-inserted stream
 * ```typescript
 * import * as MediaTailor from "alchemy/AWS/MediaTailor";
 *
 * const config = yield* MediaTailor.PlaybackConfiguration("Ads", {
 *   adDecisionServerUrl: "https://ads.example.com/vast?ip=[client_ip]",
 *   videoContentSourceUrl: "https://origin.example.com/live",
 * });
 * ```
 *
 * **Example:** Slate fill and personalization threshold
 * ```typescript
 * const config = yield* MediaTailor.PlaybackConfiguration("Ads", {
 *   adDecisionServerUrl: "https://ads.example.com/vast",
 *   videoContentSourceUrl: "https://origin.example.com/vod",
 *   slateAdUrl: "https://origin.example.com/slate.mp4",
 *   personalizationThreshold: "2 seconds",
 * });
 * ```
 *
 * ### Manifest Behavior
 * **Example:** Ad marker passthrough and avail suppression
 * ```typescript
 * const config = yield* MediaTailor.PlaybackConfiguration("Live", {
 *   adDecisionServerUrl: "https://ads.example.com/vast",
 *   videoContentSourceUrl: "https://origin.example.com/live",
 *   manifestProcessingRules: { adMarkerPassthroughEnabled: true },
 *   availSuppression: { mode: "BEHIND_LIVE_EDGE", value: "00:00:30" },
 * });
 * ```
 *
 * ### Session Logging
 * **Example:** Send 10% of session logs to CloudWatch
 * ```typescript
 * const config = yield* MediaTailor.PlaybackConfiguration("Logged", {
 *   adDecisionServerUrl: "https://ads.example.com/vast",
 *   videoContentSourceUrl: "https://origin.example.com/live",
 *   logConfiguration: { percentEnabled: 10 },
 * });
 * ```
 *
 * @resource
 */
export const PlaybackConfiguration = Resource<PlaybackConfiguration>(
  "AWS.MediaTailor.PlaybackConfiguration",
);

/**
 * Raised when MediaTailor returns a playback configuration without the
 * attributes the provider needs (ARN and playback endpoints). This indicates
 * an unexpected API response rather than a user error.
 */
export class MediaTailorIncompletePlaybackConfiguration extends Data.TaggedError(
  "MediaTailorIncompletePlaybackConfiguration",
)<{ message: string }> {}

type PlaybackConfigurationAttributes = {
  name: string;
  playbackConfigurationArn: string;
  playbackEndpointPrefix: string;
  sessionInitializationEndpointPrefix: string;
  hlsManifestEndpointPrefix: string | undefined;
  dashManifestEndpointPrefix: string | undefined;
};

export const PlaybackConfigurationProvider = () =>
  Provider.effect(
    PlaybackConfiguration,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: Pick<PlaybackConfigurationProps, "name">,
      ) {
        // MediaTailor playback configuration names max out at 64 characters.
        return props.name ?? (yield* createPhysicalName({ id, maxLength: 64 }));
      });

      const toAttributes = Effect.fn(function* (
        config: mediatailor.GetPlaybackConfigurationResponse,
      ) {
        if (
          config.Name === undefined ||
          config.PlaybackConfigurationArn === undefined ||
          config.PlaybackEndpointPrefix === undefined ||
          config.SessionInitializationEndpointPrefix === undefined
        ) {
          return yield* new MediaTailorIncompletePlaybackConfiguration({
            message: `playback configuration '${config.Name}' is missing its ARN or endpoint prefixes`,
          });
        }
        return {
          name: config.Name,
          playbackConfigurationArn: config.PlaybackConfigurationArn,
          playbackEndpointPrefix: config.PlaybackEndpointPrefix,
          sessionInitializationEndpointPrefix:
            config.SessionInitializationEndpointPrefix,
          hlsManifestEndpointPrefix:
            config.HlsConfiguration?.ManifestEndpointPrefix,
          dashManifestEndpointPrefix:
            config.DashConfiguration?.ManifestEndpointPrefix,
        } satisfies PlaybackConfigurationAttributes;
      });

      const observe = (name: string) =>
        mediatailor.getPlaybackConfiguration({ Name: name }).pipe(
          Effect.map(
            (
              config,
            ): mediatailor.GetPlaybackConfigurationResponse | undefined =>
              config,
          ),
          // Typed synthetic tag for a missing playback configuration.
          Effect.catchTag("PlaybackConfigurationNotFound", () =>
            Effect.succeed(undefined),
          ),
        );

      const desiredRequest = (
        name: string,
        props: PlaybackConfigurationProps,
      ): mediatailor.PutPlaybackConfigurationRequest => ({
        Name: name,
        AdDecisionServerUrl: props.adDecisionServerUrl,
        VideoContentSourceUrl: props.videoContentSourceUrl,
        SlateAdUrl: props.slateAdUrl,
        PersonalizationThresholdSeconds: toWireSeconds(
          props.personalizationThreshold,
        ),
        TranscodeProfileName: props.transcodeProfileName,
        InsertionMode: props.insertionMode,
        CdnConfiguration: props.cdnConfiguration && {
          AdSegmentUrlPrefix: props.cdnConfiguration.adSegmentUrlPrefix,
          ContentSegmentUrlPrefix:
            props.cdnConfiguration.contentSegmentUrlPrefix,
        },
        DashConfiguration: props.dashConfiguration && {
          MpdLocation: props.dashConfiguration.mpdLocation,
          OriginManifestType: props.dashConfiguration.originManifestType,
        },
        AvailSuppression: props.availSuppression && {
          Mode: props.availSuppression.mode,
          Value: props.availSuppression.value,
          FillPolicy: props.availSuppression.fillPolicy,
        },
        Bumper: props.bumper && {
          StartUrl: props.bumper.startUrl,
          EndUrl: props.bumper.endUrl,
        },
        LivePreRollConfiguration: props.livePreRollConfiguration && {
          AdDecisionServerUrl:
            props.livePreRollConfiguration.adDecisionServerUrl,
          MaxDurationSeconds: toWireSeconds(
            props.livePreRollConfiguration.maxDuration,
          ),
        },
        ManifestProcessingRules: props.manifestProcessingRules && {
          AdMarkerPassthrough: {
            Enabled: props.manifestProcessingRules.adMarkerPassthroughEnabled,
          },
        },
      });

      return PlaybackConfiguration.Provider.of({
        stables: ["name", "playbackConfigurationArn"],
        list: () =>
          Effect.gen(function* () {
            const items = yield* mediatailor.listPlaybackConfigurations
              .items({})
              .pipe(Stream.runCollect);
            return Array.from(items).flatMap((config) =>
              config.Name !== undefined &&
              config.PlaybackConfigurationArn !== undefined &&
              config.PlaybackEndpointPrefix !== undefined &&
              config.SessionInitializationEndpointPrefix !== undefined
                ? [
                    {
                      name: config.Name,
                      playbackConfigurationArn: config.PlaybackConfigurationArn,
                      playbackEndpointPrefix: config.PlaybackEndpointPrefix,
                      sessionInitializationEndpointPrefix:
                        config.SessionInitializationEndpointPrefix,
                      hlsManifestEndpointPrefix:
                        config.HlsConfiguration?.ManifestEndpointPrefix,
                      dashManifestEndpointPrefix:
                        config.DashConfiguration?.ManifestEndpointPrefix,
                    },
                  ]
                : [],
            );
          }),
        read: Effect.fn(function* ({ id, olds, output }) {
          const name = output?.name ?? (yield* createName(id, olds ?? {}));
          const found = yield* observe(name);
          if (found === undefined) return undefined;
          const attrs = yield* toAttributes(found);
          return (yield* hasAlchemyTags(id, tagRecord(found.Tags)))
            ? attrs
            : Unowned(attrs);
        }),
        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds ?? {});
          const newName = yield* createName(id, news ?? {});
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
          // fall through: engine default update logic for mutable fields
        }),
        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const name = output?.name ?? (yield* createName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };

          // 1. ENSURE + SYNC — PutPlaybackConfiguration is a full-replace
          //    upsert: omitted fields are cleared server-side. Because a
          //    prop the user removed must be un-set on the cloud config,
          //    the put is always applied (a subset comparison against the
          //    observed config cannot see removals, and server-side
          //    defaults make full-equality checks fragile). This one call
          //    converges greenfield, update, and adoption identically.
          const put = yield* mediatailor.putPlaybackConfiguration({
            ...desiredRequest(name, news),
            Tags: desiredTags,
          });
          const attrs = yield* toAttributes(put);

          // 2. SYNC LOGS — ConfigureLogsForPlaybackConfiguration is a
          //    separate API; diff the OBSERVED post-put log configuration
          //    against the desired one and only call the API on a delta.
          //    A removed `logConfiguration` prop converges to percent 0
          //    (session logging disabled).
          const desiredLogs = news.logConfiguration;
          const observedLogs = put.LogConfiguration;
          const observedPercent = observedLogs?.PercentEnabled ?? 0;
          const desiredPercent = desiredLogs?.percentEnabled ?? 0;
          const observedStrategies = [
            ...(observedLogs?.EnabledLoggingStrategies ?? []),
          ].sort();
          const desiredStrategies =
            desiredLogs === undefined
              ? observedStrategies // nothing desired: only percent converges
              : [...(desiredLogs.enabledLoggingStrategies ?? [])].sort();
          if (
            observedPercent !== desiredPercent ||
            observedStrategies.join(",") !== desiredStrategies.join(",")
          ) {
            yield* mediatailor.configureLogsForPlaybackConfiguration({
              PlaybackConfigurationName: name,
              PercentEnabled: desiredPercent,
              ...(desiredLogs?.enabledLoggingStrategies
                ? {
                    EnabledLoggingStrategies:
                      desiredLogs.enabledLoggingStrategies,
                  }
                : {}),
            });
          }

          // 3. SYNC TAGS — diff against the OBSERVED post-put tags so
          //    adoption (which can bring foreign tags the put may not
          //    remove) converges.
          const currentTags = tagRecord(put.Tags);
          const { upsert, removed } = diffTags(currentTags, desiredTags);
          if (upsert.length > 0) {
            yield* mediatailor.tagResource({
              ResourceArn: attrs.playbackConfigurationArn,
              Tags: Object.fromEntries(upsert.map((t) => [t.Key, t.Value])),
            });
          }
          if (removed.length > 0) {
            yield* mediatailor.untagResource({
              ResourceArn: attrs.playbackConfigurationArn,
              TagKeys: removed,
            });
          }

          yield* session.note(name);
          return attrs;
        }),
        delete: Effect.fn(function* ({ output }) {
          // DeletePlaybackConfiguration is idempotent server-side: deleting
          // a configuration that does not exist succeeds with an empty body
          // (verified live), so no not-found handling is required.
          yield* mediatailor.deletePlaybackConfiguration({
            Name: output.name,
          });
        }),
      });
    }),
  );

import * as ses from "@distilled.cloud/aws/ses";
import * as Effect from "effect/Effect";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import type { Providers } from "../Providers.ts";

/**
 * Whether the filter permits (`Allow`) or blocks (`Block`) mail from the
 * matching IP range.
 */
export type ReceiptFilterPolicy = ses.ReceiptFilterPolicy;

export interface ReceiptIpFilter {
  /**
   * Whether to allow or block mail from the CIDR range.
   */
  policy: ReceiptFilterPolicy;
  /**
   * A single IPv4 address (e.g. `1.2.3.4`) or CIDR range (e.g. `1.2.3.0/24`)
   * the filter applies to.
   */
  cidr: string;
}

export interface ReceiptFilterProps {
  /**
   * Name of the IP address filter. May contain letters, numbers, dashes and
   * underscores, up to 64 characters, and must start and end with a letter or
   * number. If omitted, a deterministic physical name is generated from the
   * app, stage, and logical ID. Changing the name replaces the filter.
   */
  filterName?: string;
  /**
   * The IP filtering rule — an allow or block decision for a CIDR range.
   * Changing it replaces the filter (SES has no update operation for filters).
   */
  ipFilter: ReceiptIpFilter;
}

export interface ReceiptFilter extends Resource<
  "AWS.SES.ReceiptFilter",
  ReceiptFilterProps,
  {
    /** Name of the IP address filter. */
    filterName: string;
  },
  never,
  Providers
> {}

/**
 * An Amazon SES receipt IP address filter — an account-level allow/block rule
 * for the source IP of inbound mail. Block filters take precedence over allow
 * filters.
 *
 * Filters are immutable: there is no update API, so any change to the name or
 * the IP rule replaces the filter.
 * ### Creating Filters
 * **Example:** Block a CIDR Range
 * ```typescript
 * import * as SES from "alchemy/AWS/SES";
 *
 * const filter = yield* SES.ReceiptFilter("BlockBadActors", {
 *   ipFilter: { policy: "Block", cidr: "10.0.0.0/24" },
 * });
 * ```
 *
 * **Example:** Allow a Single Address
 * ```typescript
 * const filter = yield* SES.ReceiptFilter("AllowPartner", {
 *   ipFilter: { policy: "Allow", cidr: "192.0.2.10" },
 * });
 * ```
 *
 * @resource
 */
export const ReceiptFilter = Resource<ReceiptFilter>("AWS.SES.ReceiptFilter");

export const ReceiptFilterProvider = () =>
  Provider.effect(
    ReceiptFilter,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: Pick<ReceiptFilterProps, "filterName">,
      ) {
        return (
          props.filterName ?? (yield* createPhysicalName({ id, maxLength: 64 }))
        );
      });

      const findFilter = Effect.fn(function* (name: string) {
        const filters = yield* ses
          .listReceiptFilters({})
          .pipe(Effect.map((response) => response.Filters ?? []));
        return filters.find((filter) => filter.Name === name);
      });

      return ReceiptFilter.Provider.of({
        stables: ["filterName"],

        // Account/region-scoped: enumerate every filter so leaked test
        // resources are cleaned by nuke. Receipt filters carry no tags.
        list: () =>
          ses
            .listReceiptFilters({})
            .pipe(
              Effect.map((response) =>
                (response.Filters ?? []).flatMap((filter) =>
                  filter.Name ? [{ filterName: filter.Name }] : [],
                ),
              ),
            ),

        read: Effect.fn(function* ({ id, olds, output }) {
          const name = output?.filterName ?? (yield* createName(id, olds));
          const found = yield* findFilter(name);
          return found ? { filterName: name } : undefined;
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds);
          const newName = yield* createName(id, news);
          if (
            oldName !== newName ||
            olds.ipFilter.policy !== news.ipFilter.policy ||
            olds.ipFilter.cidr !== news.ipFilter.cidr
          ) {
            return { action: "replace" } as const;
          }
        }),

        reconcile: Effect.fn(function* ({ id, news, output }) {
          const name = output?.filterName ?? (yield* createName(id, news));

          // OBSERVE — filters have no update API, so reconcile is create-only.
          const observed = yield* findFilter(name);

          // ENSURE — create if missing; AlreadyExists is a race, not a failure.
          if (observed === undefined) {
            yield* ses
              .createReceiptFilter({
                Filter: {
                  Name: name,
                  IpFilter: {
                    Policy: news.ipFilter.policy,
                    Cidr: news.ipFilter.cidr,
                  },
                },
              })
              .pipe(
                Effect.catchTag("AlreadyExistsException", () =>
                  Effect.succeed({}),
                ),
              );
          }

          return { filterName: name };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteReceiptFilter is idempotent for a missing filter.
          yield* ses.deleteReceiptFilter({ FilterName: output.filterName });
        }),
      });
    }),
  );

import * as ses from "@distilled.cloud/aws/ses";
import * as Effect from "effect/Effect";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import type { Providers } from "../Providers.ts";

export interface ReceiptRuleSetProps {
  /**
   * Name of the receipt rule set. May contain letters, numbers, dashes,
   * underscores and periods, up to 64 characters, and must start and end with
   * a letter or number. If omitted, a deterministic physical name is generated
   * from the app, stage, and logical ID. Changing the name replaces the rule
   * set.
   */
  ruleSetName?: string;
}

export interface ReceiptRuleSet extends Resource<
  "AWS.SES.ReceiptRuleSet",
  ReceiptRuleSetProps,
  {
    /** Name of the receipt rule set. */
    ruleSetName: string;
  },
  never,
  Providers
> {}

/**
 * An Amazon SES receipt rule set — the ordered container for the receipt rules
 * that decide what happens to inbound email (deliver to S3, invoke a Lambda,
 * publish to SNS, bounce, etc.).
 *
 * A rule set is an empty container on creation; add `SES.ReceiptRule`s to it
 * and point the account at it with `SES.ActiveReceiptRuleSet` to start
 * processing mail. Email receiving is only available in a subset of regions
 * (e.g. `us-east-1`, `us-west-2`, `eu-west-1`).
 * ### Creating Rule Sets
 * **Example:** Basic Rule Set
 * ```typescript
 * import * as SES from "alchemy/AWS/SES";
 *
 * const ruleSet = yield* SES.ReceiptRuleSet("Inbound", {});
 * ```
 *
 * **Example:** Named Rule Set
 * ```typescript
 * const ruleSet = yield* SES.ReceiptRuleSet("Inbound", {
 *   ruleSetName: "my-inbound-rules",
 * });
 * ```
 *
 * ### Activating a Rule Set
 * **Example:** Point the Account at a Rule Set
 * ```typescript
 * const ruleSet = yield* SES.ReceiptRuleSet("Inbound", {});
 * yield* SES.ActiveReceiptRuleSet("Active", {
 *   ruleSetName: ruleSet.ruleSetName,
 * });
 * ```
 *
 * @resource
 */
export const ReceiptRuleSet = Resource<ReceiptRuleSet>(
  "AWS.SES.ReceiptRuleSet",
);

export const ReceiptRuleSetProvider = () =>
  Provider.effect(
    ReceiptRuleSet,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: Pick<ReceiptRuleSetProps, "ruleSetName">,
      ) {
        return (
          props.ruleSetName ??
          (yield* createPhysicalName({ id, maxLength: 64 }))
        );
      });

      const describe = Effect.fn(function* (name: string) {
        return yield* ses
          .describeReceiptRuleSet({ RuleSetName: name })
          .pipe(
            Effect.catchTag("RuleSetDoesNotExistException", () =>
              Effect.succeed(undefined),
            ),
          );
      });

      return ReceiptRuleSet.Provider.of({
        stables: ["ruleSetName"],

        // Account/region-scoped: enumerate every rule set so leaked test
        // resources are cleaned by nuke. Classic receipt rule sets carry no
        // tags, so there is no ownership signal to filter on.
        list: () =>
          Effect.gen(function* () {
            const rows: { ruleSetName: string }[] = [];
            let nextToken: string | undefined;
            do {
              const page = yield* ses.listReceiptRuleSets({
                NextToken: nextToken,
              });
              for (const set of page.RuleSets ?? []) {
                if (set.Name) rows.push({ ruleSetName: set.Name });
              }
              nextToken = page.NextToken;
            } while (nextToken);
            return rows;
          }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const name = output?.ruleSetName ?? (yield* createName(id, olds));
          const found = yield* describe(name);
          // Receipt rule sets are untagged in the classic API, so there is no
          // way to distinguish a foreign rule set from one we own. Existence
          // at our deterministic name is treated as ownership.
          return found ? { ruleSetName: name } : undefined;
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds);
          const newName = yield* createName(id, news);
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
        }),

        reconcile: Effect.fn(function* ({ id, news, output }) {
          const name = output?.ruleSetName ?? (yield* createName(id, news));

          // OBSERVE — cloud state is authoritative.
          const observed = yield* describe(name);

          // ENSURE — create if missing; AlreadyExists is a race, not a failure.
          if (observed === undefined) {
            yield* ses
              .createReceiptRuleSet({ RuleSetName: name })
              .pipe(
                Effect.catchTag("AlreadyExistsException", () =>
                  Effect.succeed({}),
                ),
              );
          }

          // A rule set has no mutable aspects of its own; rules are separate
          // `SES.ReceiptRule` resources.
          return { ruleSetName: name };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteReceiptRuleSet is idempotent for a missing set; the active
          // set cannot be deleted and surfaces as a typed CannotDeleteException.
          yield* ses.deleteReceiptRuleSet({
            RuleSetName: output.ruleSetName,
          });
        }),
      });
    }),
  );

import * as sdb from "@distilled.cloud/aws/simpledb";
import * as Effect from "effect/Effect";
import * as Schedule from "effect/Schedule";
import * as Stream from "effect/Stream";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";

export interface DomainProps {
  /**
   * Name of the SimpleDB domain. 3-255 characters; letters, digits, `_`,
   * `-`, and `.` are allowed. Changing the name replaces the domain.
   * @default a generated physical name
   */
  domainName?: string;
}

export interface Domain extends Resource<
  "AWS.SimpleDB.Domain",
  DomainProps,
  {
    domainName: string;
    domainArn: string;
  },
  {},
  Providers
> {}

/**
 * An Amazon SimpleDB domain — the container for SimpleDB items and
 * attributes, analogous to a table.
 *
 * SimpleDB is a legacy service (closed to accounts that never used it and
 * slated for migration via the SimpleDBv2 export API), but domains remain
 * fully manageable on grandfathered accounts. A domain has no mutable
 * configuration: the name is its identity, so any name change replaces the
 * domain. SimpleDB has no tagging API, so Alchemy cannot brand domains for
 * ownership detection.
 * ### Creating Domains
 * **Example:** Basic Domain
 * ```typescript
 * import * as AWS from "alchemy/AWS";
 *
 * const domain = yield* AWS.SimpleDB.Domain("MyDomain", {});
 * ```
 *
 * **Example:** Named Domain
 * ```typescript
 * const domain = yield* AWS.SimpleDB.Domain("MyDomain", {
 *   domainName: "my-application-data",
 * });
 * ```
 *
 * @resource
 */
export const Domain = Resource<Domain>("AWS.SimpleDB.Domain");

/**
 * CreateDomain is eventually consistent — DomainMetadata directly after a
 * create can briefly report NoSuchDomain. Explicitly typed so the
 * conditional `Retry.Return` type does not leak into declaration emit.
 */
const retryWhileNoSuchDomain = <A, E extends { readonly _tag: string }, R>(
  self: Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> =>
  Effect.retry(self, {
    while: (e) => e._tag === "NoSuchDomain",
    schedule: Schedule.max([Schedule.fixed("2 seconds"), Schedule.recurs(10)]),
  });

export const DomainProvider = () =>
  Provider.effect(
    Domain,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (id: string, props: DomainProps) {
        return (
          props.domainName ??
          (yield* createPhysicalName({ id, maxLength: 255 }))
        );
      });

      const domainArn = (region: string, accountId: string, name: string) =>
        `arn:aws:sdb:${region}:${accountId}:domain/${name}`;

      const observeDomain = Effect.fn(function* (name: string) {
        return yield* sdb
          .domainMetadata({ DomainName: name })
          .pipe(
            Effect.catchTag("NoSuchDomain", () => Effect.succeed(undefined)),
          );
      });

      return Domain.Provider.of({
        stables: ["domainName", "domainArn"],

        list: () =>
          Effect.gen(function* () {
            const { accountId, region } = yield* AWSEnvironment.current;
            const names = yield* sdb.listDomains
              .items({})
              .pipe(Stream.runCollect);
            return Array.from(names).map((name) => ({
              domainName: name,
              domainArn: domainArn(region, accountId, name),
            }));
          }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name =
            output?.domainName ?? (yield* createName(id, olds ?? {}));
          const metadata = yield* observeDomain(name);
          if (metadata === undefined) {
            return undefined;
          }
          // SimpleDB has no tagging API, so ownership cannot be verified —
          // an existing domain with the derived name is treated as ours.
          return {
            domainName: name,
            domainArn: domainArn(region, accountId, name),
          };
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds ?? {});
          const newName = yield* createName(id, news);
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name = output?.domainName ?? (yield* createName(id, news));

          // 1. OBSERVE — cloud state is authoritative
          const metadata = yield* observeDomain(name);

          // 2. ENSURE — CreateDomain is idempotent (creating an existing
          //    domain succeeds); wait until the domain is visible.
          if (metadata === undefined) {
            yield* sdb.createDomain({ DomainName: name });
            yield* retryWhileNoSuchDomain(
              sdb.domainMetadata({ DomainName: name }),
            );
          }

          // 3. SYNC — a domain has no mutable configuration and no tags.

          yield* session.note(name);
          return {
            domainName: name,
            domainArn: domainArn(region, accountId, name),
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // DeleteDomain is idempotent — deleting a missing domain succeeds.
          yield* sdb.deleteDomain({ DomainName: output.domainName });
        }),
      });
    }),
  );

import * as sns from "@distilled.cloud/aws/sns";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import * as Stream from "effect/Stream";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";

export type PlatformApplicationArn = string;

export interface PlatformApplicationProps {
  /**
   * Name of the platform application. Up to 256 characters of letters,
   * numbers, underscores, hyphens, and periods.
   * @default ${app}-${stage}-${id}
   */
  name?: string;
  /**
   * Push notification platform, e.g. `GCM` (Firebase Cloud Messaging),
   * `APNS`, `APNS_SANDBOX`, `ADM`, or `BAIDU`. Changing the platform
   * replaces the application.
   */
  platform: string;
  /**
   * Platform credential — the FCM API key / service account JSON (GCM), the
   * APNS private key, or the ADM client secret. SNS validates the credential
   * at creation time. Write-only: SNS never returns it, so it is pushed on
   * create/adopt and whenever the configured value changes.
   */
  platformCredential: Redacted.Redacted<string>;
  /**
   * Platform principal — the APNS SSL certificate or ADM client id. Not
   * applicable for GCM. Write-only like `platformCredential`.
   */
  platformPrincipal?: Redacted.Redacted<string>;
  /**
   * Additional mutable SNS platform application attributes keyed by AWS
   * attribute name, such as `EventEndpointCreated`, `EventDeliveryFailure`,
   * `SuccessFeedbackRoleArn`, or `SuccessFeedbackSampleRate`.
   */
  attributes?: Record<string, string>;
}

export interface PlatformApplication extends Resource<
  "AWS.SNS.PlatformApplication",
  PlatformApplicationProps,
  {
    /** ARN of the platform application. */
    platformApplicationArn: PlatformApplicationArn;
    /** Name of the platform application. */
    name: string;
    /** Push notification platform (e.g. `GCM`, `APNS`). */
    platform: string;
    /** Whether the platform application is enabled (credentials valid). */
    enabled: boolean;
    /** Observed non-sensitive SNS attributes keyed by AWS attribute name. */
    attributes: Record<string, string>;
  },
  never,
  Providers
> {}

/**
 * An Amazon SNS platform application for mobile push notifications (FCM,
 * APNS, ADM, Baidu).
 *
 * A platform application holds the push service credentials; device tokens
 * are registered against it at runtime with the
 * `CreatePlatformEndpoint` binding, and messages are delivered with
 * `PublishToEndpoint`. SNS validates the credential when the application is
 * created, so a real push-service credential is required.
 * ### Creating Platform Applications
 * **Example:** FCM (GCM) Application
 * ```typescript
 * import * as SNS from "alchemy/AWS/SNS";
 * import * as Redacted from "effect/Redacted";
 *
 * const app = yield* SNS.PlatformApplication("PushApp", {
 *   platform: "GCM",
 *   platformCredential: Redacted.make(process.env.FCM_API_KEY!),
 * });
 * ```
 *
 * **Example:** APNS Application
 * ```typescript
 * const app = yield* SNS.PlatformApplication("IosPushApp", {
 *   platform: "APNS",
 *   platformCredential: Redacted.make(apnsPrivateKey),
 *   platformPrincipal: Redacted.make(apnsCertificate),
 * });
 * ```
 *
 * ### Runtime Endpoints
 * **Example:** Register a Device Token at Runtime
 * ```typescript
 * // init
 * const createEndpoint = yield* SNS.CreatePlatformEndpoint(app);
 * const publishToEndpoint = yield* SNS.PublishToEndpoint(app);
 *
 * // runtime
 * const endpoint = yield* createEndpoint({ Token: deviceToken });
 * yield* publishToEndpoint({
 *   TargetArn: endpoint.EndpointArn!,
 *   Message: "hello",
 * });
 * ```
 *
 * @resource
 */
export const PlatformApplication = Resource<PlatformApplication>(
  "AWS.SNS.PlatformApplication",
);

export const PlatformApplicationProvider = () =>
  Provider.succeed(PlatformApplication, {
    list: Effect.fn(function* () {
      const applications = yield* sns.listPlatformApplications.pages({}).pipe(
        Stream.runCollect,
        Effect.map((chunk) =>
          Array.from(chunk).flatMap((page) => page.PlatformApplications ?? []),
        ),
      );

      return applications.flatMap((application) => {
        const arn = application.PlatformApplicationArn;
        if (!arn) return [];
        return [toApplicationAttributes(arn, application.Attributes)];
      });
    }),
    read: Effect.fn(function* ({ id, olds, output }) {
      const arn =
        output?.platformApplicationArn ??
        (yield* toApplicationArn(id, olds ?? { platform: "" }));
      return yield* readApplication(arn);
    }),
    stables: ["platformApplicationArn", "name", "platform"],
    diff: Effect.fn(function* ({ id, news, olds }) {
      if (!isResolved(news)) return undefined;
      if (news.platform !== olds.platform) {
        return { action: "replace" } as const;
      }
      const oldName = yield* toApplicationName(id, olds);
      const newName = yield* toApplicationName(id, news);
      if (oldName !== newName) {
        return { action: "replace" } as const;
      }
    }),
    reconcile: Effect.fn(function* ({ id, news, olds, output, session }) {
      const name = yield* toApplicationName(id, news);
      const arn =
        output?.platformApplicationArn ?? (yield* toApplicationArn(id, news));

      // Observe — the credential attributes are write-only, so observation
      // covers existence plus the non-sensitive mutable attributes.
      const observed = yield* sns
        .getPlatformApplicationAttributes({ PlatformApplicationArn: arn })
        .pipe(
          Effect.map((response) => toAttributeMap(response.Attributes)),
          Effect.catchTag("NotFoundException", () => Effect.succeed(undefined)),
        );

      const credentialAttributes: Record<string, string> = {
        PlatformCredential: Redacted.value(news.platformCredential),
        ...(news.platformPrincipal
          ? { PlatformPrincipal: Redacted.value(news.platformPrincipal) }
          : undefined),
      };
      const desiredAttributes = toAttributeMap(news.attributes);

      // Ensure — create carries the full attribute set (credentials +
      // mutable attributes) in one call.
      if (observed === undefined) {
        const created = yield* sns.createPlatformApplication({
          Name: name,
          Platform: news.platform,
          Attributes: { ...desiredAttributes, ...credentialAttributes },
        });
        const platformApplicationArn = created.PlatformApplicationArn ?? arn;
        yield* session.note(platformApplicationArn);
        const state = yield* readApplication(platformApplicationArn);
        return (
          state ??
          toApplicationAttributes(platformApplicationArn, desiredAttributes)
        );
      }

      // Sync — mutable non-secret attributes diff observed vs desired;
      // removed previously-managed keys reset to "". Credentials cannot be
      // observed, so they are pushed on adoption (`olds` absent) or when the
      // configured value changes (`olds` is only a hint to skip a no-op).
      const updates: Record<string, string> = {};
      for (const [key, value] of Object.entries(desiredAttributes)) {
        if (observed[key] !== value) {
          updates[key] = value;
        }
      }
      for (const key of Object.keys(toAttributeMap(olds?.attributes))) {
        if (!(key in desiredAttributes)) {
          updates[key] = "";
        }
      }

      const credentialChanged =
        olds === undefined ||
        Redacted.value(olds.platformCredential) !==
          Redacted.value(news.platformCredential) ||
        (olds.platformPrincipal === undefined) !==
          (news.platformPrincipal === undefined) ||
        (olds.platformPrincipal !== undefined &&
          news.platformPrincipal !== undefined &&
          Redacted.value(olds.platformPrincipal) !==
            Redacted.value(news.platformPrincipal));
      if (credentialChanged) {
        Object.assign(updates, credentialAttributes);
      }

      if (Object.keys(updates).length > 0) {
        yield* sns.setPlatformApplicationAttributes({
          PlatformApplicationArn: arn,
          Attributes: updates,
        });
      }

      yield* session.note(arn);
      const state = yield* readApplication(arn);
      return state ?? toApplicationAttributes(arn, desiredAttributes);
    }),
    delete: Effect.fn(function* ({ output }) {
      // `DeletePlatformApplication` is idempotent — deleting a non-existent
      // application succeeds — so only genuine failures propagate.
      yield* sns.deletePlatformApplication({
        PlatformApplicationArn: output.platformApplicationArn,
      });
    }),
  });

const toApplicationName = Effect.fn(function* (
  id: string,
  props: Pick<PlatformApplicationProps, "name">,
) {
  if (props.name) {
    return props.name;
  }
  return yield* createPhysicalName({ id, maxLength: 256 });
});

const toApplicationArn = Effect.fn(function* (
  id: string,
  props: Pick<PlatformApplicationProps, "name" | "platform">,
) {
  const name = yield* toApplicationName(id, props);
  const { accountId, region } = yield* AWSEnvironment.current;
  return `arn:aws:sns:${region}:${accountId}:app/${props.platform}/${name}`;
});

const toAttributeMap = (
  attributes: Record<string, string | undefined> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    Object.entries(attributes ?? {}).filter(
      (entry): entry is [string, string] => typeof entry[1] === "string",
    ),
  );

const toApplicationAttributes = (
  arn: string,
  attributes: Record<string, string | undefined> | undefined,
) => {
  const observed = toAttributeMap(attributes);
  // arn:aws:sns:{region}:{account}:app/{Platform}/{Name}
  const [, platform = "", name = ""] = arn.split(":").at(-1)?.split("/") ?? [];
  return {
    platformApplicationArn: arn,
    name,
    platform,
    enabled: observed.Enabled !== "false",
    attributes: observed,
  };
};

const readApplication = Effect.fn(function* (arn: string) {
  const observed = yield* sns
    .getPlatformApplicationAttributes({ PlatformApplicationArn: arn })
    .pipe(
      Effect.map((response) => toAttributeMap(response.Attributes)),
      Effect.catchTag("NotFoundException", () => Effect.succeed(undefined)),
    );
  if (observed === undefined) {
    return undefined;
  }
  return toApplicationAttributes(arn, observed);
});

