/** @resource */
export interface ResponsePlan extends Resource<
  "AWS.SSMIncidents.ResponsePlan",
  ResponsePlanProps,
  {
    /** ARN of the response plan. */
    arn: string;
    /** Name of the response plan. */
    name: string;
  },
  never,
  Providers
> {}

/**
 * An Incident Manager response plan — the template that automates the initial
 * response to incidents by engaging contacts, starting chat-channel
 * collaboration, and running Automation runbooks.
 *
 * Requires the account's Incident Manager replication set
 * (`SSMIncidents.ReplicationSet`) to exist.
 *
 * ### Creating Response Plans
 * **Example:** Minimal response plan
 * ```typescript
 * const replicationSet = yield* SSMIncidents.ReplicationSet("Incidents", {});
 * const plan = yield* SSMIncidents.ResponsePlan("Critical", {
 *   incidentTemplate: { title: "Critical failure", impact: 1 },
 * });
 * ```
 *
 * **Example:** Response plan with engagements and chat channel
 * ```typescript
 * const plan = yield* SSMIncidents.ResponsePlan("Sev1", {
 *   displayName: "Severity 1 response",
 *   incidentTemplate: {
 *     title: "Sev1 incident",
 *     impact: 1,
 *     summary: "Automated Sev1 response",
 *     notificationTargets: [{ snsTopicArn: topic.topicArn }],
 *   },
 *   engagements: [oncall.contactArn],
 *   chatChannel: { chatbotSns: [topic.topicArn] },
 * });
 * ```
 */
const ResponsePlanResource = Resource<ResponsePlan>(
  "AWS.SSMIncidents.ResponsePlan",
);

export { ResponsePlanResource as ResponsePlan };

// Normalized deep-equality for desired-vs-observed sync comparisons —
// tolerates key ordering and treats absent optional lists as empty.
const normalize = (value: unknown): unknown => {
  if (Array.isArray(value)) return value.map(normalize);
  if (value !== null && typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value as Record<string, unknown>)
        .filter(([, v]) => v !== undefined)
        .sort(([l], [r]) => l.localeCompare(r))
        .map(([k, v]) => [k, normalize(v)]),
    );
  }
  return value;
};
const same = (l: unknown, r: unknown) =>
  JSON.stringify(normalize(l)) === JSON.stringify(normalize(r));

export const ResponsePlanProvider = () =>
  Provider.effect(
    ResponsePlanResource,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: { name?: string },
      ) {
        // Response plan names can't contain spaces; physical names are
        // DNS-safe already.
        return (
          props.name ?? (yield* createPhysicalName({ id, maxLength: 200 }))
        );
      });

      const findArnByName = (name: string) =>
        incidents.listResponsePlans.items({}).pipe(
          Stream.filter((summary) => summary.name === name),
          Stream.take(1),
          Stream.runCollect,
          Effect.map((chunk) => Array.from(chunk)[0]?.arn),
        );

      const getPlan = (arn: string) =>
        incidents
          .getResponsePlan({ arn })
          .pipe(
            Effect.catchTag("ResourceNotFoundException", () =>
              Effect.succeed(undefined),
            ),
          );

      const observe = Effect.fn(function* (
        name: string,
        arn: string | undefined,
      ) {
        if (arn !== undefined) {
          const byArn = yield* getPlan(arn);
          if (byArn !== undefined) return byArn;
        }
        const found = yield* findArnByName(name);
        return found === undefined ? undefined : yield* getPlan(found);
      });

      const readTags = (arn: string) =>
        incidents.listTagsForResource({ resourceArn: arn }).pipe(
          Effect.map(
            (r) =>
              Object.fromEntries(
                Object.entries(r.tags).filter(
                  (e): e is [string, string] => e[1] !== undefined,
                ),
              ) as Record<string, string>,
          ),
          Effect.catch(() => Effect.succeed<Record<string, string>>({})),
        );

      return ResponsePlanResource.Provider.of({
        stables: ["arn", "name"],

        list: () =>
          incidents.listResponsePlans.items({}).pipe(
            Stream.runCollect,
            Effect.map((chunk) =>
              Array.from(chunk).map((summary) => ({
                arn: summary.arn,
                name: summary.name,
              })),
            ),
          ),

        read: Effect.fn(function* ({ id, olds, output }) {
          const name = output?.name ?? (yield* createName(id, olds ?? {}));
          const plan = yield* observe(name, output?.arn);
          if (plan === undefined) return undefined;
          const attrs = { arn: plan.arn, name: plan.name };
          const tags = yield* readTags(plan.arn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        // The name is create-only; everything else updates in place.
        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds);
          const newName = yield* createName(id, news);
          if (oldName !== newName) return { action: "replace" } as const;
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const name = output?.name ?? (yield* createName(id, news));
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };

          // 1. OBSERVE
          let plan = yield* observe(name, output?.arn);

          // 2. ENSURE — create if missing; tolerate the already-exists race.
          if (plan === undefined) {
            yield* session.note(`creating response plan ${name}`);
            const arn = yield* incidents
              .createResponsePlan({
                name,
                displayName: news.displayName,
                incidentTemplate: news.incidentTemplate,
                chatChannel: news.chatChannel,
                engagements: news.engagements,
                actions: news.actions,
                integrations: news.integrations,
                tags: desiredTags,
              })
              .pipe(
                Effect.map((r) => r.arn),
                Effect.catchTag("ConflictException", () =>
                  findArnByName(name).pipe(Effect.map((found) => found!)),
                ),
              );
            plan = (yield* getPlan(arn))!;
          }
          const arn = plan.arn;

          // 3. SYNC — diff each mutable aspect of the OBSERVED plan against
          //    the desired state; call updateResponsePlan only on a delta.
          //    Empty strings / empty arrays clear a previously-set value.
          const desired = {
            displayName: news.displayName ?? "",
            incidentTemplate: {
              title: news.incidentTemplate.title,
              impact: news.incidentTemplate.impact,
              summary: news.incidentTemplate.summary ?? "",
              dedupeString: news.incidentTemplate.dedupeString ?? "",
              notificationTargets:
                news.incidentTemplate.notificationTargets ?? [],
              incidentTags: news.incidentTemplate.incidentTags ?? {},
            },
            engagements: [...(news.engagements ?? [])].sort(),
            actions: news.actions ?? [],
            integrations: news.integrations ?? [],
          };
          const observed = {
            displayName: plan.displayName ?? "",
            incidentTemplate: {
              title: plan.incidentTemplate.title,
              impact: plan.incidentTemplate.impact,
              summary: plan.incidentTemplate.summary ?? "",
              dedupeString: plan.incidentTemplate.dedupeString ?? "",
              notificationTargets:
                plan.incidentTemplate.notificationTargets ?? [],
              incidentTags: plan.incidentTemplate.incidentTags ?? {},
            },
            engagements: [...(plan.engagements ?? [])].sort(),
            actions: plan.actions ?? [],
            integrations: plan.integrations ?? [],
          };
          const chatChannelDelta =
            news.chatChannel !== undefined &&
            !same(plan.chatChannel, news.chatChannel);
          if (!same(desired, observed) || chatChannelDelta) {
            yield* incidents.updateResponsePlan({
              arn,
              displayName: desired.displayName,
              incidentTemplateTitle: desired.incidentTemplate.title,
              incidentTemplateImpact: desired.incidentTemplate.impact,
              incidentTemplateSummary: desired.incidentTemplate.summary,
              incidentTemplateDedupeString:
                desired.incidentTemplate.dedupeString,
              incidentTemplateNotificationTargets:
                desired.incidentTemplate.notificationTargets,
              incidentTemplateTags: desired.incidentTemplate.incidentTags,
              chatChannel: news.chatChannel,
              engagements: desired.engagements,
              actions: desired.actions,
              integrations: desired.integrations,
            });
          }

          // 3b. SYNC tags — diff against OBSERVED cloud tags.
          const currentTags = yield* readTags(arn);
          const { upsert, removed } = diffTags(currentTags, desiredTags);
          if (upsert.length > 0) {
            yield* incidents.tagResource({
              resourceArn: arn,
              tags: Object.fromEntries(upsert.map((t) => [t.Key, t.Value])),
            });
          }
          if (removed.length > 0) {
            yield* incidents.untagResource({
              resourceArn: arn,
              tagKeys: removed,
            });
          }

          yield* session.note(arn);
          return { arn, name };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteResponsePlan is idempotent for missing plans; tolerate the
          // typed not-found in case AWS starts returning it.
          yield* incidents
            .deleteResponsePlan({ arn: output.arn })
            .pipe(Effect.asVoid);
        }),
      });
    }),
  );

import * as sfn from "@distilled.cloud/aws/sfn";
import * as Effect from "effect/Effect";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, diffTags, hasAlchemyTags } from "../../Tags.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { Providers } from "../Providers.ts";

export interface ActivityProps {
  /**
   * Name of the activity (1-80 characters; letters, digits, dashes and
   * underscores). If omitted, a deterministic physical name is generated
   * from the app, stage, and logical ID. Changing the name triggers a
   * replacement.
   */
  activityName?: string;
  /**
   * Tags to apply to the activity. Merged with internal Alchemy tags.
   */
  tags?: Record<string, string>;
}

export interface Activity extends Resource<
  "AWS.StepFunctions.Activity",
  ActivityProps,
  {
    /**
     * Physical name of the activity.
     */
    activityName: string;
    /**
     * ARN of the activity — reference it from a state machine Task state's
     * `Resource` field.
     */
    activityArn: string;
  },
  never,
  Providers
> {}

/**
 * An AWS Step Functions activity — a named endpoint that external workers
 * poll for tasks (`GetActivityTask`) and complete with the `SendTask*`
 * callback operations.
 *
 * Activities support worker-hosted task processing outside Lambda. For
 * most callback flows the `.waitForTaskToken` service-integration pattern
 * on a {@link StateMachine} Task state is preferred.
 * ### Creating Activities
 * **Example:** Basic Activity
 * ```typescript
 * import * as StepFunctions from "alchemy/AWS/StepFunctions";
 *
 * const activity = yield* StepFunctions.Activity("ApprovalActivity");
 * ```
 *
 * **Example:** Reference an Activity from a State Machine
 * ```typescript
 * const machine = yield* StepFunctions.StateMachine("ApprovalFlow", {
 *   definition: {
 *     StartAt: "WaitForWorker",
 *     States: {
 *       WaitForWorker: {
 *         Type: "Task",
 *         Resource: activity.activityArn,
 *         End: true,
 *       },
 *     },
 *   },
 * });
 * ```
 *
 * ### Completing Tasks at Runtime
 * **Example:** Send a task result scoped to the activity
 * ```typescript
 * // init
 * const sendTaskSuccess = yield* StepFunctions.SendTaskSuccess(activity);
 *
 * // runtime
 * yield* sendTaskSuccess({
 *   taskToken: token,
 *   output: JSON.stringify({ approved: true }),
 * });
 * ```
 *
 * @resource
 */
export const Activity = Resource<Activity>("AWS.StepFunctions.Activity");

const toSfnTags = (tags: Record<string, string>): sfn.Tag[] =>
  Object.entries(tags).map(([key, value]) => ({ key, value }));

const fromSfnTags = (
  tags: ReadonlyArray<sfn.Tag> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    (tags ?? [])
      .filter(
        (tag): tag is { key: string; value: string } =>
          typeof tag.key === "string" && typeof tag.value === "string",
      )
      .map((tag) => [tag.key, tag.value]),
  );

export const ActivityProvider = () =>
  Provider.effect(
    Activity,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: Pick<ActivityProps, "activityName">,
      ) {
        return (
          props.activityName ??
          (yield* createPhysicalName({ id, maxLength: 80 }))
        );
      });

      const activityArnOf = (region: string, accountId: string, name: string) =>
        `arn:aws:states:${region}:${accountId}:activity:${name}`;

      const describeOrUndefined = Effect.fn(function* (activityArn: string) {
        return yield* sfn
          .describeActivity({ activityArn })
          .pipe(
            Effect.catchTag("ActivityDoesNotExist", () =>
              Effect.succeed(undefined),
            ),
          );
      });

      const fetchObservedTags = Effect.fn(function* (resourceArn: string) {
        return yield* sfn.listTagsForResource({ resourceArn }).pipe(
          Effect.map((r) => fromSfnTags(r.tags)),
          Effect.catchTag("ResourceNotFound", () =>
            Effect.succeed({} as Record<string, string>),
          ),
        );
      });

      return Activity.Provider.of({
        stables: ["activityName", "activityArn"],

        list: () =>
          Effect.gen(function* () {
            const pages = yield* sfn.listActivities
              .pages({})
              .pipe(Stream.runCollect);
            return Array.from(pages)
              .flatMap((page) => page.activities ?? [])
              .map((activity) => ({
                activityName: activity.name,
                activityArn: activity.activityArn,
              }));
          }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name =
            output?.activityName ?? (yield* createName(id, olds ?? {}));
          const activityArn =
            output?.activityArn ?? activityArnOf(region, accountId, name);
          const found = yield* describeOrUndefined(activityArn);
          if (!found) return undefined;
          const attrs = {
            activityName: found.name,
            activityArn: found.activityArn,
          };
          const tags = yield* fetchObservedTags(activityArn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds ?? {});
          const newName = yield* createName(id, news ?? {});
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
          // tags converge via update
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          // `news` is undefined when the resource is declared without a
          // props argument (`Activity("id")`).
          const props = news ?? {};
          const name = output?.activityName ?? (yield* createName(id, props));
          const activityArn = activityArnOf(region, accountId, name);
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...props.tags, ...internalTags };

          // 1. OBSERVE — cloud state is authoritative.
          const observed = yield* describeOrUndefined(activityArn);

          // 2. ENSURE — createActivity is idempotent for an identical
          //    configuration; ActivityAlreadyExists only fires when the
          //    existing activity differs (encryption config), in which case
          //    we keep the existing one (the ARN is deterministic).
          if (observed === undefined) {
            yield* sfn
              .createActivity({ name, tags: toSfnTags(desiredTags) })
              .pipe(
                Effect.catchTag("ActivityAlreadyExists", () => Effect.void),
              );
          }

          // 3. SYNC TAGS — against OBSERVED cloud tags (create-time tags
          //    only apply on first create; adoption may carry foreign tags).
          const observedTags = yield* fetchObservedTags(activityArn);
          const { upsert, removed } = diffTags(observedTags, desiredTags);
          if (upsert.length > 0) {
            yield* sfn.tagResource({
              resourceArn: activityArn,
              tags: upsert.map(({ Key, Value }) => ({
                key: Key,
                value: Value,
              })),
            });
          }
          if (removed.length > 0) {
            yield* sfn.untagResource({
              resourceArn: activityArn,
              tagKeys: removed,
            });
          }

          yield* session.note(activityArn);
          return { activityName: name, activityArn };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteActivity is idempotent — deleting a non-existent activity
          // succeeds.
          yield* sfn.deleteActivity({ activityArn: output.activityArn });
        }),
      });
    }),
  );

import * as iam from "@distilled.cloud/aws/iam";
import * as sfn from "@distilled.cloud/aws/sfn";
import * as Data from "effect/Data";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import * as Schedule from "effect/Schedule";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource, type ResourceBinding } from "../../Resource.ts";
import { createInternalTags, diffTags, hasAlchemyTags } from "../../Tags.ts";
import { AWSEnvironment } from "../Environment.ts";
import type { PolicyStatement } from "../IAM/Policy.ts";
import type { Providers } from "../Providers.ts";
import { compileProgram, SfnCompileError } from "./Asl/compile.ts";
import type { SfnEffect } from "./Asl/Program.ts";

/**
 * The workflow type. `STANDARD` workflows are durable (up to one year),
 * exactly-once, and support execution history; `EXPRESS` workflows are
 * high-throughput, at-least-once, cheaper, and support synchronous
 * invocation via `StartSyncExecution`.
 */
export type StateMachineType = "STANDARD" | "EXPRESS";

/**
 * Log level for a state machine's CloudWatch Logs configuration.
 */
export type StateMachineLogLevel = "ALL" | "ERROR" | "FATAL" | "OFF";

export interface StateMachineLogging {
  /**
   * Which execution history events are logged.
   */
  level: StateMachineLogLevel;
  /**
   * Whether execution input, data passed between states, and output are
   * included in the log events.
   * @default false
   */
  includeExecutionData?: boolean;
  /**
   * CloudWatch log group ARNs to deliver logs to. The `:*` suffix is
   * appended automatically when missing (the API requires it).
   */
  destinations?: string[];
}

export interface StateMachineProps {
  /**
   * Name of the state machine (1-80 characters; letters, digits, dashes and
   * underscores). If omitted, a deterministic physical name is generated
   * from the app, stage, and logical ID. Changing the name triggers a
   * replacement.
   */
  stateMachineName?: string;
  /**
   * The Amazon States Language (ASL) definition of the workflow. Accepts a
   * plain object (recommended — `Output` values such as function ARNs are
   * resolved before serialization) or a pre-serialized JSON string.
   */
  definition: Record<string, unknown> | string;
  /**
   * Literal substitutions applied to the serialized definition: every
   * occurrence of `${key}` is replaced with the mapped value. Useful when
   * the definition is authored as a static JSON string.
   */
  definitionSubstitutions?: Record<string, string>;
  /**
   * The ARN of an existing IAM role for the state machine to use. When
   * omitted, an execution role is created automatically with
   * `states.amazonaws.com` trust; `lambda:InvokeFunction` is granted for
   * every Lambda function ARN referenced in the definition, and
   * {@link StateMachineProps.policyStatements} are attached as an inline
   * policy.
   */
  roleArn?: string;
  /**
   * Additional IAM policy statements attached to the auto-created
   * execution role (ignored when {@link StateMachineProps.roleArn} is
   * provided). Use this to authorize service integrations such as
   * `sqs:SendMessage` or `dynamodb:PutItem` task states.
   */
  policyStatements?: PolicyStatement[];
  /**
   * The workflow type. Changing the type triggers a replacement.
   * @default "STANDARD"
   */
  type?: StateMachineType;
  /**
   * CloudWatch Logs configuration. Required (with level `ALL`/`ERROR`/
   * `FATAL`) to observe `EXPRESS` workflow executions. The auto-created
   * execution role is granted the CloudWatch Logs delivery permissions
   * automatically.
   */
  logging?: StateMachineLogging;
  /**
   * Whether AWS X-Ray tracing is enabled.
   * @default false
   */
  tracingEnabled?: boolean;
  /**
   * Tags to apply to the state machine. Merged with internal Alchemy tags.
   */
  tags?: Record<string, string>;
}

export interface StateMachine extends Resource<
  "AWS.StepFunctions.StateMachine",
  StateMachineProps,
  {
    /**
     * Physical name of the state machine.
     */
    stateMachineName: string;
    /**
     * ARN of the state machine — pass it to `StartExecution` or reference it
     * from other workflows.
     */
    stateMachineArn: string;
    /**
     * Workflow type (`STANDARD` or `EXPRESS`).
     */
    type: StateMachineType;
    /**
     * ARN of the IAM execution role the workflow assumes.
     */
    roleArn: string;
    /**
     * Name of the auto-created execution role. `undefined` when an explicit
     * {@link StateMachineProps.roleArn} is used.
     */
    roleName: string | undefined;
  },
  {
    /**
     * IAM policy statements bindings attach to the auto-created execution
     * role (e.g. service-integration permissions collected by `fromProgram`).
     */
    policyStatements: PolicyStatement[];
  },
  Providers
> {}

/**
 * The definition failed AWS's `validateStateMachineDefinition` pre-flight
 * check (run in reconcile before create/update). Carries the validator's
 * ERROR-severity diagnostics.
 */
export class InvalidStateMachineDefinition extends Data.TaggedError(
  "InvalidStateMachineDefinition",
)<{
  readonly diagnostics: readonly {
    readonly severity: string;
    readonly code: string;
    readonly message: string;
    readonly location: string | undefined;
  }[];
}> {}

const StateMachineResource = Resource<StateMachine>(
  "AWS.StepFunctions.StateMachine",
);

/**
 * Props for {@link StateMachine.fromProgram} — everything a raw
 * `StateMachine` accepts except the `definition` (which is compiled from
 * the program). User `policyStatements` are merged with the statements the
 * compiler collects from `Sfn.invoke`/`Sfn.integrate` task states.
 */
export interface FromProgramProps extends Omit<
  StateMachineProps,
  "definition" | "definitionSubstitutions"
> {
  /** The typed Step Functions program to compile (built with `Sfn.gen`). */
  program: SfnEffect<any, any>;
}

/**
 * Sugar over the raw `StateMachine` resource: compile a typed `Sfn` program
 * to a plain ASL definition object plus collected IAM policy statements,
 * then register the same `StateMachine` resource the raw path uses. Nothing
 * engine-level — the raw `definition` escape hatch stays first-class.
 */
const fromProgram = (id: string, props: FromProgramProps) =>
  Effect.gen(function* () {
    const { program, policyStatements, ...rest } = props;
    const compiled = yield* Effect.try({
      try: () => compileProgram(program),
      catch: (error) =>
        error instanceof SfnCompileError
          ? error
          : new SfnCompileError({ message: String(error) }),
    });
    return yield* StateMachineResource(id, {
      ...rest,
      definition: compiled.definition,
      policyStatements: [
        ...compiled.policyStatements,
        ...(policyStatements ?? []),
      ],
    });
  });

/**
 * An AWS Step Functions state machine (workflow).
 *
 * `StateMachine` owns the lifecycle of a `STANDARD` or `EXPRESS` workflow.
 * The Amazon States Language definition may be provided as a plain object —
 * `Output` values (like Lambda function ARNs) inside it are resolved before
 * serialization — and an execution role is created automatically unless an
 * explicit `roleArn` is given. Lambda functions referenced in the definition
 * are granted `lambda:InvokeFunction` on the auto-created role.
 * ### Creating State Machines
 * **Example:** Standard Workflow with a Pass State
 * ```typescript
 * import * as StepFunctions from "alchemy/AWS/StepFunctions";
 *
 * const machine = yield* StepFunctions.StateMachine("OrderWorkflow", {
 *   definition: {
 *     StartAt: "Done",
 *     States: {
 *       Done: { Type: "Pass", End: true },
 *     },
 *   },
 * });
 * ```
 *
 * **Example:** Express Workflow
 * ```typescript
 * const machine = yield* StepFunctions.StateMachine("FastWorkflow", {
 *   type: "EXPRESS",
 *   definition: {
 *     StartAt: "Echo",
 *     States: {
 *       Echo: { Type: "Pass", End: true },
 *     },
 *   },
 * });
 * ```
 *
 * ### Orchestrating Lambda Functions
 * Reference a function ARN in a Task state — `lambda:InvokeFunction` is
 * granted on the auto-created execution role automatically.
 *
 * **Example:** Invoke a Lambda Function
 * ```typescript
 * const machine = yield* StepFunctions.StateMachine("Pipeline", {
 *   definition: {
 *     StartAt: "Process",
 *     States: {
 *       Process: {
 *         Type: "Task",
 *         Resource: fn.functionArn,
 *         End: true,
 *       },
 *     },
 *   },
 * });
 * ```
 *
 * ### Service Integrations
 * **Example:** Send a Task Token to SQS (callback pattern)
 * ```typescript
 * const machine = yield* StepFunctions.StateMachine("Callback", {
 *   definition: {
 *     StartAt: "WaitForApproval",
 *     States: {
 *       WaitForApproval: {
 *         Type: "Task",
 *         Resource: "arn:aws:states:::sqs:sendMessage.waitForTaskToken",
 *         Parameters: {
 *           QueueUrl: queue.queueUrl,
 *           MessageBody: { "token.$": "$$.Task.Token" },
 *         },
 *         End: true,
 *       },
 *     },
 *   },
 *   policyStatements: [
 *     {
 *       Effect: "Allow",
 *       Action: ["sqs:SendMessage"],
 *       Resource: [queue.queueArn],
 *     },
 *   ],
 * });
 * ```
 *
 * ### Starting Executions at Runtime
 * Bind execution operations in the init phase and use them in runtime
 * handlers.
 *
 * **Example:** Start a workflow from a handler
 * ```typescript
 * // init
 * const startExecution = yield* StepFunctions.StartExecution(machine);
 *
 * return {
 *   fetch: Effect.gen(function* () {
 *     // runtime
 *     const execution = yield* startExecution({
 *       input: JSON.stringify({ orderId: "123" }),
 *     });
 *     return HttpServerResponse.json({ executionArn: execution.executionArn });
 *   }),
 * };
 * ```
 *
 * **Example:** Run an EXPRESS workflow synchronously
 * ```typescript
 * // init
 * const startSyncExecution = yield* StepFunctions.StartSyncExecution(machine);
 *
 * // runtime
 * const result = yield* startSyncExecution({
 *   input: JSON.stringify({ value: 21 }),
 * });
 * // result.status === "SUCCEEDED", result.output is the workflow output
 * ```
 *
 * ### Typed Programs
 * Author the workflow as a typed `Sfn` program (mirroring Effect's names —
 * `Sfn.gen`, `Sfn.invoke`, `Sfn.when`, `Sfn.forEach`, `Sfn.catchTag`, ...)
 * and compile it with `StateMachine.fromProgram`. The compiler emits a plain
 * ASL definition plus the IAM policy statements its task states need; the
 * raw `definition` path above stays fully usable underneath.
 *
 * **Example:** Compile a typed program
 * ```typescript
 * import { Sfn, StateMachine } from "alchemy/AWS/StepFunctions";
 *
 * const machine = yield* StateMachine.fromProgram("OrderWorkflow", {
 *   type: "EXPRESS",
 *   program: Sfn.gen(function* (input: Sfn.Expr<{ value: number }>) {
 *     const result = yield* Sfn.invoke<{ doubled: number }>(doubler, {
 *       value: input.value,
 *     });
 *     const size = yield* Sfn.when(
 *       Sfn.gt(result.doubled, 10),
 *       Sfn.succeed("big"),
 *       Sfn.succeed("small"),
 *     );
 *     return { doubled: result.doubled, size };
 *   }),
 * });
 * ```
 *
 * @resource
 */
export const StateMachine: typeof StateMachineResource & {
  fromProgram: typeof fromProgram;
} = Object.assign(StateMachineResource, { fromProgram });

/** Normalize a plain or redacted string to its plain value. */
const plain = (value: string | Redacted.Redacted<string>): string =>
  typeof value === "string" ? value : Redacted.value(value);

/** Convert a tag record to the SFN wire shape (lowercase key/value). */
const toSfnTags = (tags: Record<string, string>): sfn.Tag[] =>
  Object.entries(tags).map(([key, value]) => ({ key, value }));

/** Convert an SFN wire tag list back to a record. */
const fromSfnTags = (
  tags: ReadonlyArray<sfn.Tag> | undefined,
): Record<string, string> =>
  Object.fromEntries(
    (tags ?? [])
      .filter(
        (tag): tag is { key: string; value: string } =>
          typeof tag.key === "string" && typeof tag.value === "string",
      )
      .map((tag) => [tag.key, tag.value]),
  );

/**
 * Serialize the desired definition to its ASL JSON string, applying
 * `${key}` substitutions.
 */
const serializeDefinition = (props: {
  definition: Record<string, unknown> | string;
  definitionSubstitutions?: Record<string, string>;
}): string => {
  let definition =
    typeof props.definition === "string"
      ? props.definition
      : JSON.stringify(props.definition, null, 2);
  for (const [key, value] of Object.entries(
    props.definitionSubstitutions ?? {},
  )) {
    definition = definition.replaceAll(`\${${key}}`, value);
  }
  return definition;
};

/**
 * Canonicalize an ASL JSON string for drift comparison (whitespace/key-order
 * insensitive). Falls back to the raw string when unparsable.
 */
const normalizeDefinition = (definition: string): string => {
  try {
    const stable = (value: unknown): unknown =>
      Array.isArray(value)
        ? value.map(stable)
        : value !== null && typeof value === "object"
          ? Object.fromEntries(
              Object.entries(value as Record<string, unknown>)
                .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
                .map(([k, v]) => [k, stable(v)]),
            )
          : value;
    return JSON.stringify(stable(JSON.parse(definition)));
  } catch {
    return definition;
  }
};

/**
 * Extract every Lambda function ARN referenced in a serialized definition so
 * the auto-created execution role can be granted `lambda:InvokeFunction`.
 */
const scanLambdaArns = (definition: string): string[] => {
  const matches = definition.match(
    /arn:aws[a-z0-9-]*:lambda:[a-z0-9-]+:\d{12}:function:[A-Za-z0-9_.-]+(?::[A-Za-z0-9_$-]+)?/g,
  );
  return [...new Set(matches ?? [])];
};

/**
 * CloudWatch Logs delivery permissions required by Step Functions logging.
 * These actions do not support resource-level scoping.
 */
const LOG_DELIVERY_ACTIONS = [
  "logs:CreateLogDelivery",
  "logs:CreateLogStream",
  "logs:GetLogDelivery",
  "logs:UpdateLogDelivery",
  "logs:DeleteLogDelivery",
  "logs:ListLogDeliveries",
  "logs:PutLogEvents",
  "logs:PutResourcePolicy",
  "logs:DescribeResourcePolicies",
  "logs:DescribeLogGroups",
];

/** Map the `logging` prop to the wire `LoggingConfiguration`. */
const toWireLogging = (
  logging: StateMachineLogging | undefined,
): sfn.LoggingConfiguration | undefined =>
  logging === undefined
    ? undefined
    : {
        level: logging.level,
        includeExecutionData: logging.includeExecutionData ?? false,
        destinations: (logging.destinations ?? []).map((arn) => ({
          cloudWatchLogsLogGroup: {
            logGroupArn: arn.endsWith(":*") ? arn : `${arn}:*`,
          },
        })),
      };

/** Compare observed logging configuration against the desired one. */
const loggingDrifted = (
  observed: sfn.LoggingConfiguration | undefined,
  desired: sfn.LoggingConfiguration | undefined,
): boolean => {
  const observedLevel = observed?.level ?? "OFF";
  const desiredLevel = desired?.level ?? "OFF";
  if (observedLevel !== desiredLevel) return true;
  if (desiredLevel === "OFF") return false;
  if (
    (observed?.includeExecutionData ?? false) !==
    (desired?.includeExecutionData ?? false)
  ) {
    return true;
  }
  const arnsOf = (config: sfn.LoggingConfiguration | undefined) =>
    (config?.destinations ?? [])
      .map((d) => d.cloudWatchLogsLogGroup?.logGroupArn ?? "")
      .sort()
      .join(",");
  return arnsOf(observed) !== arnsOf(desired);
};

/**
 * IAM changes (new roles, fresh trust policies) propagate to Step Functions
 * eventually; a create right after role creation can transiently fail with
 * `AccessDeniedException`. Bounded retry, explicitly typed so declaration
 * emit never widens the provider layer (see PATTERNS §7).
 */
const retryWhileRolePropagates = <A, E extends { _tag: string }, R>(
  self: Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> =>
  Effect.retry(self, {
    while: (e) => e._tag === "AccessDeniedException",
    schedule: Schedule.max([Schedule.fixed("2 seconds"), Schedule.recurs(10)]),
  });

/**
 * A state machine of the same name may still be `DELETING` from a prior
 * destroy; creation returns the typed `StateMachineDeleting` until the
 * deletion completes. Bounded retry (~60s).
 */
const retryWhileDeleting = <A, E extends { _tag: string }, R>(
  self: Effect.Effect<A, E, R>,
): Effect.Effect<A, E, R> =>
  Effect.retry(self, {
    while: (e) => e._tag === "StateMachineDeleting",
    schedule: Schedule.max([Schedule.fixed("2 seconds"), Schedule.recurs(30)]),
  });

export const StateMachineProvider = () =>
  Provider.effect(
    StateMachine,
    Effect.gen(function* () {
      const createName = Effect.fn(function* (
        id: string,
        props: Pick<StateMachineProps, "stateMachineName">,
      ) {
        return (
          props.stateMachineName ??
          (yield* createPhysicalName({ id, maxLength: 80 }))
        );
      });

      const createRoleName = (id: string) =>
        createPhysicalName({ id, maxLength: 64 });

      const createPolicyName = (id: string) =>
        createPhysicalName({ id, maxLength: 128 });

      const stateMachineArnOf = (
        region: string,
        accountId: string,
        name: string,
      ) => `arn:aws:states:${region}:${accountId}:stateMachine:${name}`;

      const describeOrUndefined = Effect.fn(function* (
        stateMachineArn: string,
      ) {
        return yield* sfn
          .describeStateMachine({ stateMachineArn })
          .pipe(
            Effect.catchTag("StateMachineDoesNotExist", () =>
              Effect.succeed(undefined),
            ),
          );
      });

      /**
       * Pre-flight the serialized definition through the vendor validator
       * so a definitively invalid document fails with typed diagnostics
       * before any create/update call. Best-effort: if the validate call
       * itself fails (missing IAM permission, throttling), reconcile
       * proceeds and create/updateStateMachine remains the authority.
       */
      const preflightValidateDefinition = Effect.fn(function* (
        definition: string,
        type: StateMachineType,
      ) {
        const report = yield* sfn
          .validateStateMachineDefinition({
            definition,
            type,
            severity: "ERROR",
          })
          .pipe(Effect.catch(() => Effect.succeed(undefined)));
        if (report !== undefined && report.result === "FAIL") {
          return yield* Effect.fail(
            new InvalidStateMachineDefinition({
              diagnostics: report.diagnostics.map((diagnostic) => ({
                severity: diagnostic.severity,
                code: plain(diagnostic.code),
                message: plain(diagnostic.message),
                location:
                  diagnostic.location === undefined
                    ? undefined
                    : plain(diagnostic.location),
              })),
            }),
          );
        }
      });

      const fetchObservedTags = Effect.fn(function* (resourceArn: string) {
        return yield* sfn.listTagsForResource({ resourceArn }).pipe(
          Effect.map((r) => fromSfnTags(r.tags)),
          Effect.catchTag("ResourceNotFound", () =>
            Effect.succeed({} as Record<string, string>),
          ),
        );
      });

      /**
       * Compute the full inline-policy statement list for the auto-created
       * execution role: Lambda invoke grants scanned from the definition,
       * user statements, binding-contributed statements, and CloudWatch
       * Logs delivery permissions when logging is enabled.
       */
      const buildRolePolicyStatements = (
        definition: string,
        news: StateMachineProps,
        bindings: ResourceBinding<StateMachine["Binding"]>[],
      ): PolicyStatement[] => {
        const statements: PolicyStatement[] = [];
        const lambdaArns = scanLambdaArns(definition);
        if (lambdaArns.length > 0) {
          statements.push({
            Effect: "Allow",
            Action: ["lambda:InvokeFunction"],
            Resource: [
              ...lambdaArns,
              // cover qualified invocations (versions/aliases)
              ...lambdaArns
                .filter((arn) => !/:function:[^:]+:/.test(arn))
                .map((arn) => `${arn}:*`),
            ],
          });
        }
        if (news.logging && news.logging.level !== "OFF") {
          statements.push({
            Effect: "Allow",
            Action: LOG_DELIVERY_ACTIONS,
            Resource: ["*"],
          });
        }
        if (news.tracingEnabled) {
          statements.push({
            Effect: "Allow",
            Action: [
              "xray:PutTraceSegments",
              "xray:PutTelemetryRecords",
              "xray:GetSamplingRules",
              "xray:GetSamplingTargets",
            ],
            Resource: ["*"],
          });
        }
        statements.push(...(news.policyStatements ?? []));
        statements.push(...bindings.flatMap((b) => b.data.policyStatements));
        return statements;
      };

      /**
       * Ensure the auto-created execution role exists with the
       * `states.amazonaws.com` trust policy and the desired inline policy.
       * Idempotent: tolerates the role already existing and converges the
       * inline policy on every reconcile.
       */
      const ensureExecutionRole = Effect.fn(function* ({
        id,
        roleName,
        policyName,
        statements,
      }: {
        id: string;
        roleName: string;
        policyName: string;
        statements: PolicyStatement[];
      }) {
        const tags = yield* createInternalTags(id);
        const role = yield* iam
          .createRole({
            RoleName: roleName,
            AssumeRolePolicyDocument: JSON.stringify({
              Version: "2012-10-17",
              Statement: [
                {
                  Effect: "Allow",
                  Principal: { Service: "states.amazonaws.com" },
                  Action: "sts:AssumeRole",
                },
              ],
            }),
            Tags: Object.entries(tags).map(([Key, Value]) => ({ Key, Value })),
          })
          .pipe(
            Effect.catchTag("EntityAlreadyExistsException", () =>
              iam.getRole({ RoleName: roleName }),
            ),
          );

        if (statements.length > 0) {
          yield* iam.putRolePolicy({
            RoleName: roleName,
            PolicyName: policyName,
            PolicyDocument: JSON.stringify({
              Version: "2012-10-17",
              Statement: statements,
            }),
          });
        } else {
          yield* iam
            .deleteRolePolicy({ RoleName: roleName, PolicyName: policyName })
            .pipe(Effect.catchTag("NoSuchEntityException", () => Effect.void));
        }

        return role.Role.Arn;
      });

      return StateMachine.Provider.of({
        stables: ["stateMachineName", "stateMachineArn", "type"],

        list: () =>
          Effect.gen(function* () {
            const pages = yield* sfn.listStateMachines
              .pages({})
              .pipe(Stream.runCollect);
            const items = Array.from(pages).flatMap(
              (page) => page.stateMachines ?? [],
            );
            const results = yield* Effect.forEach(
              items,
              (item) =>
                sfn
                  .describeStateMachine({
                    stateMachineArn: item.stateMachineArn,
                  })
                  .pipe(
                    // name/roleArn are optional on the wire; a machine
                    // missing either cannot be expressed as Attributes.
                    Effect.map((machine) =>
                      machine.name != null &&
                      machine.stateMachineArn != null &&
                      machine.roleArn != null
                        ? {
                            stateMachineName: machine.name,
                            stateMachineArn: machine.stateMachineArn,
                            type: machine.type as StateMachineType,
                            roleArn: machine.roleArn,
                            roleName: undefined as string | undefined,
                          }
                        : undefined,
                    ),
                    Effect.catchTag("StateMachineDoesNotExist", () =>
                      Effect.succeed(undefined),
                    ),
                  ),
              { concurrency: 5 },
            );
            return results.filter(
              (item): item is StateMachine["Attributes"] => item !== undefined,
            );
          }),

        read: Effect.fn(function* ({ id, olds, output }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name =
            output?.stateMachineName ?? (yield* createName(id, olds ?? {}));
          const stateMachineArn =
            output?.stateMachineArn ??
            stateMachineArnOf(region, accountId, name);
          const found = yield* describeOrUndefined(stateMachineArn);
          if (!found || found.status === "DELETING") return undefined;
          const attrs = {
            stateMachineName: found.name,
            stateMachineArn: found.stateMachineArn,
            type: found.type as StateMachineType,
            roleArn: found.roleArn,
            roleName: output?.roleName,
          };
          const tags = yield* fetchObservedTags(stateMachineArn);
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createName(id, olds ?? {});
          const newName = yield* createName(id, news ?? {});
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
          if ((olds?.type ?? "STANDARD") !== (news?.type ?? "STANDARD")) {
            return { action: "replace" } as const;
          }
          // definition/role/logging/tracing/tags converge via update
        }),

        reconcile: Effect.fn(function* ({
          id,
          news,
          output,
          session,
          bindings,
        }) {
          const { accountId, region } = yield* AWSEnvironment.current;
          const name =
            output?.stateMachineName ?? (yield* createName(id, news));
          const stateMachineArn = stateMachineArnOf(region, accountId, name);
          const type = (news.type ?? "STANDARD") as StateMachineType;
          const definition = serializeDefinition(news);
          const desiredLogging = toWireLogging(news.logging);
          const desiredTracing = { enabled: news.tracingEnabled ?? false };
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };

          // Pre-flight: fail with typed diagnostics before touching IAM or
          // the machine when the definition is definitively invalid.
          yield* preflightValidateDefinition(definition, type);

          // Ensure the execution role first — the machine cannot exist
          // without one. Managed unless an explicit roleArn is provided.
          let roleArn = news.roleArn;
          let roleName: string | undefined;
          if (roleArn === undefined) {
            roleName = yield* createRoleName(id);
            const policyName = yield* createPolicyName(id);
            roleArn = yield* ensureExecutionRole({
              id,
              roleName,
              policyName,
              statements: buildRolePolicyStatements(definition, news, bindings),
            });
          }

          // 1. OBSERVE — cloud state is authoritative; `output` is only a
          //    name cache. A machine still DELETING from a prior destroy
          //    must finish deleting before we can recreate it.
          const observed = yield* describeOrUndefined(stateMachineArn).pipe(
            Effect.map((machine) =>
              machine?.status === "DELETING" ? undefined : machine,
            ),
          );

          if (observed === undefined) {
            // 2. ENSURE — create; tolerate the concurrent-create race and
            //    wait out a same-name deletion or IAM propagation delay.
            yield* retryWhileRolePropagates(
              retryWhileDeleting(
                sfn
                  .createStateMachine({
                    name,
                    definition,
                    roleArn,
                    type,
                    loggingConfiguration: desiredLogging,
                    tracingConfiguration: desiredTracing,
                    tags: toSfnTags(desiredTags),
                  })
                  .pipe(
                    Effect.catchTag("StateMachineAlreadyExists", () =>
                      Effect.succeed(undefined),
                    ),
                  ),
              ),
            );
          } else {
            // 3. SYNC — diff OBSERVED cloud state against desired and issue
            //    a single update only when something actually drifted.
            const drifted =
              normalizeDefinition(plain(observed.definition)) !==
                normalizeDefinition(definition) ||
              observed.roleArn !== roleArn ||
              loggingDrifted(observed.loggingConfiguration, desiredLogging) ||
              (observed.tracingConfiguration?.enabled ?? false) !==
                desiredTracing.enabled;
            if (drifted) {
              yield* retryWhileRolePropagates(
                sfn.updateStateMachine({
                  stateMachineArn,
                  definition,
                  roleArn,
                  loggingConfiguration: desiredLogging ?? { level: "OFF" },
                  tracingConfiguration: desiredTracing,
                }),
              );
              // Updates propagate eventually (typically seconds). Poll the
              // describe endpoint (bounded) so subsequent reads observe the
              // new revision; proceed best-effort if it hasn't settled.
              yield* describeOrUndefined(stateMachineArn).pipe(
                Effect.repeat({
                  schedule: Schedule.fixed("1 second"),
                  until: (machine) =>
                    machine === undefined ||
                    normalizeDefinition(plain(machine.definition)) ===
                      normalizeDefinition(definition),
                  times: 20,
                }),
              );
            }
          }

          // 3b. SYNC TAGS — against OBSERVED cloud tags so adoption
          //     converges (create-time tags only apply on first create).
          const observedTags = yield* fetchObservedTags(stateMachineArn);
          const { upsert, removed } = diffTags(observedTags, desiredTags);
          if (upsert.length > 0) {
            yield* sfn.tagResource({
              resourceArn: stateMachineArn,
              tags: upsert.map(({ Key, Value }) => ({
                key: Key,
                value: Value,
              })),
            });
          }
          if (removed.length > 0) {
            yield* sfn.untagResource({
              resourceArn: stateMachineArn,
              tagKeys: removed,
            });
          }

          yield* session.note(stateMachineArn);
          return {
            stateMachineName: name,
            stateMachineArn,
            type,
            roleArn,
            roleName,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deleteStateMachine is idempotent (no error when already gone)
          // and asynchronous — the machine transitions through DELETING.
          yield* sfn.deleteStateMachine({
            stateMachineArn: output.stateMachineArn,
          });

          // Tear down the managed execution role (absent when the user
          // supplied an explicit roleArn). Every step tolerates the role
          // being partially or fully gone already.
          if (output.roleName !== undefined) {
            const roleName = output.roleName;
            yield* iam.listRolePolicies.items({ RoleName: roleName }).pipe(
              Stream.mapEffect((policyName) =>
                iam
                  .deleteRolePolicy({
                    RoleName: roleName,
                    PolicyName: policyName,
                  })
                  .pipe(
                    Effect.catchTag("NoSuchEntityException", () => Effect.void),
                  ),
              ),
              Stream.runDrain,
              Effect.catchTag("NoSuchEntityException", () => Effect.void),
            );
            yield* iam
              .deleteRole({ RoleName: roleName })
              .pipe(
                Effect.catchTag("NoSuchEntityException", () => Effect.void),
              );
          }
        }),
      });
    }),
  );

import * as avp from "@distilled.cloud/aws/verifiedpermissions";
import * as Effect from "effect/Effect";
import * as Redacted from "effect/Redacted";
import * as Stream from "effect/Stream";
import { Unowned } from "../../AdoptPolicy.ts";
import { isResolved } from "../../Diff.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { createInternalTags, diffTags, hasAlchemyTags } from "../../Tags.ts";
import type { Providers } from "../Providers.ts";

/**
 * Schema-validation strictness applied to Cedar policies and templates
 * submitted to the store.
 *
 * - `OFF` — no schema validation.
 * - `STRICT` — policies must reference entity types and actions declared in
 *   the store's schema (requires a schema to be present).
 */
export type ValidationMode = "OFF" | "STRICT";

export interface PolicyStoreProps {
  /**
   * The schema-validation mode for the policy store.
   * @default "OFF"
   */
  validationMode?: ValidationMode;
  /**
   * A human-readable description for the policy store.
   */
  description?: string;
  /**
   * When `ENABLED`, the store cannot be deleted until protection is disabled.
   * Leave `DISABLED` for ephemeral / test stores.
   * @default "DISABLED"
   */
  deletionProtection?: "ENABLED" | "DISABLED";
  /**
   * Tags to apply to the policy store. Merged with internal Alchemy tags.
   */
  tags?: Record<string, string>;
}

export interface PolicyStore extends Resource<
  "AWS.VerifiedPermissions.PolicyStore",
  PolicyStoreProps,
  {
    /**
     * Service-assigned unique ID of the policy store — pass it to
     * {@link Policy}, {@link Schema}, and `IsAuthorized`.
     */
    policyStoreId: string;
    /**
     * ARN of the policy store.
     */
    policyStoreArn: string;
  },
  {},
  Providers
> {}

/**
 * An Amazon Verified Permissions policy store — the container for Cedar
 * policies, policy templates, and a schema. Authorization requests
 * (`IsAuthorized`) are evaluated against all policies in a store.
 * ### Creating a Policy Store
 * **Example:** Basic Policy Store
 * ```typescript
 * import * as AWS from "alchemy/AWS";
 *
 * const store = yield* AWS.VerifiedPermissions.PolicyStore("Store", {
 *   validationMode: "OFF",
 * });
 * ```
 *
 * **Example:** Strict Validation with a Schema
 * ```typescript
 * const store = yield* AWS.VerifiedPermissions.PolicyStore("Store", {
 *   validationMode: "STRICT",
 *   description: "Photo app authorization",
 * });
 *
 * yield* AWS.VerifiedPermissions.Schema("Schema", {
 *   policyStoreId: store.policyStoreId,
 *   cedarJson: JSON.stringify({
 *     PhotoApp: {
 *       entityTypes: { User: {}, Photo: {} },
 *       actions: { viewPhoto: { appliesTo: { principalTypes: ["User"], resourceTypes: ["Photo"] } } },
 *     },
 *   }),
 * });
 * ```
 *
 * @resource
 */
export const PolicyStore = Resource<PolicyStore>(
  "AWS.VerifiedPermissions.PolicyStore",
);

export const PolicyStoreProvider = () =>
  Provider.effect(
    PolicyStore,
    Effect.gen(function* () {
      const observe = Effect.fn(function* (policyStoreId: string) {
        return yield* avp
          .getPolicyStore({ policyStoreId, tags: true })
          .pipe(
            Effect.catchTag("ResourceNotFoundException", () =>
              Effect.succeed(undefined),
            ),
          );
      });

      return PolicyStore.Provider.of({
        stables: ["policyStoreId", "policyStoreArn"],

        list: () =>
          Effect.gen(function* () {
            const pages = yield* avp.listPolicyStores
              .pages({})
              .pipe(Stream.runCollect);
            const items = Array.from(pages).flatMap(
              (page) => page.policyStores ?? [],
            );
            return items.map((item) => ({
              policyStoreId: item.policyStoreId,
              policyStoreArn: item.arn,
            }));
          }),

        read: Effect.fn(function* ({ id, output }) {
          if (output?.policyStoreId === undefined) return undefined;
          const store = yield* observe(output.policyStoreId);
          if (store === undefined) return undefined;
          const attrs = {
            policyStoreId: store.policyStoreId,
            policyStoreArn: store.arn,
          };
          const tags = (store.tags ?? {}) as Record<string, string>;
          return (yield* hasAlchemyTags(id, tags)) ? attrs : Unowned(attrs);
        }),

        // no props trigger replacement — validationMode / description /
        // deletionProtection are all mutable via updatePolicyStore
        diff: Effect.fn(function* ({ news }) {
          if (!isResolved(news)) return undefined;
          return undefined;
        }),

        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const internalTags = yield* createInternalTags(id);
          const desiredTags = { ...news.tags, ...internalTags };
          const validationMode = news.validationMode ?? "OFF";

          // 1. OBSERVE — cloud state is authoritative
          let store =
            output?.policyStoreId !== undefined
              ? yield* observe(output.policyStoreId)
              : undefined;

          // 2. ENSURE — createPolicyStore returns id + arn directly
          if (store === undefined) {
            const created = yield* avp.createPolicyStore({
              validationSettings: { mode: validationMode },
              description: news.description,
              deletionProtection: news.deletionProtection,
              tags: desiredTags,
            });
            store = yield* observe(created.policyStoreId);
            if (store === undefined) {
              return {
                policyStoreId: created.policyStoreId,
                policyStoreArn: created.arn,
              };
            }
          }

          // 3. SYNC — validation / description / deletion protection
          const observedMode = store.validationSettings.mode;
          // description decodes as a Redacted (SensitiveString) — unwrap to
          // compare against the desired plain-string value
          const observedDescription =
            store.description === undefined
              ? undefined
              : Redacted.isRedacted(store.description)
                ? Redacted.value(store.description)
                : store.description;
          const observedProtection = store.deletionProtection ?? "DISABLED";
          const desiredProtection = news.deletionProtection ?? "DISABLED";
          if (
            observedMode !== validationMode ||
            observedDescription !== (news.description ?? undefined) ||
            observedProtection !== desiredProtection
          ) {
            yield* avp.updatePolicyStore({
              policyStoreId: store.policyStoreId,
              validationSettings: { mode: validationMode },
              description: news.description,
              deletionProtection: news.deletionProtection,
            });
          }

          // 3b. SYNC TAGS — diff against OBSERVED cloud tags
          const observedTags = (store.tags ?? {}) as Record<string, string>;
          const { upsert, removed } = diffTags(observedTags, desiredTags);
          if (upsert.length > 0) {
            yield* avp.tagResource({
              resourceArn: store.arn,
              tags: Object.fromEntries(upsert.map((t) => [t.Key, t.Value])),
            });
          }
          if (removed.length > 0) {
            yield* avp.untagResource({
              resourceArn: store.arn,
              tagKeys: removed,
            });
          }

          yield* session.note(store.policyStoreId);
          return {
            policyStoreId: store.policyStoreId,
            policyStoreArn: store.arn,
          };
        }),

        delete: Effect.fn(function* ({ output }) {
          // deletePolicyStore is idempotent — returns 200 even if the store
          // does not exist
          yield* avp.deletePolicyStore({
            policyStoreId: output.policyStoreId,
          });
        }),
      });
    }),
  );

import * as xray from "@distilled.cloud/aws/xray";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Stream from "effect/Stream";
import { isResolved } from "../../Diff.ts";
import { createPhysicalName } from "../../PhysicalName.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import type { Providers } from "../Providers.ts";

export interface ResourcePolicyProps {
  /**
   * Name of the resource policy. Must be unique within the account (each
   * account holds at most 5 X-Ray resource policies).
   *
   * Changing the name replaces the policy.
   * @default ${app}-${stage}-${id}
   */
  policyName?: string;
  /**
   * The IAM resource-based policy document (JSON, maximum 5 KB) granting
   * one or more Amazon Web Services services and accounts permission to
   * access X-Ray — e.g. allowing SNS active tracing to call
   * `xray:PutTraceSegments`. Updated in place.
   */
  policyDocument: string;
  /**
   * Skip the check that prevents locking yourself out of the ability to
   * change the policy in the future.
   * @default false
   */
  bypassPolicyLockoutCheck?: boolean;
}

export interface ResourcePolicy extends Resource<
  "AWS.XRay.ResourcePolicy",
  ResourcePolicyProps,
  {
    /**
     * Name of the resource policy.
     */
    policyName: string;
    /**
     * Revision id of the policy document, changed on every update.
     */
    policyRevisionId: string | undefined;
  },
  never,
  Providers
> {}

/**
 * An X-Ray resource policy — an account-level, resource-based IAM policy
 * that grants other Amazon Web Services services and accounts access to
 * X-Ray, e.g. allowing SNS active tracing to send trace segments.
 *
 * Resource policies are not taggable; ownership is keyed by the
 * deterministic policy name.
 * ### Creating Resource Policies
 * **Example:** Allow SNS active tracing to send trace data
 * ```typescript
 * import * as XRay from "alchemy/AWS/XRay";
 *
 * const policy = yield* XRay.ResourcePolicy("SnsActiveTracing", {
 *   policyDocument: JSON.stringify({
 *     Version: "2012-10-17",
 *     Statement: [
 *       {
 *         Effect: "Allow",
 *         Principal: { Service: "sns.amazonaws.com" },
 *         Action: ["xray:PutTraceSegments", "xray:GetSamplingRules"],
 *         Resource: "*",
 *       },
 *     ],
 *   }),
 * });
 * ```
 *
 * @resource
 */
export const ResourcePolicy = Resource<ResourcePolicy>(
  "AWS.XRay.ResourcePolicy",
);

/** Order-insensitive canonical form of a JSON policy document. */
const canonicalJson = (document: string): string => {
  const sort = (value: unknown): unknown =>
    Array.isArray(value)
      ? value.map(sort)
      : value !== null && typeof value === "object"
        ? Object.fromEntries(
            Object.entries(value as Record<string, unknown>)
              .sort(([a], [b]) => a.localeCompare(b))
              .map(([k, v]) => [k, sort(v)]),
          )
        : value;
  try {
    return JSON.stringify(sort(JSON.parse(document)));
  } catch {
    return document;
  }
};

export const ResourcePolicyProvider = () =>
  Provider.effect(
    ResourcePolicy,
    Effect.gen(function* () {
      const createPolicyName = Effect.fn(function* (
        id: string,
        props: Pick<ResourcePolicyProps, "policyName">,
      ) {
        // X-Ray policy names are limited to 128 characters.
        return (
          props.policyName ??
          (yield* createPhysicalName({ id, maxLength: 128 }))
        );
      });

      // X-Ray has no GetResourcePolicy — observe by enumerating the (at
      // most 5) policies in the account and matching on the policy name.
      const observePolicy = (policyName: string) =>
        xray.listResourcePolicies.items({}).pipe(
          Stream.filter((policy) => policy.PolicyName === policyName),
          Stream.runHead,
          Effect.map(Option.getOrUndefined),
        );

      return ResourcePolicy.Provider.of({
        stables: ["policyName"],
        list: () =>
          Effect.gen(function* () {
            const policies = yield* xray.listResourcePolicies
              .items({})
              .pipe(Stream.runCollect);
            return Array.from(policies).flatMap((policy) =>
              policy.PolicyName
                ? [
                    {
                      policyName: policy.PolicyName,
                      policyRevisionId: policy.PolicyRevisionId,
                    },
                  ]
                : [],
            );
          }),
        read: Effect.fn(function* ({ id, olds, output }) {
          const policyName =
            output?.policyName ?? (yield* createPolicyName(id, olds ?? {}));
          const found = yield* observePolicy(policyName);
          if (found === undefined) return undefined;
          // Resource policies are not taggable — ownership is keyed by the
          // deterministic policy name.
          return { policyName, policyRevisionId: found.PolicyRevisionId };
        }),
        diff: Effect.fn(function* ({ id, news, olds }) {
          if (!isResolved(news)) return undefined;
          const oldName = yield* createPolicyName(id, olds ?? {});
          const newName = yield* createPolicyName(id, news ?? {});
          if (oldName !== newName) {
            return { action: "replace" } as const;
          }
          // fall through: engine default update logic for the document
        }),
        reconcile: Effect.fn(function* ({ id, news, output, session }) {
          const policyName =
            output?.policyName ?? (yield* createPolicyName(id, news));

          // 1. OBSERVE — the live policy list is authoritative.
          const existing = yield* observePolicy(policyName);

          // 2/3. ENSURE + SYNC — `putResourcePolicy` is a true upsert; call
          // it only when the canonical document drifts. The observed
          // revision id guards against concurrent writers; a revision race
          // surfaces as the typed InvalidPolicyRevisionIdException, which we
          // resolve by re-observing and applying once more.
          const putPolicy = (revisionId: string | undefined) =>
            xray
              .putResourcePolicy({
                PolicyName: policyName,
                PolicyDocument: news.policyDocument,
                PolicyRevisionId: revisionId,
                BypassPolicyLockoutCheck: news.bypassPolicyLockoutCheck,
              })
              .pipe(Effect.map((r) => r.ResourcePolicy));

          const policy =
            existing?.PolicyDocument !== undefined &&
            canonicalJson(existing.PolicyDocument) ===
              canonicalJson(news.policyDocument)
              ? existing
              : yield* putPolicy(existing?.PolicyRevisionId).pipe(
                  Effect.catchTag("InvalidPolicyRevisionIdException", () =>
                    observePolicy(policyName).pipe(
                      Effect.flatMap((observed) =>
                        putPolicy(observed?.PolicyRevisionId),
                      ),
                    ),
                  ),
                );

          yield* session.note(policyName);
          return { policyName, policyRevisionId: policy?.PolicyRevisionId };
        }),
        delete: Effect.fn(function* ({ output }) {
          // DeleteResourcePolicy without a revision id skips the revision
          // check and is idempotent — deleting a missing policy succeeds.
          yield* xray.deleteResourcePolicy({
            PolicyName: output.policyName,
          });
        }),
      });
    }),
  );

import * as kv from "@distilled.cloud/cloudflare/kv";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import {
  makeHttpKVNamespaceBinding,
  makeKVAuth,
  makeKVHttpScope,
  toKVNamespaceError,
  type KVAuth,
} from "./NamespaceHttp.ts";
import { NamespaceError } from "./NamespaceTypes.ts";
import { WriteNamespace, type WriteNamespaceClient } from "./WriteNamespace.ts";

/**
 * HTTP-backed implementation of the {@link WriteNamespace} binding.
 *
 * It creates a scoped {@link AccountApiToken} with the `Workers KV Storage
 * Write` permission and writes values via the Cloudflare KV HTTP API.
 */
export const WriteNamespaceHttp = Layer.effect(
  WriteNamespace,
  Effect.suspend(() =>
    makeHttpKVNamespaceBinding({
      permissionGroups: ["Workers KV Storage Write"],
      makeClient: (token, namespaceId) =>
        makeWriteKVHttpClient(makeKVAuth(token), namespaceId),
    }),
  ),
);

export const makeWriteKVHttpClient = (
  auth: KVAuth,
  namespaceId: Effect.Effect<string>,
): WriteNamespaceClient => {
  const { authorize } = auth;
  const scope = makeKVHttpScope(auth, namespaceId);

  return {
    put: ((
      key: string,
      value: string | ArrayBuffer | ArrayBufferView | ReadableStream,
      options?: KVNamespacePutOptions,
    ) =>
      scope.pipe(
        Effect.flatMap(({ accountId, namespaceId }) =>
          toKVBody(value).pipe(
            Effect.flatMap((body) =>
              authorize(
                kv.putNamespaceValue({
                  accountId,
                  namespaceId,
                  keyName: key,
                  value: body,
                  expiration: options?.expiration,
                  expirationTtl: options?.expirationTtl,
                  metadata: options?.metadata,
                }),
              ),
            ),
          ),
        ),
        Effect.mapError(toKVNamespaceError),
        Effect.asVoid,
      )) as any,
    delete: ((key: string) =>
      scope.pipe(
        Effect.flatMap(({ accountId, namespaceId }) =>
          authorize(
            kv.deleteNamespaceValue({ accountId, namespaceId, keyName: key }),
          ),
        ),
        Effect.mapError(toKVNamespaceError),
        Effect.asVoid,
      )) as any,
  };
};

/** Collect a put value into a body accepted by the KV HTTP API. */
const toKVBody = (
  value: string | ArrayBuffer | ArrayBufferView | ReadableStream,
): Effect.Effect<string | Blob, NamespaceError> =>
  Effect.gen(function* () {
    if (typeof value === "string") return value;
    if (value instanceof Blob) return value;
    if (value instanceof ArrayBuffer) return new Blob([value]);
    if (value instanceof ReadableStream) {
      const buffer = yield* Effect.tryPromise({
        try: () => new Response(value as any).arrayBuffer(),
        catch: toKVNamespaceError,
      });
      return new Blob([buffer]);
    }
    const view = value as ArrayBufferView;
    const bytes = new Uint8Array(view.byteLength);
    bytes.set(
      new Uint8Array(
        view.buffer as ArrayBuffer,
        view.byteOffset,
        view.byteLength,
      ),
    );
    return new Blob([bytes]);
  });

import type * as runtime from "@cloudflare/workers-types";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Stream from "effect/Stream";
import { getRawStream } from "../../Util/Stream.ts";
import { makeBucketBinding, makeHelpers } from "./BucketBinding.ts";
import type {
  Conditional,
  MultipartOptions,
  MultipartUpload,
  PutOptions,
  UploadPartOptions,
  UploadedPart,
} from "./BucketTypes.ts";
import { WriteBucket, type WriteBucketClient } from "./WriteBucket.ts";

/**
 * Implementation of the {@link WriteBucket} binding that uses a Worker binding.
 */
export const WriteBucketBinding = Layer.effect(
  WriteBucket,
  Effect.suspend(() => makeBucketBinding({ makeClient: makeWrite })),
);

/** Build the write half of the binding client. */
export const makeWrite = ({
  raw,
  use,
  tryPromise,
  wrapR2Object,
  wrapR2ObjectOrBody,
}: ReturnType<typeof makeHelpers>): WriteBucketClient => {
  const wrapR2MultipartUpload = (
    upload: runtime.R2MultipartUpload,
  ): MultipartUpload => ({
    ...upload,
    raw: upload,
    uploadId: upload.uploadId,
    abort: () => tryPromise(() => upload.abort()),
    complete: (uploadedParts: UploadedPart[]) =>
      tryPromise(() => upload.complete(uploadedParts)).pipe(
        Effect.map(wrapR2Object),
      ),
    uploadPart: (
      partNumber: number,
      value:
        | ReadableStream
        | ArrayBuffer
        | ArrayBufferView
        | string
        | Blob
        | Stream.Stream<Uint8Array>,
      options?: UploadPartOptions,
    ) =>
      tryPromise(() =>
        upload.uploadPart(
          partNumber,
          Stream.isStream(value)
            ? value.pipe(Stream.toReadableStream())
            : (value as any),
          options,
        ),
      ),
  });

  return {
    // @ts-expect-error
    put: (
      key: string,
      value:
        | ReadableStream
        | ArrayBuffer
        | ArrayBufferView
        | string
        | null
        | Blob
        | Stream.Stream<Uint8Array>,
      options?: PutOptions & {
        onlyIf: Conditional | Headers;
        contentLength?: number;
      },
    ) =>
      use((raw) => {
        if (Stream.isStream(value)) {
          // `contentLength` is ours; everything else (checksums, metadata,
          // conditions) is R2's and must reach it on every path.
          const { contentLength, ...r2Options } = options ?? {};
          const rawStream = getRawStream(value);
          if (rawStream) {
            return raw.put(key, rawStream as any, r2Options);
          } else if (!contentLength) {
            throw new Error("Content length is required");
          }
          // R2 needs a known length, so the stream is piped through a fixed
          // length stream.
          const readable = Stream.toReadableStream(value).pipeThrough(
            new FixedLengthStream(contentLength),
          );
          return raw.put(key, readable as any, r2Options);
        }
        return raw.put(key, value as any, options);
      }).pipe(Effect.map(wrapR2ObjectOrBody)) as any,
    delete: (keys: string | string[]) => use((raw) => raw.delete(keys)),
    createMultipartUpload: (key: string, options?: MultipartOptions) =>
      use((raw) => raw.createMultipartUpload(key, options)).pipe(
        Effect.map(wrapR2MultipartUpload),
      ),
    resumeMultipartUpload: (key: string, uploadId: string) =>
      raw.pipe(
        Effect.map((raw) => raw.resumeMultipartUpload(key, uploadId)),
        Effect.map(wrapR2MultipartUpload),
      ),
  };
};

/**
 * Node-side seeding path into the local workerd Secrets Store simulator,
 * built on the runtime's platform proxy (`PlatformProxy.open` — our
 * `getPlatformProxy`).
 *
 * For a `dev:` store there is no cloud API to speak REST to. The local
 * `Secret` provider instead writes values through the runtime's
 * `SecretsStore.admin` hook — the raw KV-namespace view of a store (the
 * equivalent of Miniflare's `getSecretsStoreSecretAPI` admin surface): a
 * scoped platform proxy hosts the binding and Node drives it natively.
 *
 *   Node ── proxy.env.STORE.put(name, value) ──▶ secrets-store service
 *
 * Data lands in the same `{storage}/secrets-store` directory every local
 * worker's `secrets_store_secret` binding reads.
 *
 * NOT exported from `index.ts` — provider-internal scaffolding.
 */
import type * as runtime from "@cloudflare/workers-types";
import { SecretsStore } from "@alchemy.run/cloudflare-runtime/core/bindings";
import { open } from "@alchemy.run/cloudflare-runtime/core/platform-proxy";
import * as Data from "effect/Data";
import * as Effect from "effect/Effect";
import { gatewayName } from "../LocalGateway.ts";

export class LocalSecretsStoreError extends Data.TaggedError(
  "LocalSecretsStoreError",
)<{
  message: string;
  cause?: unknown;
}> {}

/**
 * Boot a scoped platform proxy for `storeId`, hand `use` the store's raw
 * KV-namespace admin surface, and tear the instance down when `use`
 * completes. One proxy boot per operation — slow but correct; callers are
 * provider lifecycle operations, not a request path.
 */
export const withLocalSecretsStore = <A, E, R>(
  storeId: string,
  use: (store: runtime.KVNamespace<string>) => Effect.Effect<A, E, R>,
) =>
  Effect.scoped(
    Effect.gen(function* () {
      const proxy = yield* open({
        name: gatewayName("alchemy-secrets-store-gateway", storeId),
        bindings: [SecretsStore.admin({ binding: "STORE", storeId })],
      });
      const store = (proxy.env as Record<string, unknown>)
        .STORE as runtime.KVNamespace<string>;
      return yield* use(store);
    }),
  );

/** Write a secret value into the local store (idempotent overwrite). */
export const seedLocalSecret = (
  storeId: string,
  secretName: string,
  value: string,
) =>
  withLocalSecretsStore(storeId, (store) =>
    Effect.tryPromise({
      try: () => store.put(secretName, value),
      catch: (cause) =>
        new LocalSecretsStoreError({
          message: `Failed to seed secret "${secretName}" into the local Secrets Store`,
          cause,
        }),
    }),
  );

/** Remove a secret from the local store (idempotent). */
export const deleteLocalSecret = (storeId: string, secretName: string) =>
  withLocalSecretsStore(storeId, (store) =>
    Effect.tryPromise({
      try: () => store.delete(secretName),
      catch: (cause) =>
        new LocalSecretsStoreError({
          message: `Failed to delete secret "${secretName}" from the local Secrets Store`,
          cause,
        }),
    }),
  );

import * as securityTxt from "@distilled.cloud/cloudflare/security-txt";
import * as Effect from "effect/Effect";
import * as Predicate from "effect/Predicate";

import { Unowned } from "../../AdoptPolicy.ts";
import * as Provider from "../../Provider.ts";
import { Resource } from "../../Resource.ts";
import { CloudflareEnvironment } from "../CloudflareEnvironment.ts";
import type { Providers } from "../Providers.ts";
import { listAllZones } from "../Zone/lookup.ts";

const TypeId = "Cloudflare.SecurityTxt.SecurityTxt" as const;
type TypeId = typeof TypeId;

export type Props = {
  /**
   * Zone the security.txt file belongs to. Stable — changing the zone
   * triggers a replacement (the old zone's security.txt is deleted and a
   * new one is created on the new zone).
   */
  zoneId: string;
  /**
   * Whether the security.txt file is served at
   * `/.well-known/security.txt` on the zone. Mutable.
   *
   * @default true
   */
  enabled?: boolean;
  /**
   * Contact channels for security researchers — `mailto:` addresses,
   * `tel:` numbers, or HTTPS URLs (RFC 9116 `Contact` field). Required —
   * Cloudflare rejects a security.txt without it. Mutable.
   */
  contact: string[];
  /**
   * RFC 3339 timestamp after which the file's content should be
   * considered stale (RFC 9116 `Expires` field), e.g.
   * `2027-01-01T00:00:00Z`. Required — Cloudflare rejects a security.txt
   * without it. Mutable.
   */
  expires: string;
  /**
   * URLs of pages crediting security researchers (RFC 9116
   * `Acknowledgments` field). Mutable.
   */
  acknowledgments?: string[];
  /**
   * Canonical URLs where this security.txt file is served (RFC 9116
   * `Canonical` field). Mutable.
   */
  canonical?: string[];
  /**
   * URLs of encryption keys for secure communication (RFC 9116
   * `Encryption` field). Mutable.
   */
  encryption?: string[];
  /**
   * URLs of security-related job openings (RFC 9116 `Hiring` field).
   * Mutable.
   */
  hiring?: string[];
  /**
   * URLs of the vulnerability disclosure policy (RFC 9116 `Policy`
   * field). Mutable.
   */
  policy?: string[];
  /**
   * Comma-separated list of language tags the security team prefers
   * (RFC 9116 `Preferred-Languages` field), e.g. `"en, es"`. Mutable.
   */
  preferredLanguages?: string;
};

export type Attributes = {
  /** Zone the security.txt file belongs to. */
  zoneId: string;
  /** Whether the file is served at `/.well-known/security.txt`. */
  enabled: boolean;
  /** Contact channels for security researchers. */
  contact: string[];
  /** RFC 3339 timestamp after which the file is considered stale. */
  expires: string;
  /** URLs of pages crediting security researchers. */
  acknowledgments: string[] | undefined;
  /** Canonical URLs where this security.txt file is served. */
  canonical: string[] | undefined;
  /** URLs of encryption keys for secure communication. */
  encryption: string[] | undefined;
  /** URLs of security-related job openings. */
  hiring: string[] | undefined;
  /** URLs of the vulnerability disclosure policy. */
  policy: string[] | undefined;
  /** Comma-separated list of preferred language tags. */
  preferredLanguages: string | undefined;
};

export type SecurityTxt = Resource<TypeId, Props, Attributes, never, Providers>;

/**
 * A zone's `security.txt` file
 * (`/zones/{zone_id}/security-center/securitytxt`), served by the
 * Cloudflare edge at `https://<zone>/.well-known/security.txt` per
 * RFC 9116 so security researchers know how to report vulnerabilities.
 *
 * The file is a singleton per zone with true create/delete semantics:
 * creating the resource publishes the file, updating it is a full
 * replace of every field, and destroying it removes the file from the
 * zone entirely.
 *
 * Cloudflare requires the RFC 9116 mandatory fields — `contact` and
 * `expires` — on every write.
 * ### Publishing a security.txt
 * **Example:** Minimal security.txt
 * ```typescript
 * const zone = yield* Cloudflare.Zone.Zone("Site", { name: "example.com" });
 *
 * yield* Cloudflare.SecurityTxt.SecurityTxt("SecurityTxt", {
 *   zoneId: zone.zoneId,
 *   contact: ["mailto:security@example.com"],
 *   expires: "2027-01-01T00:00:00Z",
 * });
 * ```
 *
 * **Example:** Full security.txt with policy and acknowledgments
 * ```typescript
 * yield* Cloudflare.SecurityTxt.SecurityTxt("SecurityTxt", {
 *   zoneId: zone.zoneId,
 *   contact: ["mailto:security@example.com", "https://example.com/report"],
 *   expires: "2027-01-01T00:00:00Z",
 *   policy: ["https://example.com/security-policy"],
 *   acknowledgments: ["https://example.com/hall-of-fame"],
 *   encryption: ["https://example.com/pgp-key.txt"],
 *   preferredLanguages: "en, es",
 * });
 * ```
 *
 * ### Pausing without deleting
 * **Example:** Keep the configuration but stop serving the file
 * ```typescript
 * yield* Cloudflare.SecurityTxt.SecurityTxt("SecurityTxt", {
 *   zoneId: zone.zoneId,
 *   enabled: false,
 *   contact: ["mailto:security@example.com"],
 *   expires: "2027-01-01T00:00:00Z",
 * });
 * ```
 *
 * @see https://developers.cloudflare.com/security-center/infrastructure/security-file/
 *
 * @resource
 * @product Security.txt
 * @category Application Security
 */
export const SecurityTxt = Resource<SecurityTxt>(TypeId, {
  aliases: ["Cloudflare.SecurityTxt"],
});

/**
 * Returns true if the given value is a SecurityTxt resource.
 */
export const isSecurityTxt = (value: unknown): value is SecurityTxt =>
  Predicate.hasProperty(value, "Type") && value.Type === TypeId;

export const SecurityTxtProvider = () =>
  Provider.succeed(SecurityTxt, {
    stables: ["zoneId"],

    list: Effect.fn(function* () {
      const { accountId } = yield* yield* CloudflareEnvironment;
      // There is no account-wide API for this per-zone singleton, and the
      // file is only present on zones that have explicitly configured it —
      // enumerate every zone, read its security.txt, and emit one entry per
      // configured zone (an empty-string sentinel means unconfigured, which
      // `read` treats as absent, so skip it).
      const allZones = yield* listAllZones(accountId);
      const rows = yield* Effect.forEach(
        allZones.map((zone) => zone.id),
        (zoneId) =>
          securityTxt
            .getSecurityTxt({ zoneId })
            .pipe(
              Effect.map((observed) =>
                typeof observed === "string"
                  ? undefined
                  : toAttributes(zoneId, observed),
              ),
            ),
        { concurrency: 10 },
      );
      return rows.filter((row): row is Attributes => row !== undefined);
    }),

    diff: Effect.fn(function* ({ olds = {}, news, output }) {
      const o = olds as Props;
      const n = news as Props;
      // zoneId is Input<string>; compare only once both sides are concrete.
      const oldZoneId =
        output?.zoneId ?? (typeof o.zoneId === "string" ? o.zoneId : undefined);
      if (
        oldZoneId !== undefined &&
        typeof n.zoneId === "string" &&
        oldZoneId !== n.zoneId
      ) {
        return { action: "replace" } as const;
      }
      return undefined;
    }),

    read: Effect.fn(function* ({ output, olds }) {
      const zoneId = output?.zoneId ?? (olds?.zoneId as string | undefined);
      if (!zoneId) return undefined;
      const observed = yield* securityTxt.getSecurityTxt({ zoneId });
      // An unconfigured zone returns an empty-string sentinel — absent.
      if (typeof observed === "string") return undefined;
      const attrs = toAttributes(zoneId, observed);
      // The file is a zone singleton with no ownership markers. On a cold
      // read (no prior output) an existing file was configured outside
      // Alchemy — brand it `Unowned` so the engine refuses to take over
      // unless `--adopt` is set.
      if (output === undefined) return Unowned(attrs);
      return attrs;
    }),

    reconcile: Effect.fn(function* ({ news }) {
      // Inputs have been resolved to concrete strings by Plan.
      const zoneId = news.zoneId as string;
      const desired = desiredAttributes(zoneId, news);

      // 1. Observe — read the live file (an empty-string sentinel means
      //    the zone has no security.txt yet).
      const observed = yield* securityTxt.getSecurityTxt({ zoneId });

      // 2. Sync — PUT is a full replace (a true upsert), so create and
      //    update are the same call. Skip the API entirely when the
      //    observed file already matches the desired one.
      if (
        typeof observed !== "string" &&
        attributesEqual(toAttributes(zoneId, observed), desired)
      ) {
        return toAttributes(zoneId, observed);
      }
      yield* securityTxt.putSecurityTxt({
        zoneId,
        enabled: desired.enabled,
        contact: desired.contact,
        expires: desired.expires,
        acknowledgments: desired.acknowledgments,
        canonical: desired.canonical,
        encryption: desired.encryption,
        hiring: desired.hiring,
        policy: desired.policy,
        preferredLanguages: desired.preferredLanguages,
      });

      // 3. Return — re-read so attributes reflect what Cloudflare stored.
      const final = yield* securityTxt.getSecurityTxt({ zoneId });
      return typeof final === "string" ? desired : toAttributes(zoneId, final);
    }),

    delete: Effect.fn(function* ({ output }) {
      // DELETE on an already-absent security.txt returns success, so the
      // operation is naturally idempotent.
      yield* securityTxt.deleteSecurityTxt({ zoneId: output.zoneId });
    }),
  });

/** Normalize the desired state from input props into the Attributes shape. */
const desiredAttributes = (zoneId: string, news: Props): Attributes => ({
  zoneId,
  enabled: news.enabled ?? true,
  contact: [...news.contact],
  expires: news.expires,
  acknowledgments: nonEmpty(news.acknowledgments),
  canonical: nonEmpty(news.canonical),
  encryption: nonEmpty(news.encryption),
  hiring: nonEmpty(news.hiring),
  policy: nonEmpty(news.policy),
  preferredLanguages:
    news.preferredLanguages === "" ? undefined : news.preferredLanguages,
});

/** Normalize the observed GET response into the Attributes shape. */
const toAttributes = (
  zoneId: string,
  observed: Exclude<securityTxt.GetSecurityTxtResponse, string>,
): Attributes => ({
  zoneId,
  enabled: observed.enabled ?? false,
  contact: [...(observed.contact ?? [])],
  expires: observed.expires ?? "",
  acknowledgments: nonEmpty(observed.acknowledgments),
  canonical: nonEmpty(observed.canonical),
  encryption: nonEmpty(observed.encryption),
  hiring: nonEmpty(observed.hiring),
  // Cloudflare echoes an empty string for an unset Preferred-Languages.
  policy: nonEmpty(observed.policy),
  preferredLanguages:
    observed.preferredLanguages === ""
      ? undefined
      : (observed.preferredLanguages ?? undefined),
});

/** Null/empty list fields normalize to `undefined` (not configured). */
const nonEmpty = (
  values: readonly string[] | null | undefined,
): string[] | undefined =>
  values === null || values === undefined || values.length === 0
    ? undefined
    : [...values];

const listEquals = (
  a: string[] | undefined,
  b: string[] | undefined,
): boolean => {
  if (a === undefined || b === undefined) return a === b;
  return a.length === b.length && a.every((v, i) => v === b[i]);
};

const attributesEqual = (a: Attributes, b: Attributes): boolean =>
  a.zoneId === b.zoneId &&
  a.enabled === b.enabled &&
  a.expires === b.expires &&
  a.preferredLanguages === b.preferredLanguages &&
  listEquals(a.contact, b.contact) &&
  listEquals(a.acknowledgments, b.acknowledgments) &&
  listEquals(a.canonical, b.canonical) &&
  listEquals(a.encryption, b.encryption) &&
  listEquals(a.hiring, b.hiring) &&
  listEquals(a.policy, b.policy);

import type * as cf from "@cloudflare/workers-types";
import * as Effect from "effect/Effect";
import type { RuntimeContext } from "../../RuntimeContext.ts";
import type * as Binding from "../Workers/Binding.ts";
import { makeBindingLayer } from "../Workers/BindingLayer.ts";
import {
  Stream,
  StreamError,
  type StreamClient,
  type StreamVideoClient,
} from "./Stream.ts";

/** The binding value produced by calling {@link Stream} (declared on `env` or `yield*`-ed). */
export type StreamBinding = Binding.Binding<
  Stream["key"],
  StreamClient,
  Stream
>;

/**
 * The layer that provides the Effect-native interface for the Cloudflare
 * Stream binding.
 *
 * Provide it on the Worker effect (`Effect.provide(Cloudflare.Stream.StreamBinding)`)
 * so that yielding a {@link Stream} binding attaches the native `stream`
 * binding to the surrounding Worker at deploy time and, at runtime, resolves to
 * the Effect-native {@link StreamClient} (wrapping the raw `cf.StreamBinding`
 * handle so every operation returns an `Effect`).
 */
export const StreamBinding = makeBindingLayer<
  Stream,
  cf.StreamBinding,
  StreamClient
>(Stream, (raw): StreamClient => {
  const call = <T>(
    fn: (binding: cf.StreamBinding) => Promise<T>,
  ): Effect.Effect<T, StreamError, RuntimeContext> =>
    raw.pipe(Effect.flatMap((binding) => tryPromise(() => fn(binding))));

  const video = (id: string): StreamVideoClient => ({
    id,
    details: () => call((binding) => binding.video(id).details()),
    update: (params) => call((binding) => binding.video(id).update(params)),
    delete: () => call((binding) => binding.video(id).delete()),
    generateToken: () => call((binding) => binding.video(id).generateToken()),
    downloads: {
      generate: (downloadType) =>
        call((binding) => binding.video(id).downloads.generate(downloadType)),
      get: () => call((binding) => binding.video(id).downloads.get()),
      delete: (downloadType) =>
        call((binding) => binding.video(id).downloads.delete(downloadType)),
    },
    captions: {
      upload: (language, input) =>
        call((binding) =>
          binding
            .video(id)
            .captions.upload(language, input as unknown as cf.ReadableStream),
        ),
      generate: (language) =>
        call((binding) => binding.video(id).captions.generate(language)),
      list: (language) =>
        call((binding) => binding.video(id).captions.list(language)),
      delete: (language) =>
        call((binding) => binding.video(id).captions.delete(language)),
    },
  });

  return {
    raw,
    upload: (url, params) => call((binding) => binding.upload(url, params)),
    createDirectUpload: (params) =>
      call((binding) => binding.createDirectUpload(params)),
    video,
    videos: {
      list: (params) => call((binding) => binding.videos.list(params)),
    },
    watermarks: {
      generate: (input, params) =>
        call((binding) =>
          // The runtime accepts a stream or a URL string for the first
          // argument; the published types declare the two as overloads.
          binding.watermarks.generate(
            input as unknown as cf.ReadableStream,
            params,
          ),
        ),
      list: () => call((binding) => binding.watermarks.list()),
      get: (watermarkId) =>
        call((binding) => binding.watermarks.get(watermarkId)),
      delete: (watermarkId) =>
        call((binding) => binding.watermarks.delete(watermarkId)),
    },
  } satisfies StreamClient;
});

const tryPromise = <T>(fn: () => Promise<T>): Effect.Effect<T, StreamError> =>
  Effect.tryPromise({
    try: fn,
    catch: (error: any) =>
      new StreamError({
        message: error?.message ?? "Unknown Cloudflare Stream error",
        code: typeof error?.code === "number" ? error.code : undefined,
        statusCode:
          typeof error?.statusCode === "number" ? error.statusCode : undefined,
        cause: error,
      }),
  });

