export type AccountTagResourceType =
  | "access_application"
  | "access_group"
  | "account"
  | "ai_gateway"
  | "alerting_policy"
  | "alerting_webhook"
  | "cloudflared_tunnel"
  | "d1_database"
  | "durable_object_namespace"
  | "gateway_list"
  | "gateway_rule"
