      }
    }),

    read: Effect.fn(function* ({ output, olds }) {
      const zoneId = output?.zoneId ?? (olds?.zoneId as string | undefined);
      const resourceId =
        output?.resourceId ?? (olds?.resourceId as string | undefined);
      const resourceType = output?.resourceType ?? olds?.resourceType;
      const accessApplicationId =
        output?.accessApplicationId ??
        (olds?.accessApplicationId as string | undefined);
      if (!zoneId || !resourceId || !resourceType) return undefined;

      const observed = yield* resourceTagging
        .getZoneTag({
          zoneId,
          resourceId,
          resourceType,
          accessApplicationId,
        })
        // A 404 means the target resource no longer exists; its tags are
        // gone with it.
        .pipe(
          Effect.catchTag("ZoneTagResourceNotFound", () =>
            Effect.succeed(undefined),
          ),
        );
      if (observed === undefined) return undefined;
      const tags = narrowTags(observed.tags);
      // Cloudflare reports untagged (and unknown) resources as an empty
      // tag set — that is "gone" for this resource.
      if (Object.keys(tags).length === 0) return undefined;

      const attrs: ZoneResourceTagsAttributes = {
        zoneId,
        resourceType,
        resourceId,
        accessApplicationId,
        tags,
        etag: observed.etag,
      };
      // Cold read without prior state: a non-empty tag set exists but we
      // cannot prove we created it (tags carry no ownership markers), so
      // gate takeover behind the adopt policy.
      return output ? attrs : Unowned(attrs);
    }),

    reconcile: Effect.fn(function* ({ news }) {
      // Inputs have been resolved to concrete strings by Plan.
      const zoneId = news.zoneId as string;
      const resourceId = news.resourceId as string;
      const accessApplicationId = news.accessApplicationId as
        | string
        | undefined;
      const desired = resolveTags(news.tags);

      // Observe — cloud state is authoritative. The GET never 404s for a
      // valid-but-untagged resource (it returns an empty tag set), so the
      // same call covers greenfield, update, and adoption. It *does* 404
      // (`ZoneTagResourceNotFound`) when the target resource itself isn't
      // visible yet — a freshly-created DNS record propagates eventually-
      // consistently to the tag index — so bounded-retry until it appears.
      const observed = yield* resourceTagging
        .getZoneTag({
          zoneId,
          resourceId,
          resourceType: news.resourceType,
          accessApplicationId,
        })
        .pipe(Effect.retry(targetVisibleRetry));

      // Sync — PUT is a full replace, so the only decision is whether the
      // observed set already equals the desired set (skip the write).
      if (recordsEqual(narrowTags(observed.tags), desired)) {
        return {
          zoneId,
          resourceType: news.resourceType,
          resourceId,
          accessApplicationId,
          tags: desired,
          etag: observed.etag,
        } satisfies ZoneResourceTagsAttributes;
      }

      const updated = yield* resourceTagging
        .putZoneTag({
          zoneId,
          resourceId,
          resourceType: news.resourceType,
          accessApplicationId,
          tags: desired,
        })
        .pipe(Effect.retry(targetVisibleRetry));
      return {
        zoneId,
        resourceType: news.resourceType,
        resourceId,
        accessApplicationId,
        tags: narrowTags(updated.tags),
        etag: updated.etag,
      } satisfies ZoneResourceTagsAttributes;
    }),

    delete: Effect.fn(function* ({ output }) {
      // The DELETE endpoint is idempotent — Cloudflare returns 204 even
      // for resources that were never tagged.
      yield* resourceTagging.deleteZoneTag({
        zoneId: output.zoneId,
        resourceId: output.resourceId,
        resourceType: output.resourceType,
        accessApplicationId: output.accessApplicationId,
      });
    }),
  });

/**
 * The zone-scoped variants of the `listResourceTaggings` response union —
 * the items that carry a `zoneId` (dns_record, custom_hostname,
 * custom_certificate, managed_client_certificate, access_application_policy,
 * api_gateway_operation, zone). These are exactly the resources this provider
 * manages tags for.
 */
type ZoneScopedTagging = Extract<
  resourceTagging.ListResourceTaggingsResponse["result"][number],
  { zoneId: string }
>;

/** Narrow distilled's `Record<string, unknown>` tag values to strings. */
const narrowTags = (tags: Record<string, unknown>): Record<string, string> =>
  Object.fromEntries(
    Object.entries(tags).map(([k, v]) => [k, String(v)] as const),
  );

/** Resolve `Input<string>` tag values (already concrete after Plan). */
const resolveTags = (
  tags: Record<string, Input<string>>,
): Record<string, string> =>
  Object.fromEntries(
    Object.entries(tags).map(([k, v]) => [k, v as string] as const),
  );

import type {
  CreateTunnelCloudflaredError,
  CreateTunnelCloudflaredRequest,
  CreateTunnelCloudflaredResponse,
  DeleteTunnelCloudflaredError,
  DeleteTunnelCloudflaredResponse,
  PatchTunnelCloudflaredError,
  PatchTunnelCloudflaredRequest,
  PatchTunnelCloudflaredResponse,
  PutTunnelCloudflaredConfigurationError,
  PutTunnelCloudflaredConfigurationRequest,
  PutTunnelCloudflaredConfigurationResponse,
} from "@distilled.cloud/cloudflare/zero-trust";
import * as zeroTrust from "@distilled.cloud/cloudflare/zero-trust";
import * as Effect from "effect/Effect";
import * as Binding from "../../Binding.ts";
import type { Worker } from "../Workers/Worker.ts";
import type { CloudflareEnvironment } from "../CloudflareEnvironment.ts";
import type { RuntimeContext } from "../../RuntimeContext.ts";
import { type TunnelAuth } from "./TunnelBinding.ts";

/**
 * Binding that lets a Worker create, update, and delete Cloudflare Tunnels at
 * runtime.
 *
 * Creates a scoped {@link AccountApiToken} with only the `Cloudflare Tunnel
 * Write` permission and binds its outputs into the Worker (the token value as a
 * `secret_text` binding) so runtime code can authenticate.
 *
 * @remarks
 *
 * `WriteTunnel` is a single identifier that is simultaneously the binding's
 * Context tag, its type, and the callable — `yield* Cloudflare.Tunnel.WriteTunnel()`.
 *
 * ### Mutating tunnels at runtime
 * **Example:** Bind the write client
 * Bind once in the Init phase; every method is available on the returned client.
 * ```typescript
 * const tunnels = yield* Cloudflare.Tunnel.WriteTunnel();
 * ```
 *
 * **Example:** Create a tunnel
 * ```typescript
 * const tunnel = yield* tunnels.create({ name: "on-demand-tunnel" });
 * ```
 *
 * **Example:** Push ingress configuration
 * ```typescript
 * yield* tunnels.putConfiguration(tunnel.id!, {
 *   ingress: [
 *     { hostname: "app.example.com", service: "http://localhost:3000" },
 *     { service: "http_status:404" },
 *   ],
 * });
 * ```
 *
 * **Example:** Rename and delete a tunnel
 * ```typescript
 * yield* tunnels.update(tunnel.id!, { name: "renamed-tunnel" });
 * yield* tunnels.delete(tunnel.id!);
 * ```
 *
 * ### Runtime Layer
 * Provide {@link WriteTunnelBinding} in the Worker's runtime layer.
 * ```typescript
 * Effect.provide(Cloudflare.Tunnel.WriteTunnelBinding)
 * ```
 *
 * @binding
 * @product Tunnels
 * @category Cloudflare One (Zero Trust)
 */
export interface WriteTunnel extends Binding.Service<
  WriteTunnel,
  "Cloudflare.Tunnel.WriteTunnel",
  () => Effect.Effect<WriteTunnelClient, never, Worker | CloudflareEnvironment>
> {}

export const WriteTunnel = Binding.Service<WriteTunnel>(
  "Cloudflare.Tunnel.WriteTunnel",
);

/** Create-tunnel request, minus the account id (supplied by the binding). */
export type CreateTunnelRequest = Omit<
  CreateTunnelCloudflaredRequest,
  "accountId"
>;

/** Update-tunnel request, minus the account id and tunnel id (positional). */
export type UpdateTunnelRequest = Omit<
  PatchTunnelCloudflaredRequest,
  "accountId" | "tunnelId"
>;

/** Tunnel configuration body, minus the account id and tunnel id (positional). */
export type ConfigurationBody = NonNullable<
  PutTunnelCloudflaredConfigurationRequest["config"]
>;

/**
 * Mutating tunnel operations. Backed by the `Cloudflare Tunnel Write`
 * permission group.
 */
export interface WriteTunnelClient {
  /** Create a new tunnel. */
  create(
    request: CreateTunnelRequest,
  ): Effect.Effect<
    CreateTunnelCloudflaredResponse,
    CreateTunnelCloudflaredError,
    RuntimeContext
  >;
  /** Update a tunnel's mutable fields (name, secret). */
  update(
    tunnelId: string,
    request: UpdateTunnelRequest,
  ): Effect.Effect<
    PatchTunnelCloudflaredResponse,
    PatchTunnelCloudflaredError,
    RuntimeContext
  >;
  /** Delete a tunnel by id. */
  delete(
    tunnelId: string,
  ): Effect.Effect<
    DeleteTunnelCloudflaredResponse,
    DeleteTunnelCloudflaredError,
    RuntimeContext
  >;
  /** Replace the remotely-managed configuration (ingress rules) for a tunnel. */
  putConfiguration(
    tunnelId: string,
    config: ConfigurationBody,
  ): Effect.Effect<
    PutTunnelCloudflaredConfigurationResponse,
    PutTunnelCloudflaredConfigurationError,
    RuntimeContext
  >;
}

/** Build the write client over an injectable {@link TunnelAuth}. */
export const writeClient = (auth: TunnelAuth): WriteTunnelClient => {
  const { authorize } = auth;
  return {
    create: Effect.fn("Cloudflare.Tunnel.create")(function* (request) {
      const accountId = yield* auth.accountId;
      return yield* authorize(
        zeroTrust.createTunnelCloudflared({ accountId, ...request }),
      );
    }),
    update: Effect.fn("Cloudflare.Tunnel.update")(
      function* (tunnelId, request) {
        const accountId = yield* auth.accountId;
        return yield* authorize(
          zeroTrust.patchTunnelCloudflared({ accountId, tunnelId, ...request }),
        );
      },
    ),
    delete: Effect.fn("Cloudflare.Tunnel.delete")(function* (tunnelId) {
      const accountId = yield* auth.accountId;
      return yield* authorize(
        zeroTrust.deleteTunnelCloudflared({ accountId, tunnelId }),
      );
    }),
    putConfiguration: Effect.fn("Cloudflare.Tunnel.putConfiguration")(
      function* (tunnelId, config) {
        const accountId = yield* auth.accountId;
        return yield* authorize(
          zeroTrust.putTunnelCloudflaredConfiguration({
            accountId,
            tunnelId,
            config,
          }),
        );
      },
    ),
  };
};

import * as machines from "@distilled.cloud/fly-io/machines";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as FetchHttpClient from "effect/unstable/http/FetchHttpClient";
import { CredentialsFromAmbientOrEnv } from "./Credentials.ts";
import type { Secret } from "./Secret.ts";
import {
  type SecretAuth,
  makeHttpSecretBinding,
  unwrapSecretValue,
} from "./SecretHttp.ts";
import { WriteSecret, type WriteSecretClient } from "./WriteSecret.ts";

/**
 * HTTP implementation of {@link WriteSecret}. Provide it on the
 * {@link Service} or Action Effect.
 *
 *
 * ### Provide the layer
 * **Example:** On an Action
 * ```typescript
 * Effect.gen(function* () {
 *   const secrets = yield* Fly.WriteSecret(ApiToken);
 *   // ...
 * }).pipe(Effect.provide(Fly.WriteSecretHttp))
 * ```
 *
 * @layer
 * @product Secret
 * @provides Fly.WriteSecret
 */
export const WriteSecretHttp = Layer.effect(
  WriteSecret,
  Effect.suspend(() =>
    makeHttpSecretBinding<Secret, WriteSecretClient>({
      makeClient: secretWriteClient,
    }),
  ),
).pipe(
  Layer.provide(FetchHttpClient.layer),
  Layer.provide(CredentialsFromAmbientOrEnv),
);

/** Build the write client over an injectable auth and App name. */
export const secretWriteClient = (
  auth: SecretAuth,
  appName: Effect.Effect<string>,
  _secretName: Effect.Effect<string>,
): WriteSecretClient => {
  const authorize = auth.authorize;
  return {
    create: Effect.fn("Fly.Secret.create")(function* (name, value) {
      return yield* authorize(
        machines.createSecret({
          app_name: yield* appName,
          secret_name: name,
          value: unwrapSecretValue(value),
        }),
      );
    }),
    update: Effect.fn("Fly.Secret.update")(function* (name, value) {
      return yield* authorize(
        machines.updateSecrets({
          app_name: yield* appName,
          values: { [name]: unwrapSecretValue(value) },
        }),
      );
    }),
    delete: Effect.fn("Fly.Secret.delete")(function* (name) {
      return yield* authorize(
        machines.deleteSecret({
          app_name: yield* appName,
          secret_name: name,
        }),
      );
    }),
  };
};

import * as Credentials from "@distilled.cloud/aws/Credentials";
import * as Endpoint from "@distilled.cloud/aws/Endpoint";
import { presignS3Url } from "@distilled.cloud/aws/Presign";
import * as Region from "@distilled.cloud/aws/Region";
import * as S3 from "@distilled.cloud/aws/s3";
import * as Data from "effect/Data";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Redacted from "effect/Redacted";
import * as HttpClient from "effect/unstable/http/HttpClient";

export interface StorageConfig {
  /** Branch-specific, path-style S3 endpoint. */
  endpoint: string;
  /** Signing region returned by Neon. */
  region: string;
  /** Branch credential token ID, not an AWS account key. */
  accessKeyId: string;
  /** Branch credential S3 secret. */
  secretAccessKey: Redacted.Redacted<string>;
}

export class StoragePaginationError extends Data.TaggedError(
  "StoragePaginationError",
)<{ message: string }> {}
export class StorageDeleteError extends Data.TaggedError("StorageDeleteError")<{
  message: string;
}> {}

/** Internal S3 transport. Endpoint overrides retain the bucket in the request path. */
export const storageLayer = (config: StorageConfig) =>
  Layer.mergeAll(
    Endpoint.of(config.endpoint),
    Region.of(config.region as Region.RegionName),
    Layer.succeed(
      Credentials.Credentials,
      Effect.succeed({
        accessKeyId: Redacted.make(config.accessKeyId),
        secretAccessKey: config.secretAccessKey,
        sessionToken: undefined,
        region: config.region as Region.RegionName,
      }),
    ),
  );

export type StoragePutOptions = Pick<
  S3.PutObjectRequest,
  | "ContentType"
  | "CacheControl"
  | "ContentDisposition"
  | "ContentEncoding"
  | "ContentLanguage"
  | "Metadata"
>;

/** Construct clients once; no connections or disposable resources are retained. */
export const makeStorageClient = Effect.fn(function* (
  config: StorageConfig,
  bucket: string,
) {
  const http = yield* HttpClient.HttpClient;
  const layer = Layer.mergeAll(
    storageLayer(config),
    Layer.succeed(HttpClient.HttpClient, http),
  );
  const provide = <A, E, R>(effect: Effect.Effect<A, E, R>) =>
    effect.pipe(Effect.provide(layer));
  return {
    get: (key: string) =>
      provide(S3.getObject({ Bucket: bucket, Key: key })).pipe(
        Effect.catchTag("NoSuchKey", () => Effect.succeed(undefined)),
      ),
    head: (key: string) =>
      provide(S3.headObject({ Bucket: bucket, Key: key })).pipe(
        Effect.catchTag("NotFound", () => Effect.succeed(undefined)),
      ),
    list: (
      options: {
        prefix?: string;
        delimiter?: string;
        cursor?: string;
        limit?: number;
      } = {},
    ) =>
      provide(
        S3.listObjectsV2({
          Bucket: bucket,
          Prefix: options.prefix,
          Delimiter: options.delimiter,
          ContinuationToken: options.cursor,
          MaxKeys: options.limit,
        }),
      ),
    put: (
      key: string,
      body: string | Uint8Array,
      options: StoragePutOptions = {},
    ) =>
      provide(
        S3.putObject({ Bucket: bucket, Key: key, Body: body, ...options }),
      ),
    delete: (key: string) =>
      provide(S3.deleteObject({ Bucket: bucket, Key: key })),
    deleteMany: (keys: string[]) =>
      Effect.gen(function* () {
        const deleted: S3.DeletedObject[] = [];
        // Large Neon batches can exceed the gateway's 60-second request limit.
        for (let offset = 0; offset < keys.length; offset += 100) {
          const result = yield* provide(
            S3.deleteObjects({
              Bucket: bucket,
              Delete: {
                Objects: keys
                  .slice(offset, offset + 100)
                  .map((Key) => ({ Key })),
              },
            }),
          );
          if (result.Errors?.length)
            return yield* new StorageDeleteError({
              message: `S3 refused ${result.Errors.length} object deletions`,
            });
          deleted.push(...(result.Deleted ?? []));
        }
        return { Deleted: deleted } satisfies S3.DeleteObjectsOutput;
      }),
    createMultipartUpload: (key: string, options: StoragePutOptions = {}) =>
      provide(
        S3.createMultipartUpload({ Bucket: bucket, Key: key, ...options }),
      ),
    uploadPart: (
      key: string,
      uploadId: string,
      partNumber: number,
      body: Uint8Array,
    ) =>
      provide(
        S3.uploadPart({
          Bucket: bucket,
          Key: key,
          UploadId: uploadId,
          PartNumber: partNumber,
          Body: body,
        }),
      ),
    completeMultipartUpload: (
      key: string,
      uploadId: string,
      parts: S3.CompletedPart[],
    ) =>
      provide(
        S3.completeMultipartUpload({
          Bucket: bucket,
          Key: key,
          UploadId: uploadId,
          MultipartUpload: { Parts: parts },
        }),
      ),
    abortMultipartUpload: (key: string, uploadId: string) =>
      provide(
        S3.abortMultipartUpload({
          Bucket: bucket,
          Key: key,
          UploadId: uploadId,
        }),
      ).pipe(Effect.catchTag("NoSuchUpload", () => Effect.void)),
    listMultipartUploads: (keyMarker?: string, uploadIdMarker?: string) =>
      provide(
        S3.listMultipartUploads({
          Bucket: bucket,
          KeyMarker: keyMarker,
          UploadIdMarker: uploadIdMarker,
        }),
      ),
    listParts: (key: string, uploadId: string, partNumberMarker?: string) =>
      provide(
        S3.listParts({
          Bucket: bucket,
          Key: key,
          UploadId: uploadId,
          PartNumberMarker: partNumberMarker,
        }),
      ),
    presign: (
      key: string,
      method: "GET" | "PUT",
      options: { expiresIn?: number; contentType?: string } = {},
    ) => provide(presignS3Url({ bucket, key, method, ...options })),
    getTags: () =>
      provide(S3.getBucketTagging({ Bucket: bucket })).pipe(
        Effect.catchTag("NoSuchTagSet", () => Effect.succeed({ TagSet: [] })),
      ),
    putTags: (tags: Record<string, string>) =>
      provide(
        S3.putBucketTagging({
          Bucket: bucket,
          Tagging: {
            TagSet: Object.entries(tags).map(([Key, Value]) => ({
              Key,
              Value,
            })),
          },
        }),
      ),
    getCors: () =>
      provide(S3.getBucketCors({ Bucket: bucket })).pipe(
        Effect.catchTag("NoSuchCORSConfiguration", () =>
          Effect.succeed({ CORSRules: [] }),
        ),
      ),
    putCors: (rules: S3.CORSRule[]) =>
      provide(
        S3.putBucketCors({
          Bucket: bucket,
          CORSConfiguration: { CORSRules: rules },
        }),
      ),
    deleteCors: () => provide(S3.deleteBucketCors({ Bucket: bucket })),
    deleteBucket: () =>
      provide(S3.deleteBucket({ Bucket: bucket })).pipe(
        Effect.catchTag("NoSuchBucket", () => Effect.void),
      ),
  };
});

export type StorageClient = Effect.Success<
  ReturnType<typeof makeStorageClient>
>;

/** Empty only this bucket and branch, checking pagination and partial failures. */
export const emptyStorageBucket = Effect.fn(function* (client: StorageClient) {
  let cursor: string | undefined;
  const seen = new Set<string>();
  do {
    const page = yield* client.list({ cursor, limit: 1000 });
    const keys = (page.Contents ?? []).flatMap((object) =>
      object.Key === undefined ? [] : [object.Key],
    );
    if (keys.length) yield* client.deleteMany(keys);
    cursor = page.IsTruncated ? page.NextContinuationToken : undefined;
    if (page.IsTruncated && (!cursor || seen.has(cursor))) {
      return yield* new StoragePaginationError({
        message: "Object listing did not advance",
      });
    }
    if (cursor) seen.add(cursor);
  } while (cursor);
  let keyMarker: string | undefined;
  let uploadMarker: string | undefined;
  const uploadsSeen = new Set<string>();
  for (;;) {
    const page = yield* client.listMultipartUploads(keyMarker, uploadMarker);
    for (const upload of page.Uploads ?? []) {
      if (upload.Key && upload.UploadId)
        yield* client.abortMultipartUpload(upload.Key, upload.UploadId);
    }
    if (!page.IsTruncated) break;
    keyMarker = page.NextKeyMarker;
    uploadMarker = page.NextUploadIdMarker;
    const marker = `${keyMarker ?? ""}/${uploadMarker ?? ""}`;
    if (!keyMarker || uploadsSeen.has(marker)) {
      return yield* new StoragePaginationError({
        message: "Multipart listing did not advance",
      });
    }
    uploadsSeen.add(marker);
  }
});

import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Stream from "effect/Stream";

import * as SQS from "../AWS/SQS/index.ts";
import { toWireSeconds } from "../Util/Duration.ts";
import { ServerHost } from "./Process.ts";

export const SQSQueueEventSource = Layer.effect(
  SQS.QueueEventSource,
  Effect.gen(function* () {
    const { run } = yield* ServerHost;

    const ReceiveMessage = yield* SQS.ReceiveMessage;
    const DeleteMessageBatch = yield* SQS.DeleteMessageBatch;

    return Effect.fn(function* <StreamReq = never, Req = never>(
      queue: SQS.Queue,
      props: SQS.MessagesProps,
      process: (
        stream: Stream.Stream<SQS.SQSRecord, never, StreamReq>,
      ) => Effect.Effect<void, never, Req | StreamReq>,
    ) {
      const QueueArn = yield* queue.queueArn;

      const receiveMessage = yield* ReceiveMessage(queue);
      const deleteMessageBatch = yield* DeleteMessageBatch(queue);

      yield* run(
        Effect.forever(
          Effect.gen(function* () {
            const queueArn = yield* QueueArn;
            const region = queueArn.split(":")[3]!;
            const result = yield* receiveMessage({
              MaxNumberOfMessages:
                props.maxNumberOfMessages ?? props.batchSize ?? 10,
              WaitTimeSeconds:
                toWireSeconds(props.waitTime) ??
                toWireSeconds(props.maximumBatchingWindow),
            });

            const messages = result.Messages ?? [];
            if (messages.length === 0) return;

            yield* process(
              Stream.fromArray(
                messages.map((msg) => ({
                  messageId: msg.MessageId!,
                  receiptHandle: msg.ReceiptHandle!,
                  body: msg.Body!,
                  attributes: {
                    ApproximateReceiveCount:
                      msg.Attributes?.ApproximateReceiveCount!,
                    SentTimestamp: msg.Attributes?.SentTimestamp!,
                    SenderId: msg.Attributes?.SenderId!,
                    ApproximateFirstReceiveTimestamp:
                      msg.Attributes?.ApproximateFirstReceiveTimestamp!,
                  },
                  messageAttributes: {},
                  md5OfBody: msg.MD5OfBody!,
                  eventSource: "aws:sqs",
                  eventSourceARN: queueArn,
                  awsRegion: region,
                })),
              ),
            ).pipe(Effect.orDie);

            // TODO(sam): only delete messages that were successfully processed
            yield* deleteMessageBatch({
              Entries: messages.map((msg, i) => ({
                Id: msg.MessageId ?? String(i),
                ReceiptHandle: msg.ReceiptHandle!,
              })),
            });
          }),
        ).pipe(Effect.orDie),
      );
    }) as SQS.QueueEventSourceService;
  }),
);

